                    }
                    eofReached = true; // Mark EOF reached for the underlying stream
                } else if (c > 0) {
                    // Data read from underlying stream, process it
                    if (doEncode) {
                        base64.encode(buf, 0, c);
                    } else {
                        base64.decode(buf, 0, c);
                    }
                }
                // If c == 0, no data was read from 'in', but it's not EOF.
                // We'll proceed to check base64.readResults() for any pending data.
