@Override
    public Iterator<CSVRecord> iterator() {
        if (isClosed()) {
            throw new IllegalStateException("CSVParser has been closed and cannot create a new iterator.");
        }

        return new Iterator<CSVRecord>() {
            private CSVRecord currentPeekedRecord; // Renamed for clarity within the iterator

            /**
             * Attempts to read the next record from the parser.
             * Wraps IOException in IllegalStateException for iterator contract.
             *
             * @return The next CSVRecord, or null if end of stream.
             * @throws IllegalStateException If an IOException occurs during reading.
             */
            private CSVRecord getNextRecordSafely() {
                try {
                    return CSVParser.this.nextRecord();
                } catch (final IOException e) {
                    throw new IllegalStateException(
                            "I/O error while reading next CSV record (record number: " + CSVParser.this.getRecordNumber() + ", " +
                            "character offset: " + CSVParser.this.characterOffset + "): " + e.getMessage(), e);
                }
            }

            /**
             * Checks if there is another CSVRecord available.
             * This method peeks ahead to pre-fetch the next record if not already peeked.
             *
             * @return true if there is a next record, false otherwise.
             * @throws IllegalStateException if the underlying CSVParser has been closed.
             */
            @Override
            public boolean hasNext() {
                if (CSVParser.this.isClosed()) {
                    // If closed, no more records can be read.
                    // This check is performed immediately to ensure consistency.
                    return false;
                }
                if (this.currentPeekedRecord == null) {
                    // Only try to fetch if we haven't already peeked for the next record.
                    this.currentPeekedRecord = this.getNextRecordSafely();
                }
                // A non-null peeked record means there's a next element.
                return this.currentPeekedRecord != null;
            }

            /**
             * Returns the next CSVRecord in the iteration.
             *
             * @return the next CSVRecord.
             * @throws NoSuchElementException if the iteration has no more elements,
             *         or if the underlying CSVParser has been closed.
             * @throws IllegalStateException if an I/O error occurs while fetching the next record.
             */
            @Override
            public CSVRecord next() {
                // Always call hasNext() to ensure currentPeekedRecord is properly populated
                // or to throw an immediate exception if the parser is closed or no more elements.
                if (!hasNext()) {
                    // If hasNext() returns false, it means either:
                    // 1. The parser is closed (checked by hasNext())
                    // 2. getNextRecordSafely() returned null, indicating end of stream.
                    // In both cases, there's no element to return.
                    throw new NoSuchElementException("No more CSV records available or parser is closed.");
                }

                // If hasNext() returned true, currentPeekedRecord must be non-null.
                final CSVRecord nextRecord = this.currentPeekedRecord;
                this.currentPeekedRecord = null; // Consume the peeked record
                return nextRecord;
            }

            /**
             * This operation is not supported for CSV iterators as the underlying data stream
             * cannot be modified.
             *
             * @throws UnsupportedOperationException always.
             */
            @Override
            public void remove() {
                throw new UnsupportedOperationException("Removing CSV records from the stream is not supported.");
            }
        };
    }

public static boolean equals(final CharSequence cs1, final CharSequence cs2) {
    // 1. Same instance check: If both references point to the same object, they are equal.
    if (cs1 == cs2) {
        return true;
    }

    // 2. Null check: If one is null and the other isn't (handled by previous check if both are null), they are not equal.
    if (cs1 == null || cs2 == null) {
