    }

    // 3. String optimization: If both are String instances, delegate to String.equals() for efficiency.
    if (cs1 instanceof String && cs2 instanceof String) {
        return cs1.equals(cs2);
    }

    // 4. Length check: For general CharSequence equality, lengths must be identical.
    if (cs1.length() != cs2.length()) {
        return false;
    }

    // 5. Character-by-character comparison: Iterate through characters if lengths are equal and not both Strings.
    // This is the common approach for CharSequence equality when not both are Strings.
    // The original code was attempting to use CharSequenceUtils.regionMatches,
    // which is suitable for comparing *parts* of CharSequences, but not directly for full equality
