    } catch (NumberFormatException ignored) {
        // If it's not a direct integer, try parsing as a double only if it was a PEEKED_NUMBER
        // and check for precision loss. For quoted strings, a NFE means it's not an int.
        if (p == PEEKED_NUMBER) {
            double asDouble = Double.parseDouble(valueToParse); // This can still throw NFE if malformed
            result = (int) asDouble;
            if (result != asDouble) { // Make sure no precision was lost casting to 'int'.
                throw new NumberFormatException("Expected an int but was " + valueToParse
                    + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
            }
            pathIndices[stackSize - 1]++;
            return result;
        } else {
            // For quoted strings, if Integer.parseInt fails, it's not a valid int.
            throw new NumberFormatException("Expected an int but was \"" + valueToParse
                + "\" at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
        }
    }
}

public static WildcardType supertypeOf(Type bound) {
    // 1. Input Validation: Check for null bound
    if (bound == null) {
        throw new NullPointerException("Bound cannot be null for a wildcard supertype.");
    }

    // 2. Input Validation: Check for primitive bound.
    // Gson's internal types often canonicalize primitives to their wrapper types,
    // or explicitly disallow them in generic type contexts.
    // Assuming checkNotPrimitive is available and throws an IllegalArgumentException for primitives.
    // If not, a manual check like 'bound instanceof Class && ((Class<?>) bound).isPrimitive()' would be needed.
    // This method is present in $Gson$Types, suggesting it's the intended way to check.
    checkNotPrimitive(bound);

    Type[] lowerBounds = new Type[] { bound };
    // For "? super T", the upper bound is implicitly Object.class.
    Type[] upperBounds = new Type[] { Object.class };

    // Assuming WildcardTypeImpl is the correct concrete implementation for WildcardType
    return new WildcardTypeImpl(upperBounds, lowerBounds);
}

public static UnsafeAllocator create() {
    // Attempt 1: sun.misc.Unsafe (JVM)
    try {
      Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
      Field theUnsafeField = unsafeClass.getDeclaredField("theUnsafe");
      theUnsafeField.setAccessible(true);
      final Object unsafe = theUnsafeField.get(null);
      final Method allocateInstanceMethod = unsafeClass.getMethod("allocateInstance", Class.class);

      logger.log(Level.FINE, "Using sun.misc.Unsafe for object allocation.");
      return new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new IllegalArgumentException("Class cannot be null for newInstance.");
          }
          return (T) allocateInstanceMethod.invoke(unsafe, c);
        }
      };
    } catch (Throwable e) { // Catch Throwable to also capture Error like NoClassDefFoundError
      logger.log(Level.FINER, "Failed to use sun.misc.Unsafe for object allocation.", e);
    }

    // Attempt 2: Dalvik VM, post-Gingerbread (ObjectStreamClass.getConstructorId/newInstance)
    try {
      Method getConstructorIdMethod = ObjectStreamClass.class
          .getDeclaredMethod("getConstructorId", Class.class);
      getConstructorIdMethod.setAccessible(true);
      // We assume getConstructorId for Object.class provides a generic ID for
      // allocating instances without calling a constructor.
      final int constructorId = (Integer) getConstructorIdMethod.invoke(null, Object.class);

      final Method newInstanceMethod = ObjectStreamClass.class
          .getDeclaredMethod("newInstance", Class.class, int.class);
      newInstanceMethod.setAccessible(true);

      logger.log(Level.FINE, "Using ObjectStreamClass for object allocation (post-Gingerbread Dalvik).");
      return new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new IllegalArgumentException("Class cannot be null for newInstance.");
          }
          return (T) newInstanceMethod.invoke(null, c, constructorId);
        }
      };
    } catch (Throwable e) {
      logger.log(Level.FINER, "Failed to use ObjectStreamClass for object allocation.", e);
    }

    // Attempt 3: Dalvik VM, pre-Gingerbread (ObjectInputStream.newInstance)
    try {
      final Method newInstanceMethod = ObjectInputStream.class
          .getDeclaredMethod("newInstance", Class.class, Class.class);
      newInstanceMethod.setAccessible(true);

      logger.log(Level.FINE, "Using ObjectInputStream for object allocation (pre-Gingerbread Dalvik).");
      return new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new IllegalArgumentException("Class cannot be null for newInstance.");
          }
          // We assume Object.class as the second argument indicates allocation without constructor.
          return (T) newInstanceMethod.invoke(null, c, Object.class);
        }
      };
    } catch (Throwable e) {
      logger.log(Level.FINER, "Failed to use ObjectInputStream for object allocation.", e);
    }

    // Fallback: Give up and throw UnsupportedOperationException
    logger.log(Level.WARNING, "No suitable mechanism found for object allocation without constructor. Falling back to throwing UnsupportedOperationException.");
    return new UnsafeAllocator() {
      @Override
      public <T> T newInstance(Class<T> c) {
        if (c == null) {
          throw new IllegalArgumentException("Class cannot be null for newInstance.");
        }
        throw new UnsupportedOperationException(
            "Cannot allocate instance of " + c.getName() + " without calling its constructor."
                + " All known platform-specific mechanisms failed. "
                + "This typically occurs on highly restricted JVMs or unusual Android environments.");
      }
    };
  }

public JsonWriter value(boolean value) throws IOException {
    writeDeferredName();
