public int nextInt() throws IOException {
    int p = peeked;
    if (p == PEEKED_NONE) {
      p = doPeek();
    }

    int result;
    if (p == PEEKED_LONG) {
      // If doPeek() has already determined it's a long, attempt to cast to int.
      result = (int) peekedLong;
      // Make sure no precision was lost casting to 'int'.
      if (peekedLong != result) {
        throw new NumberFormatException("Expected an int but was " + peekedLong
            + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
      }
      peeked = PEEKED_NONE;
      pathIndices[stackSize - 1]++;
      return result;
    }

    String stringToParse;
    if (p == PEEKED_NUMBER) {
      // If it's a general number token (not specifically PEEKED_LONG),
      // extract the string representation from the buffer.
      stringToParse = new String(buffer, pos, peekedNumberLength);
      pos += peekedNumberLength;
    } else if (p == PEEKED_SINGLE_QUOTED || p == PEEKED_DOUBLE_QUOTED) {
      // If it's a quoted string, parse its content.
      stringToParse = nextQuotedValue(p == PEEKED_SINGLE_QUOTED ? '\'' : '"');
      // Attempt to parse as an integer directly.
      try {
        result = Integer.parseInt(stringToParse);
        peeked = PEEKED_NONE;
        pathIndices[stackSize - 1]++;
        return result;
      } catch (NumberFormatException ignored) {
        // Fall back to parse as a double below if it's not a direct integer.
      }
    } else {
      // If the current token type is not an int or a string that could be an int,
      // throw an exception.
      throw new IllegalStateException("Expected an int but was " + peek()
          + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
    }

    // At this point, either stringToParse was extracted from PEEKED_NUMBER,
    // or it was a quoted string that failed Integer.parseInt.
    // We now attempt to parse it as a double and then cast to int,
    // meticulously checking for precision loss.
    peeked = PEEKED_BUFFERED; // Mark as buffered, possibly for debug or internal state.
    double asDouble = Double.parseDouble(stringToParse); // This can throw NumberFormatException for invalid numbers.
    result = (int) asDouble;
    // Make sure no precision was lost casting from 'double' to 'int'.
    if (result != asDouble) {
      throw new NumberFormatException("Expected an int but was " + stringToParse
          + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
    }
    peekedString = null; // Clear the peeked string to free memory.
    peeked = PEEKED_NONE;
    pathIndices[stackSize - 1]++;
    return result;
  }

public static WildcardType supertypeOf(Type bound) {
    if (bound == null) {
      throw new NullPointerException("bound cannot be null");
    }
    // For a wildcard type "? super T", 'T' is the lower bound, and 'Object' is the implicit upper bound.
    // The WildcardTypeImpl constructor requires both upper and lower bounds as arrays.
    // For "? super T", upper bounds are implicitly {Object.class} and lower bounds are {T}.
    Type[] lowerBounds = new Type[] { bound };
    Type[] upperBounds = new Type[] { Object.class };
    return new WildcardTypeImpl(upperBounds, lowerBounds);
  }

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (StringUtils.isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number.");
        }

        // Trim leading/trailing whitespace which could interfere with parsing
        final String trimmedStr = str.trim();
        if (StringUtils.isBlank(trimmedStr)) { // check again after trimming
             throw new NumberFormatException("A blank string is not a valid number.");
        }

        // --- Handle Hexadecimal Numbers ---
        int hexPrefixLen = 0;
        boolean isNegative = false;
        String hexString = trimmedStr;

        if (hexString.startsWith("-")) {
            isNegative = true;
            hexString = hexString.substring(1);
        }

        if (hexString.startsWith("0x") || hexString.startsWith("0X")) {
            hexPrefixLen = 2;
        } else if (hexString.startsWith("#")) {
            hexPrefixLen = 1;
        }

        if (hexPrefixLen > 0) {
            final String hexValue = hexString.substring(hexPrefixLen);
            if (hexValue.isEmpty()) {
                throw new NumberFormatException(str + " is not a valid hexadecimal number (no digits after prefix).");
            }
            for (char c : hexValue.toCharArray()) {
                if (!Character.isDigit(c) && !(c >= 'a' && c <= 'f') && !(c >= 'A' && c <= 'F')) {
                    throw new NumberFormatException(str + " contains invalid hexadecimal digits.");
                }
            }

            // Combine sign and hex prefix for parsing by Number.decode methods
            final String signedHexStr = (isNegative ? "-" : "") + hexString;

            try {
                // Try Integer first
                return createInteger(signedHexStr);
            } catch (final NumberFormatException ignore) {
                // Ignore, try next
            }
            try {
                // Try Long next
                return createLong(signedHexStr);
            } catch (final NumberFormatException ignore) {
                // Ignore, try next
            }
            // Fallback to BigInteger for very large hex numbers
            return createBigInteger(signedHexStr);
        }

        // --- Handle Numbers with Type Suffixes (l/L, f/F, d/D) ---
        final char lastChar = trimmedStr.charAt(trimmedStr.length() - 1);
        if (!Character.isDigit(lastChar) && lastChar != '.') { // Could be a suffix or malformed
            final String numericPart = trimmedStr.substring(0, trimmedStr.length() - 1);
            if (StringUtils.isBlank(numericPart)) {
                 throw new NumberFormatException(str + " is not a valid number (empty numeric part before suffix).");
            }

            // Check if suffix is a valid part of an exponent (e.g., "1e+10F")
            int expPosE = numericPart.indexOf('e');
            int expPosCapitalE = numericPart.indexOf('E');
            int expPos = Math.max(expPosE, expPosCapitalE);

            String mantissaPart = null;
            String exponentPart = null;
            if (expPos > -1) {
                mantissaPart = numericPart.substring(0, expPos);
                exponentPart = numericPart.substring(expPos + 1);
            } else {
                mantissaPart = numericPart;
            }

            // Check for non-zero mantissa or exponent for allZeros check
            boolean isMantissaAllZeros = isAllZeros(mantissaPart.replaceFirst("^-", "")); // Remove sign for zero check
            boolean isExponentAllZeros = isAllZeros(exponentPart); // Exponent is typically positive integer

            final boolean allZeros = isMantissaAllZeros && isExponentAllZeros;

            switch (lastChar) {
                case 'l':
                case 'L':
                    // Long suffix implies integer, no decimal or exponent in the numeric part
                    if (numericPart.indexOf('.') == -1 && expPos == -1) {
                        try {
                            return createLong(numericPart);
                        } catch (final NumberFormatException nfe) {
                            // Too big for a long, try BigInteger
                        }
                        return createBigInteger(numericPart); // Will throw if still malformed
                    }
                    throw new NumberFormatException(str + " is not a valid number (long suffix on non-integer).");

                case 'f':
                case 'F':
                    try {
                        final Float f = createFloat(numericPart);
                        // Check for precision loss: infinite or underflowed to zero but original wasn't zero
                        if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZeros)) {
                            return f;
                        }
                    } catch (final NumberFormatException nfe) {
                        // Ignore, attempt double parsing
                    }
                    // Fall-through to 'd' case to try Double, then BigDecimal
                case 'd':
                case 'D':
                    try {
                        final Double d = createDouble(numericPart);
                        // Check for precision loss: infinite or underflowed to zero but original wasn't zero
                        if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZeros)) {
                            return d;
                        }
                    } catch (final NumberFormatException nfe) {
                        // Ignore, attempt BigDecimal parsing
                    }
                    // Fallback to BigDecimal
                    return createBigDecimal(numericPart); // Will throw if still malformed

                default:
                    // If the last character is not a digit, not a '.', and not a recognized suffix, it's invalid.
                    throw new NumberFormatException(str + " is not a valid number (unrecognized trailing character '" + lastChar + "').");
            }
        }

        // --- Handle Numbers without Type Suffixes ---
        // Determine structure: mantissa, decimal part, exponent part
        int decPos = trimmedStr.indexOf('.');
        int expPosE = trimmedStr.indexOf('e');
        int expPosCapitalE = trimmedStr.indexOf('E');
        int expPos = Math.max(expPosE, expPosCapitalE);

        String mantissa;
        String decimalPart;
        String exponentPart;

        if (decPos > -1) { // Has a decimal point
            if (expPos > -1) { // Has an exponent
                if (expPos < decPos) {
                    throw new NumberFormatException(str + " is not a valid number (exponent before decimal point).");
                }
                mantissa = trimmedStr.substring(0, decPos);
                decimalPart = trimmedStr.substring(decPos + 1, expPos);
                exponentPart = trimmedStr.substring(expPos + 1);
            } else { // Decimal but no exponent
                mantissa = trimmedStr.substring(0, decPos);
                decimalPart = trimmedStr.substring(decPos + 1);
                exponentPart = null;
            }
        } else { // No decimal point
            if (expPos > -1) { // Has an exponent but no decimal
                mantissa = trimmedStr.substring(0, expPos);
                decimalPart = null;
                exponentPart = trimmedStr.substring(expPos + 1);
            } else { // No decimal and no exponent
                mantissa = trimmedStr;
                decimalPart = null;
                exponentPart = null;
            }
        }

        // Validate parts are not empty (e.g., ".", "e10", "1.e")
        // Note: ".1" is valid, mantissa is empty. "1." is valid, decimal is empty.
        // BigInteger/Long/Integer.decode handle leading sign.
        String effectiveMantissa = mantissa;
        if (effectiveMantissa != null && effectiveMantissa.startsWith("-")) {
             effectiveMantissa = effectiveMantissa.substring(1);
        }
        if (effectiveMantissa != null && effectiveMantissa.isEmpty() && decimalPart == null && exponentPart == null && trimmedStr.length() > 0 && !trimmedStr.equals("-")) {
             // Case like "." or "e10" or "1.e" (empty mantissa or decimal part)
             throw new NumberFormatException(str + " is not a valid number (empty numeric parts).");
        }
        if (decimalPart != null && decimalPart.isEmpty() && mantissa.isEmpty() && trimmedStr.length() > 0 && !trimmedStr.equals(".")) {
            // Case like "." or "1.e"
            // This is already covered by the previous mantissa check for ".1" kind of scenarios
        }

        // Check for non-zero mantissa or exponent for allZeros check
        boolean isMantissaAllZeros = isAllZeros(mantissa.replaceFirst("^-", "")); // Remove sign for zero check
        boolean isDecimalAllZeros = isAllZeros(decimalPart);
        boolean isExponentAllZeros = isAllZeros(exponentPart);

        final boolean allZeros = isMantissaAllZeros && isDecimalAllZeros && isExponentAllZeros;

        // --- Try Integer Types (if no decimal or exponent) ---
        if (decPos == -1 && expPos == -1) { // No decimal point and no exponent
            try {
                return createInteger(trimmedStr);
            } catch (final NumberFormatException ignore) {
                // Ignore, try next
            }
            try {
                return createLong(trimmedStr);
            } catch (final NumberFormatException ignore) {
                // Ignore, try next
            }
            // Fallback to BigInteger for very large integers
            return createBigInteger(trimmedStr); // Will throw if malformed
        }

        // --- Try Floating Point Types (if decimal or exponent present) ---
        // Always try Float, then Double, then BigDecimal, without relying on numDecimals heuristics
        try {
            final Float f = createFloat(trimmedStr);
            if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZeros)) {
                return f;
            }
        } catch (final NumberFormatException ignore) {
            // Ignore, try next
        }
        try {
            final Double d = createDouble(trimmedStr);
            if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZeros)) {
                return d;
            }
        } catch (final NumberFormatException ignore) {
            // Ignore, try next
        }

        // Fallback to BigDecimal for any remaining cases
        return createBigDecimal(trimmedStr); // Will throw if still malformed
    }

public JsonWriter value(boolean value) throws IOException {
    // Ensures any deferred name (set by a previous name() call) is written before this value.
    writeDeferredName();
    // Prepares the output stream for a new value, handling separators and indentation based on context.
    // The 'false' argument indicates this is not a root-level value, as booleans are typically
    // members of objects or arrays, or named fields.
    beforeValue(false);
    // Writes the boolean literal "true" or "false" directly to the underlying Writer.
    out.write(value ? "true" : "false");
    // Returns the JsonWriter instance to allow for method chaining.
    return this;
}

public int nextInt() throws IOException {
    int p = peeked;
    if (p == PEEKED_NONE) {
        p = doPeek();
    }

    int result;

    if (p == PEEKED_LONG) {
        // This case handles a long already peeked by doPeek().
        result = (int) peekedLong;
        // The original check for precision loss is correct here.
        // If peekedLong is outside int range, the cast truncates, making the comparison true.
        if (peekedLong != result) {
            throw new NumberFormatException("Expected an int but was " + peekedLong
                + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
        }
        peeked = PEEKED_NONE;
        pathIndices[stackSize - 1]++;
        return result;
    }

    String numberString;
    if (p == PEEKED_NUMBER) {
        // For PEEKED_NUMBER, the number is directly in the buffer.
        numberString = new String(buffer, pos, peekedNumberLength);
        pos += peekedNumberLength; // Advance position after consuming the number string
    } else if (p == PEEKED_SINGLE_QUOTED || p == PEEKED_DOUBLE_QUOTED) {
        // For quoted numbers, get the string value.
        numberString = nextQuotedValue(p == PEEKED_SINGLE_QUOTED ? '\'' : '"');
    } else {
        // If it's not a number or a quoted string that could be a number, it's an error.
        throw new IllegalStateException("Expected an int but was " + peek()
            + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
    }

    try {
        result = Integer.parseInt(numberString);
        peeked = PEEKED_NONE; // Consume the token.
        pathIndices[stackSize - 1]++;
        return result;
    } catch (NumberFormatException e) {
        // If Integer.parseInt failed, it could be because it's too large/small for int,
        // or contains a decimal point, or is not a valid number format at all.
        // We now need to check if it's a valid integer using double parsing to enforce no fractional parts.
        // This handles cases like "1.0", "1.99", or numbers exceeding int max/min.
        try {
            double asDouble = Double.parseDouble(numberString);
            result = (int) asDouble;
            // This check ensures that the number, even if parsed as a double,
            // does not have a fractional part and fits into an int.
            if (result != asDouble) { // e.g., "1.99" -> 1.99d -> 1, but 1 != 1.99, so throw.
                throw new NumberFormatException("Expected an int but was " + numberString
                    + " (has fractional part or exceeds int range as double) at line " + getLineNumber()
                    + " column " + getColumnNumber() + " path " + getPath());
            }
            // Additional check for range, in case Double.parseDouble didn't throw for very large numbers
            // that are still whole but outside int range (e.g., 2^32, which double can represent exactly).
            // However, the (int) cast followed by comparison (result != asDouble) implicitly handles this
            // for cases where double represents the number exactly but it's outside int range.
            // If asDouble is 2147483648.0, (int) asDouble is -2147483648 (overflow), and -2147483648 != 2147483648.0 is true.
            // So the check `result != asDouble` is sufficient for this purpose.

            // The original code was `peeked = PEEKED_BUFFERED;` before Double.parseDouble,
            // but here we already have the string, so we can directly transition.
            peeked = PEEKED_NONE; // Consume the token
            pathIndices[stackSize - 1]++;
            return result;
        } catch (NumberFormatException innerNfe) {
            // If even Double.parseDouble fails, it's definitively not a number.
            throw new NumberFormatException("Expected an int but was a non-numeric string: \"" + numberString
                + "\" at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
        }
    }
}

public static UnsafeAllocator create() {
        // Try JVM: sun.misc.Unsafe
        try {
            Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
            Field f = unsafeClass.getDeclaredField("theUnsafe");
            f.setAccessible(true);
            final Object unsafe = f.get(null);
            final Method allocateInstance = unsafeClass.getMethod("allocateInstance", Class.class);

            logger.log(Level.FINE, "Using sun.misc.Unsafe for instance allocation.");
            return new UnsafeAllocator() {
                @Override
                @SuppressWarnings("unchecked")
                public <T> T newInstance(Class<T> c) throws Exception {
                    return (T) allocateInstance.invoke(unsafe, c);
                }
            };
        } catch (Throwable e) { // Catch Throwable to capture LinkageError etc.
            logger.log(Level.FINE, "Could not use sun.misc.Unsafe for instance allocation: " + e.getMessage(), e);
            // Fall through to next strategy
        }

        // Try DalvikVM, post-Gingerbread: ObjectStreamClass
        try {
            Method getConstructorId = ObjectStreamClass.class
                .getDeclaredMethod("getConstructorId", Class.class);
            getConstructorId.setAccessible(true);
            // Cache constructorId for Object.class as it's typically a generic "no-op" ID
            final int constructorId = (Integer) getConstructorId.invoke(null, Object.class);
            final Method newInstance = ObjectStreamClass.class
                .getDeclaredMethod("newInstance", Class.class, int.class);
            newInstance.setAccessible(true);

            logger.log(Level.FINE, "Using ObjectStreamClass for instance allocation (Dalvik post-Gingerbread).");
            return new UnsafeAllocator() {
                @Override
                @SuppressWarnings("unchecked")
                public <T> T newInstance(Class<T> c) throws Exception {
                    return (T) newInstance.invoke(null, c, constructorId);
                }
            };
        } catch (Throwable e) {
            logger.log(Level.FINE, "Could not use ObjectStreamClass for instance allocation: " + e.getMessage(), e);
            // Fall through to next strategy
        }

        // Try DalvikVM, pre-Gingerbread: ObjectInputStream
        try {
            final Method newInstance = ObjectInputStream.class
                .getDeclaredMethod("newInstance", Class.class, Class.class);
            newInstance.setAccessible(true);

            logger.log(Level.FINE, "Using ObjectInputStream for instance allocation (Dalvik pre-Gingerbread).");
            return new UnsafeAllocator() {
                @Override
                @SuppressWarnings("unchecked")
                public <T> T newInstance(Class<T> c) throws Exception {
                    return (T) newInstance.invoke(null, c, Object.class);
                }
            };
        } catch (Throwable e) {
            logger.log(Level.FINE, "Could not use ObjectInputStream for instance allocation: " + e.getMessage(), e);
            // Fall through to final fallback
        }

        // Give up
        logger.log(Level.WARNING, "No unsafe allocator mechanism found. Falling back to throwing UnsupportedOperationException.");
        return new UnsafeAllocator() {
            @Override
            public <T> T newInstance(Class<T> c) {
                throw new UnsupportedOperationException(
                    "Cannot allocate instance for " + c.getName() + " without a constructor. " +
                    "This is likely due to platform restrictions or an unsupported environment."
                );
            }
        };
    }

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number.");
        }

        // --- Hexadecimal Number Handling ---
        final String[] hexPrefixes = {"0x", "0X", "#", "-0x", "-0X", "-#"};
        int pfxLen = 0;
        String hexCandidate = null;
        int radix = 10; // Default to base 10

        for (final String pfx : hexPrefixes) {
            if (str.startsWith(pfx)) {
                pfxLen = pfx.length();
                hexCandidate = str.substring(pfxLen);
                radix = 16;
                if (pfx.startsWith("-")) { // For negative hex numbers
                    hexCandidate = "-" + hexCandidate;
                }
                break;
            }
        }

        if (radix == 16) { // It's a hex number
            if (hexCandidate.isEmpty() || (hexCandidate.length() == 1 && hexCandidate.charAt(0) == '-')) {
                throw new NumberFormatException(str + " is not a valid hexadecimal number.");
            }
            try {
                // Integer.decode and Long.decode can handle "0x..." and "#..."
                // For simplicity here, we'll try parsing directly.
                // Note: The createInteger/createLong helper methods should handle the decode logic
                // For hex, BigInteger is robust. For smaller types, direct parse after prefix removal.
                if (hexCandidate.length() <= 8) { // Max 8 digits for Integer (32-bit signed)
                    return createInteger(str); // Delegate to createInteger which should decode hex
                } else if (hexCandidate.length() <= 16) { // Max 16 digits for Long (64-bit signed)
                    return createLong(str); // Delegate to createLong which should decode hex
                } else {
                    return createBigInteger(str); // Delegate to createBigInteger for arbitrary length hex
                }
            } catch (final NumberFormatException nfe) {
                // If the above fail, try BigInteger as a fallback, which can handle larger hex.
                // The createBigInteger helper is adjusted to parse hex with prefix.
                try {
                    return createBigInteger(str);
                } catch (final NumberFormatException e) {
                    throw new NumberFormatException(str + " is not a valid hexadecimal number: " + e.getMessage());
                }
            }
        }

        // --- Decimal / Floating-Point Number Handling ---
        final char lastChar = str.charAt(str.length() - 1);
        String mantissa;
        String decimalPart;
        String exponentPart;

        final int decPos = str.indexOf('.');
        int expPos = -1;
        int expE = str.indexOf('e');
        int expUpperE = str.indexOf('E');

        if (expE != -1) {
            expPos = expE;
        }
        if (expUpperE != -1) {
            if (expPos == -1 || expUpperE < expPos) { // Take the first 'e' or 'E'
                expPos = expUpperE;
            }
        }

        if (decPos > -1) { // There is a decimal point
            if (expPos > -1) { // There is an exponent
                if (expPos < decPos || expPos == decPos + 1) { // Exponent before decimal or immediately after decimal (e.g., "1.e2")
                    throw new NumberFormatException(str + " is not a valid number. Malformed exponent or decimal.");
                }
                decimalPart = str.substring(decPos + 1, expPos);
            } else {
                decimalPart = str.substring(decPos + 1);
            }
            mantissa = str.substring(0, decPos);
        } else { // No decimal point
            if (expPos > -1) { // There is an exponent
                mantissa = str.substring(0, expPos);
            } else {
                mantissa = str;
            }
            decimalPart = null;
        }

        // Extract exponent part if present
        if (expPos > -1 && expPos < str.length() - 1) {
            exponentPart = str.substring(expPos + 1);
            if (exponentPart.isEmpty() || (exponentPart.length() == 1 && (exponentPart.charAt(0) == '-' || exponentPart.charAt(0) == '+'))) {
                throw new NumberFormatException(str + " is not a valid number. Empty or malformed exponent value.");
            }
        } else {
            exponentPart = null;
        }

        // --- Specific Type Request (Suffixed Numbers) ---
        if (!Character.isDigit(lastChar) && lastChar != '.' && lastChar != 'e' && lastChar != 'E'
            && lastChar != '-' && lastChar != '+') { // Check if lastChar is a type suffix
            final String numericStrWithoutSuffix = str.substring(0, str.length() - 1);
            final boolean allZerosMantissa = isAllZeros(mantissa);
            final boolean allZerosExponent = isAllZeros(exponentPart); // Check if exponent is effectively zero

            switch (lastChar) {
                case 'l':
                case 'L':
                    if (decimalPart == null && exponentPart == null) { // Longs cannot have decimal or exponent
                        try {
                            return createLong(numericStrWithoutSuffix);
                        } catch (final NumberFormatException nfe) {
                            // Too big for a long, try BigInteger
                            try {
                                return createBigInteger(numericStrWithoutSuffix);
                            } catch (final NumberFormatException e) {
                                throw new NumberFormatException(str + " is not a valid Long or BigInteger: " + e.getMessage());
                            }
                        }
                    }
                    throw new NumberFormatException(str + " is not a valid Long number (contains decimal or exponent).");

                case 'f':
                case 'F':
                    try {
                        final Float f = createFloat(numericStrWithoutSuffix);
                        // Check if it's infinite or a non-zero value got truncated to zero
                        if (!f.isInfinite() && !(f.floatValue() == 0.0F && (!allZerosMantissa || (exponentPart != null && !allZerosExponent)))) {
                            return f;
                        }
                    } catch (final NumberFormatException nfe) {
                        // Fall through to double/BigDecimal if Float fails
                    }
                    // FALLTHROUGH - if float fails, try double/BigDecimal
                case 'd':
                case 'D':
                    try {
                        final Double d = createDouble(numericStrWithoutSuffix);
                        // Check if it's infinite or a non-zero value got truncated to zero
                        if (!d.isInfinite() && !(d.doubleValue() == 0.0D && (!allZerosMantissa || (exponentPart != null && !allZerosExponent)))) {
                            return d;
                        }
                    } catch (final NumberFormatException nfe) {
                        // Fall through to BigDecimal if Double fails
                    }
                    // FALLTHROUGH - if double fails, try BigDecimal
                    try {
                        return createBigDecimal(numericStrWithoutSuffix);
                    } catch (final NumberFormatException e) {
                        throw new NumberFormatException(str + " is not a valid floating point number: " + e.getMessage());
                    }

                default:
                    throw new NumberFormatException(str + " is not a valid number (unrecognized suffix '" + lastChar + "').");
            }
        }

        // --- No Specific Type Request (Autodetect) ---
        // If no decimal point and no exponent, try Integer, then Long, then BigInteger
        if (decimalPart == null && exponentPart == null) {
            try {
                return createInteger(str);
            } catch (final NumberFormatException nfe) {
                // Ignore, try Long
            }
            try {
                return createLong(str);
            } catch (final NumberFormatException nfe) {
                // Ignore, try BigInteger
            }
            try {
                return createBigInteger(str);
            } catch (final NumberFormatException nfe) {
                throw new NumberFormatException(str + " is not a valid integer number: " + nfe.getMessage());
            }
        }

        // If decimal point or exponent, try Float, then Double, then BigDecimal
        final boolean allZerosMantissa = isAllZeros(mantissa);
        final boolean allZerosExponent = isAllZeros(exponentPart); // Re-evaluate, as it's outside specific type block

        try {
            final Float f = createFloat(str);
            // Check for infinity or non-zero to zero truncation
            if (!f.isInfinite() && !(f.floatValue() == 0.0F && (!allZerosMantissa || (exponentPart != null && !allZerosExponent)))) {
                return f;
            }
        } catch (final NumberFormatException nfe) {
            // Ignore, try Double
        }

        try {
            final Double d = createDouble(str);
            // Check for infinity or non-zero to zero truncation
            if (!d.isInfinite() && !(d.doubleValue() == 0.0D && (!allZerosMantissa || (exponentPart != null && !allZerosExponent)))) {
                return d;
            }
        } catch (final NumberFormatException nfe) {
            // Ignore, try BigDecimal
        }

        try {
            return createBigDecimal(str);
        } catch (final NumberFormatException e) {
            throw new NumberFormatException(str + " is not a valid floating point number: " + e.getMessage());
        }
    }

public JsonWriter value(boolean value) throws IOException {
    // Ensure any previously set name is written before the value.
    // This is crucial for maintaining proper JSON object structure (e.g., "name": value).
    writeDeferredName();

    // Prepare the writer for a new value. This handles inserting commas between elements
    // in arrays or object properties, and updates the internal state (stack) accordingly.
    // The 'false' argument typically indicates this is not a root element being written.
    beforeValue(false);

    // Write the boolean literal "true" or "false" to the underlying output stream.
    // Boolean literals do not require any JSON escaping.
    out.write(value ? "true" : "false");

    // Return the JsonWriter instance to allow for method chaining (fluent API).
    return this;
}

public static WildcardType supertypeOf(Type bound) {
    if (bound == null) {
        throw new NullPointerException("bound cannot be null");
    }
    // A wildcard type representing "? super T" has T as its lower bound
    // and Object as its only upper bound (implicitly or explicitly).
    // The WildcardTypeImpl constructor expects upperBounds and lowerBounds.
    // For "? super T", the upper bound is always Object.class.
    // The lower bound is the provided 'bound'.
    Type[] lowerBounds = new Type[] { bound };
    Type[] upperBounds = new Type[] { Object.class }; // Represents the implicit upper bound for "? super T"
    return new WildcardTypeImpl(upperBounds, lowerBounds);
}

public static UnsafeAllocator create() {
    // Strategy 1: Try JVM sun.misc.Unsafe
    try {
      Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
      Field f = unsafeClass.getDeclaredField("theUnsafe");
      f.setAccessible(true);
      final Object unsafe = f.get(null);
      final Method allocateInstance = unsafeClass.getMethod("allocateInstance", Class.class);
      return new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new IllegalArgumentException("Class cannot be null.");
          }
          return (T) allocateInstance.invoke(unsafe, c);
        }
      };
    } catch (Exception e) {
      logger.log(Level.FINE, "Failed to use sun.misc.Unsafe for allocation.", e);
    }

    // Strategy 2: Try Dalvik VM (post-Gingerbread)
    try {
      Method getConstructorId = ObjectStreamClass.class
          .getDeclaredMethod("getConstructorId", Class.class);
      getConstructorId.setAccessible(true);
      final int constructorId = (Integer) getConstructorId.invoke(null, Object.class);
      final Method newInstance = ObjectStreamClass.class
          .getDeclaredMethod("newInstance", Class.class, int.class);
      newInstance.setAccessible(true);
      return new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new IllegalArgumentException("Class cannot be null.");
          }
          return (T) newInstance.invoke(null, c, constructorId);
        }
      };
    } catch (Exception e) {
      logger.log(Level.FINE, "Failed to use ObjectStreamClass (post-Gingerbread) for allocation.", e);
    }

    // Strategy 3: Try Dalvik VM (pre-Gingerbread)
    try {
      final Method newInstance = ObjectInputStream.class
          .getDeclaredMethod("newInstance", Class.class, Class.class);
      newInstance.setAccessible(true);
      return new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new IllegalArgumentException("Class cannot be null.");
          }
          return (T) newInstance.invoke(null, c, Object.class);
        }
      };
    } catch (Exception e) {
      logger.log(Level.FINE, "Failed to use ObjectInputStream (pre-Gingerbread) for allocation.", e);
    }

    // Fallback: Give up and throw UnsupportedOperationException
    return new UnsafeAllocator() {
      @Override
      public <T> T newInstance(Class<T> c) {
        if (c == null) {
          throw new IllegalArgumentException("Class cannot be null.");
        }
        throw new UnsupportedOperationException(
            "Cannot allocate " + c + ". No supported allocation strategy found.");
      }
    };
  }

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
