                 return createBigInteger(bigIntHexStr); // BigInteger needs the hex digits directly
            } catch (final NumberFormatException nfe) {
                throw new NumberFormatException(str + " is not a valid hex number.");
            }
        }


        // Revert parseStr to original str for non-hex parsing, as sign handling is now integrated below
        parseStr = str;

