        final char lastChar = parseStr.charAt(parseStr.length() - 1);
        String mant; // Mantissa
        String dec;  // Decimal part
        String exp;  // Exponent part

        final int decPos = parseStr.indexOf('.');
        final int ePos = parseStr.indexOf('e');
        final int EPos = parseStr.indexOf('E');

        // Determine the actual exponent position (first 'e' or 'E')
        int expPos = -1;
