            }
            mant = parseStr.substring(0, decPos);
            numDecimals = dec.length();
        } else { // no decimal point
            if (expPos > -1) {
                mant = parseStr.substring(0, expPos);
            } else {
                mant = parseStr;
            }
            dec = null;
        }

        if (expPos > -1 && expPos < parseStr.length() - 1) {
            exp = parseStr.substring(expPos + 1); // Get full exponent string
        } else {
            exp = null;
        }

        // Validate mantissa: must contain at least one digit or be empty if it's ".5" or "e5"
        if (mant.isEmpty() && decPos == -1 && expPos == -1 && !parseStr.equals(".")) {
             // Example: if mant is empty, and no dec/exp, like an empty string, should be caught by isBlank.
             // If input is just "-", mant is empty, decPos and expPos are -1, this would be invalid.
             // If input is ".", mant is empty, decPos is 0, expPos is -1.
        }

        // Check for specific type suffixes (l/L, f/F, d/D)
        // This block needs careful re-evaluation of how 'numeric' and 'allZeros' are used.
        // It's trying to parse 'numeric' (str without suffix) and then validate based on 'allZeros' of mantissa/exponent.
        if (!Character.isDigit(lastChar) && lastChar != '.') {
            final String numeric = parseStr.substring(0, parseStr.length() - 1);
            final boolean allZerosMantissa = isAllZeros(mant);
            final boolean allZerosExponent = isAllZeros(exp); // exp could be null here.
            final boolean allZerosCombined = allZerosMantissa && (exp == null || allZerosExponent);

            switch (lastChar) {
                case 'l' :
                case 'L' :
                    if (dec == null && exp == null && isDigits(numeric) || (numeric.startsWith("-") && isDigits(numeric.substring(1)))) {
                        try {
                            return createLong(numeric);
                        } catch (final NumberFormatException nfe) {
                            // Too big for a long, try BigInteger
                        }
                        return createBigInteger(numeric);
                    }
                    throw new NumberFormatException(str + " is not a valid Long number.");
                case 'f' :
                case 'F' :
                    try {
                        final Float f = createFloat(numeric);
                        // If it's infinite, or it's zero but the original non-suffix part implies non-zero digits (precision loss)
                        if (!f.isInfinite() && (f.floatValue() != 0.0F || allZerosCombined)) {
                            return f;
                        }
                    } catch (final NumberFormatException nfe) {
                        // ignore, try next
                    }
                    //$FALL-THROUGH$ to double then BigDecimal
                case 'd' :
                case 'D' :
                    try {
                        final Double d = createDouble(numeric);
                        // If it's infinite, or it's zero but the original non-suffix part implies non-zero digits (precision loss)
                        if (!d.isInfinite() && (d.doubleValue() != 0.0D || allZerosCombined)) {
                            return d;
                        }
                    } catch (final NumberFormatException nfe) {
                        // ignore, try next
                    }
                    // If Float/Double didn't work or had precision issues, use BigDecimal
                    try {
                        return createBigDecimal(numeric);
                    } catch (final NumberFormatException e) {
                        // All attempts failed for a specific type suffix
                        throw new NumberFormatException(str + " is not a valid number of type 'd' or 'f'.");
                    }
                default :
                    throw new NumberFormatException(str + " is not a valid number (unrecognized suffix or format).");
            }
        }

        // --- No suffix, infer type based on content ---
        // If no decimal point and no exponent, try integer types
        if (decPos == -1 && expPos == -1) {
            try {
                return createInteger(parseStr);
            } catch (final NumberFormatException nfe) {
                // ignore and try Long
            }
            try {
                return createLong(parseStr);
            } catch (final NumberFormatException nfe) {
                // ignore and try BigInteger
            }
            return createBigInteger(parseStr);
        }

        // If decimal or exponent is present, try floating-point types
        final boolean allZerosMantissa = isAllZeros(mant);
        final boolean allZerosExponent = isAllZeros(exp);
        final boolean allZerosCombined = allZerosMantissa && (exp == null || allZerosExponent);

        // Try Float if precision allows
        try {
            // Heuristic for Float: if 7 or fewer digits after decimal. This is just a hint.
            if (numDecimals <= 7) {
                final Float f = createFloat(parseStr);
                // Same precision check as above: if not infinite, and not 0.0 with non-zero original value
                if (!f.isInfinite() && (f.floatValue() != 0.0F || allZerosCombined)) {
                    return f;
                }
            }
        } catch (final NumberFormatException nfe) {
            // ignore and try Double
        }

        // Try Double if precision allows
        try {
            // Heuristic for Double: if 16 or fewer digits after decimal.
            if (numDecimals <= 16) { // Original was >8, then >16. This should be <=16.
                final Double d = createDouble(parseStr);
                // Same precision check as above
                if (!d.isInfinite() && (d.doubleValue() != 0.0D || allZerosCombined)) {
                    return d;
                }
            }
        } catch (final NumberFormatException nfe) {
            // ignore and try BigDecimal
        }

        // Fallback to BigDecimal if Float/Double failed or had precision issues, or if too many decimals
        return createBigDecimal(parseStr);
    }

