                mantissa = str.substring(0, expPos);
                exponentPart = str.substring(expPos + 1);
            } else { // No decimal, no exponent
                mantissa = str;
            }
        }

        // Check if the number ends with a type suffix
        final char lastChar = str.charAt(str.length() - 1);
        boolean hasTypeSuffix = !Character.isDigit(lastChar) && lastChar != '.';

        if (hasTypeSuffix) {
            final String numeric = str.substring(0, str.length() - 1);
            boolean allZeros = isAllZeros(mantissa) && (exponentPart == null || isAllZeros(exponentPart)); // Re-eval allZeros based on parsed parts

            switch (lastChar) {
                case 'l':
                case 'L':
