                    return createBigDecimal(numeric);

                case 'd':
                case 'D':
                    try {
                        final Double d = createDouble(numeric);
                        // More robust precision check: Parse as BigDecimal and compare
                        BigDecimal bdD = new BigDecimal(numeric);
                        if (bdD.compareTo(BigDecimal.valueOf(d)) == 0) { // Check for exact representation
                            return d;
                        }
                    } catch (final NumberFormatException nfe) {
                        // Ignore, try BigDecimal later
                    }
                    // Fall through to BigDecimal if Double fails or loses precision
                    return createBigDecimal(numeric);

                default:
                    throw new NumberFormatException(str + " is not a valid number (unrecognized suffix).");
            }
        }

        // --- No Suffix - Infer Type ---

        if (decimalPart == null && exponentPart == null) { // Pure integer format
            try {
                return createInteger(str);
            } catch (final NumberFormatException nfe) {
                try {
                    return createLong(str);
                } catch (final NumberFormatException nfe2) {
                    return createBigInteger(str);
                }
            }
        }

        // Floating point number (with or without exponent, with or without decimal)

        // Try Float first, with robust precision check
        try {
            final Float f = createFloat(str);
            BigDecimal bdF = new BigDecimal(str);
            if (bdF.compareTo(BigDecimal.valueOf(f)) == 0 || f.isInfinite()) {
                 return f;
            }
        } catch (final NumberFormatException nfe) {
            // Ignore, try Double
        }

        // Try Double next, with robust precision check
        try {
            final Double d = createDouble(str);
            BigDecimal bdD = new BigDecimal(str);
            if (bdD.compareTo(BigDecimal.valueOf(d)) == 0 || d.isInfinite()) {
                return d;
            }
        } catch (final NumberFormatException nfe) {
            // Ignore, try BigDecimal
        }

        // If neither Float nor Double can represent it precisely, or they failed, use BigDecimal
        return createBigDecimal(str);
    }

public static WildcardType supertypeOf(Type bound) {
    if (bound == null) {
        throw new NullPointerException("bound cannot be null");
    }
    Type[] lowerBounds = new Type[] { bound };
    return new WildcardTypeImpl(new Type[] { Object.class }, lowerBounds);
}

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (StringUtils.isBlank(str)) { // Assuming StringUtils.isBlank is available
            throw new NumberFormatException("A blank string is not a valid number.");
        }

        final String trimmedStr = str.trim(); // Trim to handle leading/trailing spaces
        if (StringUtils.isBlank(trimmedStr)) { // Re-check after trimming
            throw new NumberFormatException("A blank string is not a valid number.");
        }

        // --- Handle Hexadecimal Numbers ---
        final String[] hexPrefixes = {"0x", "0X", "#"};
        final String[] negativeHexPrefixes = {"-0x", "-0X", "-#"};
        boolean isNegativeHex = false;
        String hexValue = null;

        for (final String pfx : hexPrefixes) {
            if (trimmedStr.startsWith(pfx)) {
                hexValue = trimmedStr.substring(pfx.length());
                break;
            }
        }
        if (hexValue == null) { // Check for negative hex prefixes
            for (final String pfx : negativeHexPrefixes) {
                if (trimmedStr.startsWith(pfx)) {
                    isNegativeHex = true;
                    hexValue = trimmedStr.substring(pfx.length());
                    break;
                }
            }
        }

        if (hexValue != null) { // We have a hex number
            if (StringUtils.isBlank(hexValue)) {
                throw new NumberFormatException(str + " is not a valid hexadecimal number (missing digits).");
            }
            // Validate hex digits - simple check if all are valid hex characters (0-9, a-f, A-F)
            for (char c : hexValue.toCharArray()) {
                if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
                    throw new NumberFormatException(str + " contains invalid hexadecimal digits.");
                }
            }

            try {
                final BigInteger bi = new BigInteger(hexValue, 16);
                if (isNegativeHex) {
                    if (bi.compareTo(BigInteger.ZERO) == 0) { // -0x0 is just 0
                        return Integer.valueOf(0);
                    }
                    if (bi.compareTo(BigInteger.valueOf(Long.MAX_VALUE).add(BigInteger.ONE)) < 0) { // Can fit in long
                        if (bi.compareTo(BigInteger.valueOf(Integer.MAX_VALUE).add(BigInteger.ONE)) < 0) { // Can fit in int
                            return Integer.valueOf(-bi.intValue());
                        }
                        return Long.valueOf(-bi.longValue());
                    }
                    return bi.negate();
                } else {
                    if (bi.compareTo(BigInteger.valueOf(Integer.MAX_VALUE)) <= 0) {
                        return bi.intValue();
                    }
                    if (bi.compareTo(BigInteger.valueOf(Long.MAX_VALUE)) <= 0) {
                        return bi.longValue();
                    }
                    return bi;
                }
            } catch (final NumberFormatException e) {
                // Should not happen if hexValue is already validated, but as a safeguard
                throw new NumberFormatException(str + " is not a valid hexadecimal number: " + e.getMessage());
            }
        }

        // --- Handle Numbers with Suffixes or Specific Floating Point/Integer Forms ---
        // Need to parse mantissa, decimal, and exponent parts
        String mantissa;
        String decimalPart = null;
        String exponentPart = null;

        int decPos = trimmedStr.indexOf('.');
        // Correctly find exponent position (case-insensitive)
        int expPos = -1;
        int expPosLowerE = trimmedStr.indexOf('e');
        int expPosUpperE = trimmedStr.indexOf('E');
        if (expPosLowerE > -1) {
            expPos = expPosLowerE;
        }
        if (expPosUpperE > -1) {
            if (expPos == -1 || expPosUpperE < expPos) { // Use the first 'e' or 'E' encountered
                expPos = expPosUpperE;
            }
        }

        // Basic sanity checks for exponent/decimal positions
        if (decPos > -1 && expPos > -1 && decPos > expPos) {
            throw new NumberFormatException(str + " is not a valid number (decimal point after exponent).");
        }
        if (expPos > -1 && (expPos == 0 || expPos == trimmedStr.length() -1)) { // Exponent char at start or end
             throw new NumberFormatException(str + " is not a valid number (misplaced exponent).");
        }

        int end = trimmedStr.length();
        char lastChar = trimmedStr.charAt(end - 1);

        boolean hasSuffix = false;
        if (!Character.isDigit(lastChar) && lastChar != '.') { // Check if it's a type suffix
            switch (lastChar) {
                case 'l':
                case 'L':
                case 'f':
                case 'F':
                case 'd':
                case 'D':
                    hasSuffix = true;
                    end--; // Exclude suffix from numeric string
                    break;
                default: // Invalid suffix or just a non-digit at the end of what might be a number
                    // If it's not a recognized suffix, and it's not a digit, it's not a number
                    throw new NumberFormatException(str + " is not a valid number (unrecognized trailing character).");
            }
        }

        String numeric = trimmedStr.substring(0, end);

        // Re-calculate positions for the numeric part *after* removing suffix
        decPos = numeric.indexOf('.');
        expPos = -1;
        expPosLowerE = numeric.indexOf('e');
        expPosUpperE = numeric.indexOf('E');
        if (expPosLowerE > -1) {
            expPos = expPosLowerE;
        }
        if (expPosUpperE > -1) {
            if (expPos == -1 || expPosUpperE < expPos) {
                expPos = expPosUpperE;
            }
        }

        // Parse mantissa, decimal part, and exponent part from the numeric string
        int numDecimals = 0;
        if (decPos > -1) { // There is a decimal point
            if (expPos > -1) { // There is an exponent
                decimalPart = numeric.substring(decPos + 1, expPos);
            } else {
                decimalPart = numeric.substring(decPos + 1);
            }
            mantissa = numeric.substring(0, decPos);
            numDecimals = decimalPart.length();
        } else {
            if (expPos > -1) {
                mantissa = numeric.substring(0, expPos);
            } else {
                mantissa = numeric;
            }
        }

        if (expPos > -1) {
            exponentPart = numeric.substring(expPos + 1);
        }

        // Handle specific type suffixes
        if (hasSuffix) {
            switch (lastChar) {
                case 'l':
                case 'L':
                    if (decPos == -1 && expPos == -1) { // Must be an integer literal for long suffix
                        try {
                            return createLong(numeric);
                        } catch (final NumberFormatException nfe) {
                            // Too big for a long, try BigInteger
                            return createBigInteger(numeric);
                        }
                    }
                    throw new NumberFormatException(str + " is not a valid long number (contains decimal or exponent).");

                case 'f':
                case 'F':
                    try {
                        final Float f = createFloat(numeric);
                        // Check for precision loss for numbers that become 0.0 or infinite due to float's limited range
                        final boolean allZeros = (isAllZeros(mantissa) && (decimalPart == null || isAllZeros(decimalPart)) && (exponentPart == null || isAllZeros(exponentPart)));
                        if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                            return f;
                        }
                    } catch (final NumberFormatException nfe) {
                        // ignore the bad float format, try bigger type
                    }
                    // FALL-THROUGH to Double or BigDecimal if Float fails or loses precision
                case 'd':
                case 'D':
                    try {
                        final Double d = createDouble(numeric);
                        final boolean allZeros = (isAllZeros(mantissa) && (decimalPart == null || isAllZeros(decimalPart)) && (exponentPart == null || isAllZeros(exponentPart)));
                        // Corrected: use d.doubleValue() for Double comparison
                        if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                            return d;
                        }
                    } catch (final NumberFormatException nfe) {
                        // ignore the bad double format, try bigger type
                    }
                    // If Float/Double failed or lost precision, try BigDecimal
                    try {
                        return createBigDecimal(numeric);
                    } catch (final NumberFormatException e) {
                        // All attempts failed for this suffix
                        throw new NumberFormatException(str + " is not a valid number for type '" + lastChar + "'.");
                    }
                default: // Should not be reached due to previous hasSuffix check
                    throw new NumberFormatException(str + " is not a valid number.");
            }
        }

        // --- No Suffix - Determine Type Automatically ---
        // If no decimal point and no exponent, try Integer, then Long, then BigInteger
        if (decPos == -1 && expPos == -1) {
            try {
                return createInteger(numeric);
            } catch (final NumberFormatException nfe) {
                // Ignore, too big for Integer, try Long
            }
            try {
                return createLong(numeric);
            } catch (final NumberFormatException nfe) {
                // Ignore, too big for Long, try BigInteger
            }
            // If it's too big for Long or malformed as Long, createBigInteger will either succeed or throw
            return createBigInteger(numeric);
        }

        // Must be a Float, Double, or BigDecimal (has decimal or exponent)
        final boolean allZeros = (isAllZeros(mantissa) && (decimalPart == null || isAllZeros(decimalPart)) && (exponentPart == null || isAllZeros(exponentPart)));

        // Try Float first, if it can maintain precision
        try {
            // Heuristic for float precision: 7 or fewer decimal digits
            if (numDecimals <= 7) {
                final Float f = createFloat(numeric);
                if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                    return f;
                }
            }
        } catch (final NumberFormatException nfe) {
            // Ignore, try Double
        }

        // Try Double next, if it can maintain precision
        try {
            // Heuristic for double precision: 16 or fewer decimal digits
            if (numDecimals <= 16) { // numDecimals is already calculated from the string
                final Double d = createDouble(numeric);
                if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                    return d;
                }
            }
        } catch (final NumberFormatException nfe) {
            // Ignore, try BigDecimal
        }

        // Fallback to BigDecimal if Float/Double fail or lose precision
        return createBigDecimal(numeric);
    }

