            // NumberFormatException could be more informative.
            return null;
            // Alternatively: throw new NumberFormatException("String starts with '--', which is not a valid number format.");
        }

        // Handle hexadecimal numbers
        if (str.startsWith("0x") || str.startsWith("-0x")) {
            // Assuming createInteger handles hex parsing (e.g., via Integer.decode())
            return createInteger(str);
        }

        char lastChar = str.charAt(str.length() - 1);
        String mant; // Mantissa part before decimal and exponent
        String dec;  // Decimal part after decimal and before exponent
        String exp;  // Exponent part

        int decPos = str.indexOf('.');

        // Correctly find the first occurrence of 'e' or 'E'
        int ePos = str.indexOf('e');
        int EPos = str.indexOf('E');
        int expPos;

        if (ePos > -1) {
            expPos = ePos;
            if (EPos > -1 && EPos < ePos) { // 'E' appeared before 'e'
                expPos = EPos;
            }
        } else if (EPos > -1) {
            expPos = EPos;
        } else {
            expPos = -1; // No exponent found
        }

        // Parse mantissa, decimal, and exponent parts
        if (decPos > -1) { // Contains a decimal point
            if (expPos > -1) { // Contains both decimal and exponent
                if (expPos < decPos) {
                    throw new NumberFormatException(str + " is not a valid number. Exponent marker appears before decimal point.");
                }
                dec = str.substring(decPos + 1, expPos);
                mant = str.substring(0, decPos);
            } else { // Contains decimal, but no exponent
                dec = str.substring(decPos + 1);
                mant = str.substring(0, decPos);
            }
        } else { // No decimal point
            if (expPos > -1) { // Contains exponent, but no decimal
                mant = str.substring(0, expPos);
                dec = null;
            } else { // Neither decimal nor exponent
                mant = str;
                dec = null;
            }
        }

        // Check for common error: exponent marker at the very end of the string
        if (expPos == str.length() -1) {
             throw new NumberFormatException(str + " is not a valid number. Exponent marker found at the end of the string.");
        }


        // Determine if there's a type suffix (l, L, f, F, d, D)
        if (!Character.isDigit(lastChar) && lastChar != '.') {
            String numericPartWithoutSuffix = str.substring(0, str.length() - 1);

            // Extract exponent for numbers with suffixes (if present)
            if (expPos > -1 && expPos < str.length() - 1) { // Exponent exists and is not the suffix itself
                exp = str.substring(expPos + 1, str.length() - 1); // Exclude the type suffix
            } else {
                exp = null;
            }

            // Check if the mantissa or exponent parts are all zeros (for precision checking later)
            boolean allZerosMantissa = isAllZeros(mant);
            boolean allZerosExp = isAllZeros(exp); // Assuming exp can be null or "0" etc.

            switch (lastChar) {
                case 'l' :
                case 'L' :
                    if (dec == null && exp == null) { // Longs should not have decimal or exponent
                        // Ensure the numeric part is valid for a long (optional leading '-')
                        if ( (numericPartWithoutSuffix.charAt(0) == '-' && isDigits(numericPartWithoutSuffix.substring(1))) ||
                             isDigits(numericPartWithoutSuffix) ) {
                            try {
                                return createLong(numericPartWithoutSuffix);
                            } catch (NumberFormatException nfe) {
                                // Too big for a long, try BigInteger
                                return createBigInteger(numericPartWithoutSuffix);
                            }
                        }
                    }
                    throw new NumberFormatException(str + " is not a valid number for 'L' suffix. Longs cannot have decimal or exponent parts.");

                case 'f' :
                case 'F' :
                    try {
                        Float f = createFloat(numericPartWithoutSuffix);
                        // Check for infinite values or values that underflowed to zero but weren't originally zero
                        if (!(f.isInfinite() || (f.floatValue() == 0.0F && (!allZerosMantissa || !allZerosExp)))) {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // ignore and try larger type if 'f' or 'F' couldn't fit
                    }
                    // $FALL-THROUGH$ to 'd' case if float is infinite or underflowed
                case 'd' :
                case 'D' :
                    try {
                        Double d = createDouble(numericPartWithoutSuffix);
                        // Check for infinite values or values that underflowed to zero but weren't originally zero
                        if (!(d.isInfinite() || (d.doubleValue() == 0.0D && (!allZerosMantissa || !allZerosExp)))) { // Corrected floatValue() to doubleValue()
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // ignore and try BigDecimal
                    }
                    try {
                        // If float or double could not represent it accurately, use BigDecimal
                        return createBigDecimal(numericPartWithoutSuffix);
                    } catch (NumberFormatException e) {
                        // This catch should ideally not happen if createDouble/createFloat already handle most non-numeric cases
                        // but is kept for robustness.
                        throw new NumberFormatException(str + " is not a valid number after attempting float, double, and bigdecimal conversions.");
                    }

                default :
                    throw new NumberFormatException(str + " is not a valid number. Unrecognized type suffix: '" + lastChar + "'.");
            }
        } else {
            // User doesn't have a preference on the return type (no suffix), so infer the best type.

            // Re-extract exponent for this case where there is no suffix (exp will be null or the actual string)
            if (expPos > -1 && expPos < str.length()) { // expPos cannot be str.length()
                exp = str.substring(expPos + 1); // Get exponent part until the end
            } else {
                exp = null;
            }

            if (dec == null && exp == null) {
                // Must be an int, long, or BigInteger (no decimal or exponent)
                try {
                    return createInteger(str);
                } catch (NumberFormatException nfe) {
                    // ignore, try long
                }
                try {
                    return createLong(str);
                } catch (NumberFormatException nfe) {
                    // ignore, try BigInteger
                }
                // If it's too big for long, try BigInteger
                return createBigInteger(str);

            } else {
                // Must be a float, double, or BigDecimal (contains decimal or exponent)
                boolean allZerosMantissa = isAllZeros(mant);
                boolean allZerosExp = isAllZeros(exp);

                try {
                    Float f = createFloat(str);
                    // Check for infinite values or values that underflowed to zero but weren't originally zero
                    if (!(f.isInfinite() || (f.floatValue() == 0.0F && (!allZerosMantissa || !allZerosExp)))) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // ignore, try double
                }
                try {
                    Double d = createDouble(str);
                    // Check for infinite values or values that underflowed to zero but weren't originally zero
                    if (!(d.isInfinite() || (d.doubleValue() == 0.0D && (!allZerosMantissa || !allZerosExp)))) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // ignore, try BigDecimal
                }

                // If float or double could not represent it accurately, use BigDecimal
                return createBigDecimal(str);
            }
        }
    }

public static String random(int count, int start, int end, boolean letters, boolean numbers,
                                char[] chars, Random random) {
        if (random == null) {
            throw new IllegalArgumentException("Random instance cannot be null.");
        }
        if (count == 0) {
            return "";
        }
        if (count < 0) {
            throw new IllegalArgumentException("Requested random string length " + count + " is less than 0.");
        }
        if (chars != null && chars.length == 0) {
            throw new IllegalArgumentException("The chars array must not be empty if provided.");
        }

        // Determine the character source range
        if (chars == null) {
            if (start == 0 && end == 0) {
                // Default range based on flags if custom chars not provided
                if (!letters && !numbers) {
                    // Default to all printable ASCII characters if no specific types are requested
                    // and no custom range is given. Exclude control characters.
                    start = 32; // Space
                    end = 127;  // Del (~tilde)
                } else {
                    // Default to alphanumeric range.
                    // This will be filtered further below by letters/numbers flags.
                    start = 32; // Space
                    end = 127; // Del (~tilde) - A common range that includes most letters, numbers, and symbols.
                               // We deliberately keep this somewhat broad as the filtering happens later.
                }
            } else {
                if (start < 0 || end < 0 || start > end) {
                    throw new IllegalArgumentException("Invalid 'start' (" + start + ") or 'end' (" + end + ") range. " +
                                                       "Must be 0 <= start <= end.");
                }
                // Ensure custom range does not exceed char max
                if (end > Character.MAX_VALUE) {
                    end = Character.MAX_VALUE;
                }
            }
        } else {
            // When custom chars array is provided, 'start' and 'end' apply to the array indices.
            // If they are 0 and 0, use the full array.
            if (start == 0 && end == 0) {
                end = chars.length;
            } else {
                if (start < 0 || end < 0 || start > end || end > chars.length) {
                    throw new IllegalArgumentException("Invalid 'start' (" + start + ") or 'end' (" + end + ") for 'chars' array. " +
                                                       "Must be 0 <= start <= end <= chars.length.");
                }
            }
        }

        char[] buffer = new char[count];
        int bufferIndex = 0; // Fill buffer from left to right

        // Calculate gap based on the determined range
        int effectiveGap = (chars == null) ? (end - start) : (end - start);
        if (effectiveGap <= 0) {
            throw new IllegalArgumentException("Effective character range or array segment is empty.");
        }


        while (bufferIndex < count) {
            char ch;
            if (chars == null) {
                // Randomly pick a character within the numeric range [start, end)
                ch = (char) (random.nextInt(effectiveGap) + start);
            } else {
                // Randomly pick a character from the custom array segment [start, end)
                ch = chars[random.nextInt(effectiveGap) + start];
            }

            // Filter based on letter/number flags
            boolean isValidChar = (!letters && !numbers) || // No specific filters, any char is valid
                                  (letters && Character.isLetter(ch)) ||
                                  (numbers && Character.isDigit(ch));

            if (isValidChar) {
                // Basic Multilingual Plane (BMP) characters or valid surrogate pairs
                if (Character.isSurrogate(ch)) {
                    // This method explicitly avoids generating surrogate pairs directly by filtering them out.
                    // Generating valid random surrogate pairs representing supplementary characters is complex
                    // and typically done at the code point level, not char level, for string generation.
                    // For this method's context (simple random string), it's safer to skip surrogates
                    // or define a clear policy.
                    // Original intent seems to try to handle them, but the implementation was broken.
                    // A common approach for 'random' is to stick to BMP or filter them out.
                    // We'll skip them to simplify and avoid malformed strings.
                    // If supplementary characters are desired, the method signature and logic need a complete redesign.
                    continue; // Skip this character and try again for the current position
                }
                buffer[bufferIndex++] = ch;
            }
            // If isValidChar is false, character is skipped, loop will re-iterate for the same bufferIndex
        }
        return new String(buffer);
    }

public static Number createNumber(String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (StringUtils.isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number");
        }

        // Handle specific problematic patterns or prefixes first
        // Consistency: if "--" is truly problematic for a specific underlying parser,
        // it should still throw NumberFormatException like other invalid inputs.
        // Based on analysis, BigDecimal.valueOf("--") throws NFE, so this special case
        // returning null is inconsistent and should be an NFE.
        if (str.startsWith("--")) {
            throw new NumberFormatException(str + " is not a valid number. Double hyphens are not supported.");
        }

        // Handle hexadecimal numbers
        if (str.startsWith("0x") || str.startsWith("-0x")) {
            // NumberUtils.createInteger and NumberUtils.createLong typically handle hex prefixes.
            // Try to create an Integer first, then a Long, then BigInteger.
            // This mirrors the behavior for decimal integers without a suffix.
            try {
                return createInteger(str);
            } catch (NumberFormatException nfe) {
                // Ignore, try Long
            }
            try {
                return createLong(str);
            } catch (NumberFormatException nfe) {
                // Ignore, try BigInteger
            }
            return createBigInteger(str); // Fallback to BigInteger for very large hex numbers
        }

        char lastChar = str.charAt(str.length() - 1);
        String mant;
        String dec;
        String exp;

        int decPos = str.indexOf('.');
        // Corrected expPos calculation: find the first occurrence of 'e' or 'E'
        int expPos = Math.max(str.indexOf('e'), str.indexOf('E'));

        // Parse mantissa, decimal, and exponent parts
        if (decPos > -1) { // Contains a decimal point
            if (expPos > -1) { // Contains an exponent AND a decimal point
                if (expPos < decPos || expPos > str.length() -1) { // Exponent before decimal or at end
                    throw new NumberFormatException(str + " is not a valid number. Exponent in invalid position.");
                }
                dec = str.substring(decPos + 1, expPos);
                mant = str.substring(0, decPos);
            } else { // Contains decimal, but no exponent
                dec = str.substring(decPos + 1);
                mant = str.substring(0, decPos);
            }
        } else { // No decimal point
            if (expPos > -1) { // Contains exponent, but no decimal point
                if (expPos > str.length() - 1) { // Exponent at end
                    throw new NumberFormatException(str + " is not a valid number. Exponent in invalid position.");
                }
                mant = str.substring(0, expPos);
            } else { // No decimal, no exponent (pure integer or suffixed integer)
                mant = str;
            }
            dec = null; // No decimal part
        }

        // Determine the exponent string if present in the processed mant/dec/exp extraction
        if (expPos > -1 && expPos < str.length() - 1) {
             // If a suffix is present, exp should exclude the last char.
             // If no suffix, exp should go to the end.
             // This needs to be handled carefully based on whether lastChar is a digit or type suffix.
             // Let's refine this to be part of the final type determination.
             // For now, let's reset exp for the main parsing if lastChar is a type suffix.
        }


        // Check if the last character is a type suffix
        if (!Character.isDigit(lastChar) && lastChar != '.') {
            String numeric = str.substring(0, str.length() - 1); // String without the suffix

            // Re-extract exponent for the 'numeric' string without suffix
            int newExpPos = Math.max(numeric.indexOf('e'), numeric.indexOf('E'));
            if (newExpPos > -1 && newExpPos < numeric.length() - 1) {
                exp = numeric.substring(newExpPos + 1); // Exponent is part of numeric
            } else {
                exp = null;
            }

            boolean allZeros = isAllZeros(mant) && (exp == null || isAllZeros(exp)); // Re-evaluate allZeros based on extracted parts

            switch (lastChar) {
                case 'l' :
                case 'L' :
                    // A 'long' type suffix implies integer. No decimal or exponent is allowed.
                    if (dec == null && exp == null) {
                        try {
                            return createLong(numeric);
                        } catch (NumberFormatException nfe) {
                            // If too big for a long, try BigInteger.
                            // The original code was returning BigInteger on NFE from createLong for 'l' suffix,
                            // which is reasonable behavior for very large numbers that still fit an integer pattern.
                            return createBigInteger(numeric);
                        }
                    }
                    throw new NumberFormatException(str + " is not a valid Long number. Decimals or exponents not allowed with 'L' suffix.");

                case 'f' :
                case 'F' :
                    try {
                        // Use the class's own createFloat method
                        Float f = createFloat(numeric);
                        // Check for infinite or underflow to zero from non-zero string
                        if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // Ignored if it's not a valid float. Will fall through to Double/BigDecimal.
                        // This behavior is preserved as per original design intention for robustness.
                    }
                    // Fall-through to 'd' case if float is not precise enough or fails to parse.

                case 'd' :
                case 'D' :
                    try {
                        // Use the class's own createDouble method
                        Double d = createDouble(numeric);
                        // Check for infinite or underflow to zero from non-zero string
                        if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // Ignored if it's not a valid double. Will fall through to BigDecimal.
                        // This behavior is preserved as per original design intention for robustness.
                    }
                    // If Float or Double fails to parse or is not precise enough, try BigDecimal.
                    try {
                        return createBigDecimal(numeric);
                    } catch (NumberFormatException e) {
                        // If BigDecimal also fails, then it's definitely not a number.
                        throw new NumberFormatException(str + " is not a valid floating point number with 'F' or 'D' suffix.");
                    }

                default :
                    throw new NumberFormatException(str + " is not a valid number. Unknown suffix '" + lastChar + "'.");
            }
        } else {
            // No type suffix, user doesn't have a preference on the return type.
            // Try to parse as Integer, then Long, then BigInteger if it's an integer-like string.
            // Or as Float, then Double, then BigDecimal if it's a floating-point-like string.

            // Re-evaluate exponent for the whole string if it ended with a digit/period
            if (expPos > -1 && expPos < str.length() -1) { // Note: expPos must be before the end if it's present.
                 exp = str.substring(expPos + 1);
            } else {
                exp = null;
            }

            if (dec == null && exp == null) {
                // Must be an int, long, or BigInteger
                try {
                    return createInteger(str);
                } catch (NumberFormatException nfe) {
                    // ignore the bad number, try long
                }
                try {
                    return createLong(str);
                } catch (NumberFormatException nfe) {
                    // ignore the bad number, try BigInteger
                }
                return createBigInteger(str); // Fallback for very large integers
            } else {
                // Must be a float, double, or BigDecimal
                boolean allZeros = isAllZeros(mant) && (exp == null || isAllZeros(exp));
                try {
                    Float f = createFloat(str);
                    if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // ignore the bad number, try double
                }
                try {
                    Double d = createDouble(str);
                    if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // ignore the bad number, try BigDecimal
                }
                return createBigDecimal(str); // Fallback for high-precision or very large/small floating point numbers
            }
        }
    }

