public int translate(CharSequence input, int index, Writer out) throws IOException {
        if (input == null || out == null) {
            throw new IllegalArgumentException("Input CharSequence and Writer cannot be null.");
        }
        int seqEnd = input.length();

        // Check for &# prefix, requiring at least one character after it (for 'x' or the first digit)
        if (index + 2 >= seqEnd || input.charAt(index) != '&' || input.charAt(index + 1) != '#') {
            return 0; // Not a numeric entity or not enough characters
        }

        int start = index + 2; // Position after &#
        boolean isHex = false;
        int hexPrefixLength = 0;

        // Check for 'x' or 'X' for hexadecimal
        if (start < seqEnd) {
            char firstChar = input.charAt(start);
            if (firstChar == 'x' || firstChar == 'X') {
                isHex = true;
                hexPrefixLength = 1;
                start++; // Move past 'x' or 'X'
                if (start == seqEnd) { // Check if input ends immediately after &#x
                    return 0; // Not a valid entity (&#x with no number)
                }
            }
        } else {
            return 0; // Not a valid entity (&# with no number/x)
        }

        int end = start;
        // Find the end of the numeric entity (either ';' or end of sequence)
        while (end < seqEnd && input.charAt(end) != ';') {
            end++;
        }

        // Validate that there's actual content for the number
        if (end == start) {
            // No digits found between &#[x] and ; or end of string
            return 0;
        }

        String entityStr = input.subSequence(start, end).toString();
        int entityValue;
        try {
            if (isHex) {
                entityValue = Integer.parseInt(entityStr, 16);
            } else {
                entityValue = Integer.parseInt(entityStr, 10);
            }
        } catch (NumberFormatException nfe) {
            // Log the error or throw a more specific exception if desired
            // For now, consistent with original behavior of skipping invalid entities
            // System.err.println("Invalid numeric entity: " + entityStr); // For debugging
            return 0;
        }

        // Handle high code points (supplementary characters)
        if (entityValue > 0xFFFF) {
            // Character.toChars returns a char array for supplementary characters (surrogate pair)
            out.write(Character.toChars(entityValue));
        } else {
            // For BMP characters, write directly as an int
            out.write(entityValue);
        }

        // Calculate consumed characters:
        // 2 for "&#"
        // hexPrefixLength for 'x' or 'X' if present
        // (end - start) for the actual numeric digits
        // 1 if terminated by ';' else 0
        int charsConsumed = 2 + hexPrefixLength + (end - start);
        if (end < seqEnd && input.charAt(end) == ';') {
            charsConsumed++; // Include the semicolon if it was present
        }

        return charsConsumed;
    }

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }

        final String trimmedStr = str.trim(); // Trim leading/trailing whitespace
        if (StringUtils.isBlank(trimmedStr)) {
            throw new NumberFormatException("A blank string (after trimming) is not a valid number.");
        }

        // BigDecimal.createNumber still parses "--1", which is not a standard number.
        // This explicitly handles the double-hyphen case.
        if (trimmedStr.startsWith("--")) {
            throw new NumberFormatException(trimmedStr + " is not a valid number. Double hyphen detected.");
        }

        // Handle hexadecimal numbers
        if (trimmedStr.startsWith("0x") || trimmedStr.startsWith("-0x") || trimmedStr.startsWith("0X") || trimmedStr.startsWith("-0X")) {
