                // directly support `0x` prefixes for floats/doubles without explicit `Float.valueOf` or `Double.valueOf` handling
                // which expects it without the 0x prefix if it's already a hex float format.
                // Since this method aims for broad number parsing, we'll try float/double as a fallback for non-hex integer patterns
                // if the original hex string failed integer parsing. This is a common pattern for such a utility.
                try {
                    return createDouble(trimmedStr); // Try parsing as double, which can handle hex floats like "0x1.ap-3" when provided to Double.valueOf
                } catch (NumberFormatException ignored) {
                    throw new NumberFormatException(trimmedStr + " is not a valid hexadecimal integer or floating-point number.");
                }
