        char lastChar = trimmedStr.charAt(trimmedStr.length() - 1);
        String mantissaPart; // Renamed for clarity from 'mant'
        String decimalPart; // Renamed for clarity from 'dec'
        String exponentPart; // Renamed for clarity from 'exp'

        int decPos = trimmedStr.indexOf('.');
        int expPos = trimmedStr.indexOf('e');
        if (expPos == -1) { // If 'e' not found, try 'E'
            expPos = trimmedStr.indexOf('E');
        }

        // Determine mantissa, decimal, and exponent parts
        if (decPos > -1) { // Has a decimal point
            if (expPos > -1) { // Has a decimal and an exponent
                if (expPos < decPos || expPos > trimmedStr.length() - 1) { // Exponent must be after decimal and not be the last char
                    throw new NumberFormatException(trimmedStr + " is not a valid number: invalid exponent position.");
                }
                decimalPart = trimmedStr.substring(decPos + 1, expPos);
                mantissaPart = trimmedStr.substring(0, decPos);
                exponentPart = trimmedStr.substring(expPos + 1);
            } else { // Has a decimal but no exponent
                decimalPart = trimmedStr.substring(decPos + 1);
                mantissaPart = trimmedStr.substring(0, decPos);
                exponentPart = null;
            }
        } else { // No decimal point
            if (expPos > -1) { // No decimal but has an exponent
                if (expPos > trimmedStr.length() - 1) { // Exponent must not be the last char
                    throw new NumberFormatException(trimmedStr + " is not a valid number: invalid exponent position.");
                }
                mantissaPart = trimmedStr.substring(0, expPos);
                decimalPart = null; // No decimal part
                exponentPart = trimmedStr.substring(expPos + 1);
            } else { // No decimal and no exponent
                mantissaPart = trimmedStr;
                decimalPart = null;
                exponentPart = null;
            }
        }

        // Remove type suffix if present
        if (!Character.isDigit(lastChar) && lastChar != '.' && lastChar != '+' && lastChar != '-') { // Added '+' and '-' as these are valid for exponents
            String numericPart = trimmedStr.substring(0, trimmedStr.length() - 1); // The numeric part without the suffix
            boolean allZerosNumeric = (isAllZeros(mantissaPart) || "0".equals(mantissaPart)) && (decimalPart == null || isAllZeros(decimalPart) || "0".equals(decimalPart)) && (exponentPart == null || isAllZeros(exponentPart) || "0".equals(exponentPart));

            switch (lastChar) {
                case 'l' :
                case 'L' :
                    // A long must not have a decimal or exponent.
                    if (decPos != -1 || expPos != -1) {
