public String format(Date date) {
    // Robustness: Handle null input for 'date'.
    // A NullPointerException would otherwise be thrown by c.setTime(date).
    if (date == null) {
        throw new IllegalArgumentException("Date must not be null.");
    }

    // Initialize Calendar with the configured TimeZone and Locale.
    // Explicitly setting the locale ensures consistent date/time calculations
    // and representations that might be locale-dependent, aligning with mLocale.
    Calendar c = new GregorianCalendar(mTimeZone, mLocale);
    c.setTime(date);

    // Apply the formatting rules using the initialized Calendar and a StringBuffer.
