    return applyRules(c, new StringBuffer(mMaxLengthEstimate)).toString();
}

public static Number createNumber(String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (StringUtils.isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number.");
        }

        // Improved parsing for hex
        if (str.startsWith("0x") || str.startsWith("-0x")) {
            String hexValue = str.startsWith("-") ? "-" + str.substring(3) : str.substring(2);
            if (hexValue.isEmpty() || (hexValue.length() == 1 && hexValue.charAt(0) == '-')) { // Handle "0x" or "-0x"
                throw new NumberFormatException("Invalid hexadecimal number: " + str);
            }
            try {
                return createInteger(str); // Integer.decode handles "0x" prefix
            } catch (NumberFormatException e) {
                try {
                    return createLong(str); // Long.decode handles "0x" prefix
                } catch (NumberFormatException e2) {
                    try {
                        // For BigInteger, we strip the prefix and handle the sign manually
                        return new BigInteger(hexValue, 16);
                    } catch (NumberFormatException e3) {
                        throw new NumberFormatException("Unable to parse hexadecimal number: " + str);
                    }
                }
            }
        }

        // Separate parsing for suffix to determine type preference
        char lastChar = str.charAt(str.length() - 1);
        String numericString = str;
        NumberType preferredType = NumberType.NONE;

        if (!Character.isDigit(lastChar) && lastChar != '.') { // Could be a type suffix
            switch (Character.toLowerCase(lastChar)) {
                case 'l':
                    preferredType = NumberType.LONG;
                    numericString = str.substring(0, str.length() - 1);
                    break;
                case 'f':
                    preferredType = NumberType.FLOAT;
                    numericString = str.substring(0, str.length() - 1);
                    break;
                case 'd':
                    preferredType = NumberType.DOUBLE;
                    numericString = str.substring(0, str.length() - 1);
                    break;
                default:
                    // Not a recognized type suffix, treat the whole string as numeric
                    break;
            }
        }

        // Basic validation before heavy parsing
        if (numericString.isEmpty() || (numericString.length() == 1 && numericString.charAt(0) == '-')) {
            throw new NumberFormatException("Invalid number format: " + str);
        }

        // Parse into components: sign, integer part, decimal part, exponent part
        boolean negative = false;
        int start = 0;
        if (numericString.startsWith("-")) {
            negative = true;
            start = 1;
        } else if (numericString.startsWith("+")) {
            start = 1; // + sign is allowed
        }

        String actualNumericPart = numericString.substring(start);
        if (actualNumericPart.isEmpty()) {
            throw new NumberFormatException("Invalid number format: " + str);
        }

        int decPos = actualNumericPart.indexOf('.');
        int expPos = -1;
        int eIndex = actualNumericPart.indexOf('e');
        int EIndex = actualNumericPart.indexOf('E');
        if (eIndex != -1) {
            expPos = eIndex;
        }
        if (EIndex != -1 && (expPos == -1 || EIndex < expPos)) {
            expPos = EIndex;
        }

        String mantissa = null;
        String decimalPart = null;
        String exponentPart = null;

        if (expPos > -1) { // Has exponent
            if (decPos > -1) { // Has decimal and exponent
                if (expPos < decPos) {
                    throw new NumberFormatException(str + " is not a valid number (exponent before decimal).");
                }
                mantissa = actualNumericPart.substring(0, decPos);
                decimalPart = actualNumericPart.substring(decPos + 1, expPos);
            } else { // Only exponent
                mantissa = actualNumericPart.substring(0, expPos);
            }
            exponentPart = actualNumericPart.substring(expPos + 1);
        } else if (decPos > -1) { // Only decimal
            mantissa = actualNumericPart.substring(0, decPos);
            decimalPart = actualNumericPart.substring(decPos + 1);
        } else { // Neither decimal nor exponent
            mantissa = actualNumericPart;
        }

        // Basic sanity checks for parts
        if ((mantissa == null || mantissa.isEmpty()) && (decimalPart == null || decimalPart.isEmpty())) {
            throw new NumberFormatException("Invalid number format: " + str + " (missing significant digits).");
        }
        if (mantissa != null && !isDigits(mantissa)) {
            throw new NumberFormatException("Invalid number format: " + str + " (mantissa contains non-digits).");
        }
        if (decimalPart != null && !isDigits(decimalPart)) {
            throw new NumberFormatException("Invalid number format: " + str + " (decimal part contains non-digits).");
        }
        // Exponent part can have a sign
        if (exponentPart != null && !isDigits(exponentPart.replaceFirst("^[+-]", ""))) {
            throw new NumberFormatException("Invalid number format: " + str + " (exponent contains non-digits or invalid sign).");
        }


        // Reconstruct the full string for parsing (BigDecimal is robust)
        String fullNumericStringForBigDecimal = (negative ? "-" : "") + actualNumericPart;
        boolean hasDecimalOrExponent = (decPos > -1 || expPos > -1);
        boolean isZeroValue = isAllZeros(mantissa) && isAllZeros(decimalPart) && isAllZeros(exponentPart);


        switch (preferredType) {
            case LONG:
                if (hasDecimalOrExponent) {
                    throw new NumberFormatException(str + " is not a valid long (contains decimal or exponent).");
                }
                try {
                    return createLong(numericString); // Use original numericString as createLong handles sign
                } catch (NumberFormatException e) {
                    // Too big for a long, try BigInteger
                    try {
                        return createBigInteger(numericString);
                    } catch (NumberFormatException e2) {
                        throw new NumberFormatException("Unable to parse long/BigInteger: " + str);
                    }
                }
            case FLOAT:
                try {
                    Float f = createFloat(numericString);
                    if (f.isInfinite() && !createBigDecimal(fullNumericStringForBigDecimal).stripTrailingZeros().abs().equals(BigDecimal.ZERO)) {
                        // If Float is infinite but the actual number isn't zero, it's an overflow/underflow, try higher precision.
                        // We check against BigDecimal zero to handle cases like "0.0e-50000f" which might be infinity or 0.0f
                        // but should potentially be handled by BigDecimal.
                        // The original `(f.floatValue() == 0.0F && !allZeros)` was too simplistic.
                        throw new NumberFormatException("Float overflow/underflow detected for: " + str);
                    }
                    if (f.floatValue() == 0.0F && !isZeroValue) {
                         // String represents non-zero, but float became zero due to precision loss/underflow
                        throw new NumberFormatException("Float precision loss (resulted in zero) for: " + str);
                    }
                    return f;
                } catch (NumberFormatException e) {
                    // Fall through to Double then BigDecimal for float parsing errors
                }
                // FALL-THROUGH if Float fails, try Double or BigDecimal (as in original)
            case DOUBLE:
                try {
                    Double d = createDouble(numericString);
                    if (d.isInfinite() && !createBigDecimal(fullNumericStringForBigDecimal).stripTrailingZeros().abs().equals(BigDecimal.ZERO)) {
                        throw new NumberFormatException("Double overflow/underflow detected for: " + str);
                    }
                    if (d.doubleValue() == 0.0D && !isZeroValue) {
                        throw new NumberFormatException("Double precision loss (resulted in zero) for: " + str);
                    }
                    return d;
                } catch (NumberFormatException e) {
                    // Fall through to BigDecimal for double parsing errors
                }
                // FALL-THROUGH if Double fails or was not preferred, try BigDecimal
            case NONE: // No preferred type, determine best fit
                // Integral types
                if (!hasDecimalOrExponent) {
                    try {
                        return createInteger(fullNumericStringForBigDecimal);
                    } catch (NumberFormatException e) {
                        try {
                            return createLong(fullNumericStringForBigDecimal);
                        } catch (NumberFormatException e2) {
                            try {
                                return createBigInteger(fullNumericStringForBigDecimal);
                            } catch (NumberFormatException e3) {
                                throw new NumberFormatException("Unable to parse integral number: " + str);
                            }
                        }
                    }
                } else { // Floating point without suffix - prioritize precision
                    try {
                        BigDecimal bd = createBigDecimal(fullNumericStringForBigDecimal);
                        // Check if it fits perfectly into a Double
                        try {
                            Double d = bd.doubleValue();
                            if (new BigDecimal(d.toString()).compareTo(bd) == 0) { // Check for precision loss
                                return d;
                            }
                        } catch (NumberFormatException ignore) {
                            // Can happen if bd is too big for double
                        }
                        // Check if it fits perfectly into a Float (less likely after Double check)
                        try {
                            Float f = bd.floatValue();
                            if (new BigDecimal(f.toString()).compareTo(bd) == 0) { // Check for precision loss
                                return f;
                            }
                        } catch (NumberFormatException ignore) {
                            // Can happen if bd is too big for float
                        }
                        return bd; // Default to BigDecimal for precision
                    } catch (NumberFormatException e) {
                        throw new NumberFormatException("Unable to parse floating point number: " + str);
                    }
                }
            default:
                // This case should ideally not be reached if enum is exhaustive
                throw new NumberFormatException("Unexpected internal state for number type: " + str);
        }
    }

public static String join(Object[] array, String separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }
    if (separator == null) {
        separator = ""; // Use literal "" for clarity, or refer to StringUtils.EMPTY if available
    }

    // Validate indices
    if (startIndex < 0 || startIndex > array.length) {
        throw new IndexOutOfBoundsException("startIndex must be within the bounds of the array: [0, " + array.length + "]. Given: " + startIndex);
    }
    if (endIndex < 0 || endIndex > array.length) {
        throw new IndexOutOfBoundsException("endIndex must be within the bounds of the array: [0, " + array.length + "]. Given: " + endIndex);
    }
    if (startIndex > endIndex) {
        throw new IllegalArgumentException("startIndex cannot be greater than endIndex. Given startIndex: " + startIndex + ", endIndex: " + endIndex);
    }

    int noOfItems = (endIndex - startIndex);
    if (noOfItems <= 0) {
        return ""; // Use literal "" for clarity, or refer to StringUtils.EMPTY if available
    }

    // Estimate initial capacity for StringBuilder to reduce reallocations.
    // A reasonable heuristic: average item length (e.g., 16) * number of items + (number of items - 1) * separator length.
    // This is an estimation; actual length might vary.
    int estimatedLength = 0;
    if (noOfItems > 0) {
        // Estimate for the first element
        estimatedLength += (array[startIndex] == null ? 16 : array[startIndex].toString().length());
        // Estimate for subsequent elements and separators
        estimatedLength += (noOfItems - 1) * (16 + separator.length());
    }
    // Ensure a minimum capacity to avoid very small initial buffers
    StringBuilder buf = new StringBuilder(Math.max(16, estimatedLength));

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(separator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}

public int translate(CharSequence input, int index, Writer out) throws IOException {
        // Robustness: Input validation for nulls and boundary conditions.
        if (input == null || out == null || index < 0 || index >= input.length()) {
            return 0; // Or throw IllegalArgumentException depending on desired behavior
        }

        // Check for '&#' prefix, ensuring enough characters are available for comparison.
        if (index + 1 >= input.length() || input.charAt(index) != '&' || input.charAt(index + 1) != '#') {
            return 0;
        }

        int start = index + 2;
        boolean isHex = false;

        // Robustness: Check if there's a character after "&#" for parsing.
        if (start >= input.length()) {
            return 0; // Malformed: ends with "&#"
        }

        char firstChar = input.charAt(start);
        if (firstChar == 'x' || firstChar == 'X') {
            isHex = true;
            start++;
            // Robustness: Check if there's a character after "&#x" for parsing.
            if (start >= input.length()) {
                return 0; // Malformed: ends with "&#x"
            }
        }

        int end = start;
        // Robustness: Boundary check within the loop to prevent ArrayIndexOutOfBoundsException.
        while (end < input.length() && input.charAt(end) != ';') {
            end++;
        }

        // Robustness: Ensure a semicolon was found and the entity content is not empty.
        if (end >= input.length() || input.charAt(end) != ';') {
            return 0; // No closing semicolon found or input ended prematurely.
        }
        if (end == start) {
            return 0; // Empty entity content, e.g., "&#;" or "&#x;"
        }

        int entityValue;
        try {
            String entityContent = input.subSequence(start, end).toString();
            if (isHex) {
                entityValue = Integer.parseInt(entityContent, 16);
            } else {
                entityValue = Integer.parseInt(entityContent, 10);
            }
        } catch (NumberFormatException nfe) {
            // Robustness: Handle malformed numeric content gracefully.
            return 0;
        }

        // Logical Fix: Validate entityValue against valid Unicode range.
        if (entityValue < Character.MIN_CODE_POINT || entityValue > Character.MAX_CODE_POINT) {
            return 0; // Invalid Unicode code point.
        }

        // Logical Fix: Correctly write Unicode code points, including surrogate pairs.
        // CharsetEncoder or String conversion is more robust for characters outside BMP.
        // For simplicity and directness, Character.toChars handles this correctly.
        out.write(Character.toChars(entityValue));

        // Calculate characters consumed: "&" + "#" + (optional "x") + entity_digits + ";"
        return 2 + (end - start) + (isHex ? 1 : 0) + 1;
    }

public String format(Date date) {
    // Robustness: Handle null date parameter
    if (date == null) {
        // Depending on desired behavior:
        // Option 1: Throw an IllegalArgumentException for invalid input.
        // throw new IllegalArgumentException("Date cannot be null.");
        // Option 2: Return null, indicating an inability to format.
        return null;
        // Option 3: Return an empty string, implying no date to format.
        // return "";
    }

    // Logical correction/clarification:
    // Create a new Calendar instance, ensuring it uses the FastDateFormat's configured TimeZone.
    // The GregorianCalendar(TimeZone) constructor sets the time zone.
    Calendar c = new GregorianCalendar(mTimeZone);

    // Set the time of the Calendar instance to the given Date.
    // The Date object represents a specific instant in time.
    // The Calendar instance, now configured with mTimeZone, will interpret this instant
    // according to mTimeZone when formatting rules are applied.
    c.setTime(date);

    // Create a StringBuffer with an initial estimated capacity to minimize reallocations.
    // The applyRules method is expected to populate this buffer based on the Calendar and
    // the FastDateFormat's internal formatting rules (mRules).
    StringBuffer buf = new StringBuffer(mMaxLengthEstimate);
    return applyRules(c, buf).toString();
}

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (str.trim().isEmpty()) { // Robustness: replace StringUtils.isBlank
            throw new NumberFormatException("A blank string is not a valid number");
        }

        final String trimmedStr = str.trim(); // Trim once for consistency

        // --- Hexadecimal Number Handling ---
        // Hex prefixes for Java are 0x or 0X
        final String[] hexPrefixes = {"0x", "0X", "-0x", "-0X"}; // Corrected: removed non-standard '#' and '-#'
        int pfxLen = 0;
        boolean isNegative = false;
        for (final String pfx : hexPrefixes) {
            if (trimmedStr.startsWith(pfx)) {
                pfxLen = pfx.length();
                if (pfx.startsWith("-")) {
                    isNegative = true;
                }
                break;
            }
        }

        if (pfxLen > 0) { // We have a hex number
            String hexDigitsStr = trimmedStr.substring(pfxLen);
            if (isNegative) {
                hexDigitsStr = "-" + hexDigitsStr; // Re-add negative sign for parsing
            }

            // Corrected: Parse hex string with radix 16
            // Using BigInteger for flexibility in parsing, then fitting into smaller types
            try {
                BigInteger bi = new BigInteger(hexDigitsStr, 16);

                if (bi.bitLength() < 32 && bi.compareTo(BigInteger.valueOf(Integer.MAX_VALUE)) <= 0 && bi.compareTo(BigInteger.valueOf(Integer.MIN_VALUE)) >= 0) {
                     return bi.intValueExact(); // Fits in int
                }
                if (bi.bitLength() < 64 && bi.compareTo(BigInteger.valueOf(Long.MAX_VALUE)) <= 0 && bi.compareTo(BigInteger.valueOf(Long.MIN_VALUE)) >= 0) {
                    return bi.longValueExact(); // Fits in long
                }
                return bi; // Return BigInteger if it doesn't fit in smaller types
            } catch (NumberFormatException e) {
                throw new NumberFormatException("Invalid hexadecimal number: " + str);
            }
        }

        // --- Decimal / Floating-Point Number Handling ---
        final char lastChar = trimmedStr.charAt(trimmedStr.length() - 1);
        String mant;
        String dec;
        String exp;

        final int decPos = trimmedStr.indexOf('.');
        int ePos = -1; // Position of 'e' or 'E'
        final int lowerEPOS = trimmedStr.indexOf('e');
        final int upperEPOS = trimmedStr.indexOf('E');

        if (lowerEPOS > -1 && upperEPOS > -1) {
            throw new NumberFormatException(str + " contains multiple exponent characters ('e' and 'E').");
        } else if (lowerEPOS > -1) {
            ePos = lowerEPOS;
        } else if (upperEPOS > -1) {
            ePos = upperEPOS;
        }

        // Parse mantissa, decimal, and exponent parts
        if (decPos > -1) { // There is a decimal point
            if (ePos > -1) { // There is an exponent
                if (ePos < decPos || ePos > trimmedStr.length()) { // Malformed exponent position
                    throw new NumberFormatException(str + " is not a valid number (malformed exponent).");
                }
                dec = trimmedStr.substring(decPos + 1, ePos);
            } else {
                dec = trimmedStr.substring(decPos + 1);
            }
            mant = trimmedStr.substring(0, decPos);
        } else { // No decimal point
            if (ePos > -1) {
                if (ePos > trimmedStr.length()) { // Malformed exponent position
                    throw new NumberFormatException(str + " is not a valid number (malformed exponent).");
                }
                mant = trimmedStr.substring(0, ePos);
            } else {
                mant = trimmedStr;
            }
            dec = null; // No decimal part
        }

        // Extract exponent string if present
        if (ePos > -1) {
            exp = trimmedStr.substring(ePos + 1);
        } else {
            exp = null;
        }

        // --- Specific Type Suffix Handling ---
        if (!Character.isDigit(lastChar) && lastChar != '.') { // Ends with a suffix or malformed
            final String numeric = trimmedStr.substring(0, trimmedStr.length() - 1);
            final boolean allZeros = isAllZeros(mant) && (exp == null || isAllZeros(exp));

            switch (Character.toLowerCase(lastChar)) {
                case 'l':
                    // Must be an integer type with 'l' suffix
                    if (dec != null || ePos > -1) {
                        throw new NumberFormatException(str + " is not a valid long (cannot have decimal or exponent).");
                    }
                    if (!isDigits(numeric) && !(numeric.length() > 1 && numeric.startsWith("-") && isDigits(numeric.substring(1)))) {
                        throw new NumberFormatException(str + " is not a valid long (contains non-digit characters).");
                    }
                    try {
                        return createLong(numeric);
                    } catch (final NumberFormatException nfe) {
                        return createBigInteger(numeric); // Too big for long, try BigInteger
                    }
                case 'f':
                    // Try as Float, if fails (overflow/underflow/precision), try BigDecimal
                    try {
                        final Float f = createFloat(numeric);
                        // Check for precision loss or extreme values for 'f' suffix
                        if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZeros)) {
                            return f;
                        }
                    } catch (final NumberFormatException nfe) { /* ignore, try BigDecimal */ }
                    // Fall through to BigDecimal if Float fails
                    return createBigDecimal(numeric); // Must be BigDecimal if 'f' was specified and Float failed
                case 'd':
                    // Try as Double, if fails (overflow/underflow/precision), try BigDecimal
                    try {
                        final Double d = createDouble(numeric);
                        // Check for precision loss or extreme values for 'd' suffix
                        if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZeros)) {
                            return d;
                        }
                    } catch (final NumberFormatException nfe) { /* ignore, try BigDecimal */ }
                    // Fall through to BigDecimal if Double fails
                    return createBigDecimal(numeric); // Must be BigDecimal if 'd' was specified and Double failed
                default:
                    throw new NumberFormatException(str + " is not a valid number (unrecognized suffix '" + lastChar + "').");
            }
        }

        // --- No Suffix: Determine Smallest Fitting Type ---
        final boolean allZeros = isAllZeros(mant) && (exp == null || isAllZeros(exp));

        if (decPos == -1 && ePos == -1) { // No decimal point and no exponent -> Integer types
            try {
                return createInteger(trimmedStr);
            } catch (final NumberFormatException nfe) { /* ignore */ }
            try {
                return createLong(trimmedStr);
            } catch (final NumberFormatException nfe) { /* ignore */ }
            return createBigInteger(trimmedStr);
        } else { // Decimal point or exponent present -> Floating-point types
            try {
                final Float f = createFloat(trimmedStr);
                if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZeros)) {
                    return f;
                }
            } catch (final NumberFormatException nfe) { /* ignore */ }
            try {
                final Double d = createDouble(trimmedStr);
                if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZeros)) {
                    return d;
                }
            } catch (final NumberFormatException nfe) { /* ignore */ }
            return createBigDecimal(trimmedStr);
        }
    }

@Override
    public int translate(CharSequence input, int index, Writer out) throws IOException {
        // Robustness: Handle null input gracefully if it were possible here, though generally assumed non-null
        // for CharSequenceTranslator. Assuming input is never null as per contract of parent class.

        // Robustness: Protect from ArrayIndexOutOfBounds at the beginning.
        // We need at least 4 characters for "&#X;", 3 for "&#1;" to be considered.
        // We need '&#', at least one character for the entity value, and a ';'.
        // So, minimum length of a valid entity is 4 (e.g., "&#1;").
        if (index >= input.length() - 3) { // Check if there's enough room for "&#1;" or "&#x;" (not 'x' itself, but minimum pattern)
            return 0;
        }

        if (input.charAt(index) == '&' && input.charAt(index + 1) == '#') {
            int start = index + 2;
            boolean isHex = false;

            // Robustness: Check if 'start' is within bounds before accessing.
            if (start >= input.length()) { // Malformed: ends with "&#"
                return 0;
            }

            char firstChar = input.charAt(start);
            if (firstChar == 'x' || firstChar == 'X') {
                start++;
                isHex = true;
                // Robustness: Check if 'start' is within bounds after incrementing for 'x'
                if (start >= input.length()) { // Malformed: ends with "&#x"
                    return 0;
                }
            }

            int end = start;
            // Robustness: Protect from infinite loop/ArrayIndexOutOfBounds if ';' is not found.
            // Loop until ';' or end of string.
            while (end < input.length() && input.charAt(end) != ';') {
                end++;
            }

            // Robustness: If ';' was not found, this is not a complete entity.
            if (end == input.length()) {
                return 0;
            }

            // Robustness: Ensure there's actual content between 'start' and 'end'.
            // For "&#;" or "&#x;" (after start increments), subSequence would be empty.
            if (start == end) {
                return 0; // No numeric value present (e.g., "&#;")
            }

            int entityValue;
            try {
                String numericPart = input.subSequence(start, end).toString();
                if (isHex) {
                    entityValue = Integer.parseInt(numericPart, 16);
                } else {
                    entityValue = Integer.parseInt(numericPart, 10);
                }
            } catch (NumberFormatException nfe) {
                return 0; // Not a valid number
            }

            // Robustness: Check for valid Unicode code point range.
            // Although Writer.write(int) handles surrogate pairs, a common convention for
            // numeric entities is to represent a single Unicode code point.
            // Valid code points are 0 to 0x10FFFF.
            if (entityValue < Character.MIN_CODE_POINT || entityValue > Character.MAX_CODE_POINT) {
                return 0; // Malformed entity value (out of Unicode range)
            }

            // Logic: Write the character corresponding to the parsed code point.
            out.write(entityValue);

            // Logic: Calculate consumed characters correctly.
            // 2 for "&#"
            // (end - start) for the numeric part
            // (isHex ? 1 : 0) for the 'x' if present
            // 1 for the trailing ';'
            return 2 + (end - start) + (isHex ? 1 : 0) + 1;
        }
        return 0; // Not a numeric entity starting with "&#"
    }

public String format(Date date) {
    // Robustness: Add a null check for the input 'date' parameter.
    if (date == null) {
        throw new IllegalArgumentException("Date must not be null");
    }

    // Create a new Calendar instance with the formatter's configured time zone.
    // GregorianCalendar is used as a concrete implementation of Calendar.
    Calendar c = new GregorianCalendar(mTimeZone);

    // Set the time of the calendar from the provided Date object.
    c.setTime(date);

    // Apply the formatting rules to the Calendar object, writing the result
    // into a StringBuffer initialized with an estimated maximum length
