public static <T> T[] add(final T[] array, final int index, final T element) {
        // Determine the component type of the new array
        Class<?> componentType = null;
        if (array != null) {
            componentType = array.getClass().getComponentType();
        } else if (element != null) {
            componentType = element.getClass();
        } else {
            // Both array and element are null. We cannot determine 'T'.
            // Returning Object[] {null} as a fallback, but this might lead to ClassCastException if T is specific.
            // A more robust solution might throw an exception or require T explicitly.
            // For now, mirroring original behavior's outcome, though still problematic.
            return (T[]) new Object[]{null};
        }

        // Handle null array case (create a new array with one element)
        if (array == null) {
            if (index != 0) {
                throw new IndexOutOfBoundsException("Index: " + index + ", Size: 0");
            }
            // Create a new array of the determined componentType with size 1
            @SuppressWarnings("unchecked")
            final T[] newArray = (T[]) Array.newInstance(componentType, 1);
            newArray[0] = element;
            return newArray;
        }

        // Validate the index for a non-null array
        if (index < 0 || index > array.length) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Length: " + array.length);
        }

        // Create a new array of the same component type but with one extra element
        @SuppressWarnings("unchecked")
        final T[] newArray = (T[]) Array.newInstance(componentType, array.length + 1);

        // Copy elements before the insertion point
        System.arraycopy(array, 0, newArray, 0, index);

        // Insert the new element
        newArray[index] = element;

        // Copy elements after the insertion point
        if (index < array.length) { // Only if there are elements after the insertion point
            System.arraycopy(array, index, newArray, index + 1, array.length - index);
        }

        return newArray;
    }

