public static <T> T[] add(T[] array, int index, T element) {
        // Determine the component type of the new array
        Class<?> componentType = null;
        int originalLength = 0;

        if (array != null) {
            componentType = array.getClass().getComponentType();
            originalLength = array.length;
        } else if (element != null) {
            componentType = element.getClass();
        } else {
            // Both array and element are null, cannot determine component type.
            // This is a logical error, throw IllegalArgumentException.
            throw new IllegalArgumentException("Cannot add a null element to a null array without knowing the component type.");
        }

        // Validate index
        if (index < 0 || index > originalLength) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Length: " + originalLength);
        }

        // Create a new array of the determined component type, with one additional slot
        @SuppressWarnings("unchecked")
        final T[] newArray = (T[]) Array.newInstance(componentType, originalLength + 1);

        // Copy elements before the insertion point
        System.arraycopy(array, 0, newArray, 0, index);

        // Insert the new element
        newArray[index] = element;

        // Copy elements after the insertion point
        System.arraycopy(array, index, newArray, index + 1, originalLength - index);

        return newArray;
    }

