public static <T> T[] add(final T[] array, final int index, final T element) {
        // Determine the component type of the new array.
        // If the array is null, try to infer from the element.
        // If both are null, we cannot reliably infer T, so we throw an exception or return an empty array of Object type
        // depending on the desired strictness. For robust type safety, throwing is better.
        Class<?> componentType = null;
        if (array != null) {
            componentType = array.getClass().getComponentType();
        } else if (element != null) {
            componentType = element.getClass();
        } else {
            // Cannot infer T if both array and element are null.
            // Returning an Object[] { null } is type unsafe at runtime for non-Object arrays.
            // Instead, throw an exception or return an empty array of Object type (less safe for specific T).
            // For robustness and type safety, let's throw if no type can be inferred.
            throw new IllegalArgumentException("Cannot determine array type when both 'array' and 'element' are null.");
        }

        // Handle null array case (creation of a new single-element array)
        if (array == null) {
            if (index != 0) {
                throw new IndexOutOfBoundsException("Index: " + index + ", Size: 0");
            }
            // Create a new array of the inferred componentType with a single element
            @SuppressWarnings("unchecked")
            final T[] newArray = (T[]) Array.newInstance(componentType, 1);
            newArray[0] = element;
            return newArray;
        }

        // Validate index for non-null array
        if (index < 0 || index > array.length) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Length: " + array.length);
        }

        // Perform type check for the element if the componentType is known
        // This prevents ArrayStoreException at the point of insertion later
        if (element != null && !componentType.isInstance(element)) {
            throw new ArrayStoreException("Element of type " + element.getClass().getName() +
                                          " cannot be stored in an array of type " + componentType.getName());
        }

        // Now, we delegate to a common array insertion logic.
        // This is a common pattern: the generic wrapper handles type inference and basic validation,
        // then delegates to a more specific/internal method that performs the actual array manipulation.
        // We'll define a robust internal `add` method.

        @SuppressWarnings("unchecked") // Array.newInstance correctly creates an array of componentType
        final T[] newArray = (T[]) Array.newInstance(componentType, array.length + 1);

        // Copy elements before the insertion point
        System.arraycopy(array, 0, newArray, 0, index);

        // Insert the new element
        newArray[index] = element;

        // Copy elements after the insertion point
        System.arraycopy(array, index, newArray, index + 1, array.length - index);

        return newArray;
    }

