        // Returning 0 is the standard behavior for CharSequenceTranslator when no match occurs.
        return 0;
    }

    int currentMaxSearchLength = longest;
    // Adjust currentMaxSearchLength if the remaining part of the input is shorter than 'longest'
    if (index + currentMaxSearchLength > input.length()) {
        currentMaxSearchLength = input.length() - index;
    }

    // Descend so as to get a greedy algorithm, matching the longest possible sequence first.
    // Iterate from the maximum possible length down to the shortest length.
    for (int i = currentMaxSearchLength; i >= shortest; i--) {
        // Ensure the current subsequence length 'i' does not cause an IndexOutOfBoundsException
        // when combined with 'index'. This check is largely redundant due to currentMaxSearchLength calculation,
        // but good for explicit safety, especially if 'shortest' could be problematic.
        if (index + i > input.length()) {
