        }

        final CharSequence subSeq = input.subSequence(index, index + i);
        final CharSequence result = lookupMap.get(subSeq);
        if (result != null) {
            out.write(result.toString());
            return i; // Return the number of characters consumed from the input
        }
    }
    return 0; // No translation found at the given index
}

public static boolean isNumber(final String str) {
        if (StringUtils.isEmpty(str)) { // Use final for parameter as good practice
            return false;
        }

        final char[] chars = str.toCharArray();
        int sz = chars.length;
        boolean hasExp = false;
        boolean hasDecPoint = false;
        boolean allowSigns = false; // Flag to indicate if a sign is allowed at the current position (e.g., after 'e'/'E')
        boolean foundDigit = false;

        // Deal with any possible sign at the beginning of the string
        int start = 0;
        if (chars[0] == '-' || chars[0] == '+') {
            start = 1;
        }

        // Check for "0x" prefix for hexadecimal numbers
        if (sz > start + 1 && chars[start] == '0' && chars[start + 1] == 'x') {
            int i = start + 2;
            if (i == sz) {
                return false; // str == "0x" or "+0x" or "-0x" (no hex digits)
            }
            // Checking hexadecimal characters
            for (; i < chars.length; i++) {
                if (!((chars[i] >= '0' && chars[i] <= '9') ||
                      (chars[i] >= 'a' && chars[i] <= 'f') ||
                      (chars[i] >= 'A' && chars[i] <= 'F'))) {
                    return false; // Invalid hex character
                }
            }
            return true; // Valid hexadecimal number
        }

        // --- Main loop for decimal/floating-point numbers ---
        sz--; // Decrement size to handle potential type qualifier at the very end
        int i = start;

        // Loop through characters, processing digits, decimal points, and exponents
        // The condition `i < sz || (i < sz + 1 && allowSigns && !foundDigit)` ensures
        // we process characters up to (but not including) the last one,
        // unless a sign is allowed and we haven't found a digit yet (e.g., "1E-").
        while (i < sz || (i < chars.length && allowSigns && !foundDigit)) {
            if (chars[i] >= '0' && chars[i] <= '9') {
                foundDigit = true;
                allowSigns = false; // A digit invalidates the need for a sign immediately after
            } else if (chars[i] == '.') {
                if (hasDecPoint || hasExp) {
                    // Two decimal points, or a decimal point within an exponent part (e.g., "1E1.2")
                    return false;
                }
                hasDecPoint = true;
            } else if (chars[i] == 'e' || chars[i] == 'E') {
                if (hasExp) {
                    return false; // Two 'e' or 'E' characters
                }
                if (!foundDigit) {
                    // An 'e' or 'E' must be preceded by at least one digit (e.g., ".E1", "E1" are invalid)
                    return false;
                }
                hasExp = true;
                allowSigns = true; // A sign is allowed immediately after 'e'/'E' (e.g., "1e+5", "1e-5")
                foundDigit = false; // Reset foundDigit to ensure a digit follows the 'e' or 'E' (or its sign)
            } else if (chars[i] == '+' || chars[i] == '-') {
                if (!allowSigns) {
                    // Sign only allowed at the beginning or immediately after 'e'/'E'
                    return false;
                }
                allowSigns = false; // Consume the sign, no more signs immediately after
                foundDigit = false; // We need a digit after this sign in the exponent
            } else {
                return false; // Invalid character found
            }
            i++;
        }

        // --- Post-loop check for the last character (potential type qualifier or a digit) ---
        if (i < chars.length) { // If there's a character remaining after the loop
            if (chars[i] >= '0' && chars[i] <= '9') {
                // The last character is a digit, no type qualifier, this is a valid number.
                // This covers cases like "123", "1.23", "123e4"
                return foundDigit; // Ensure at least one digit was found overall
            }
            if (chars[i] == 'e' || chars[i] == 'E') {
                // An 'e' or 'E' cannot be the last character (e.g., "123E")
                return false;
            }
            if (!allowSigns && (chars[i] == 'd' || chars[i] == 'D' || chars[i] == 'f' || chars[i] == 'F')) {
                // 'd', 'D', 'f', 'F' qualifiers for floating-point numbers
                return foundDigit; // Must have at least one digit before the qualifier
            }
            if (chars[i] == 'l' || chars[i] == 'L') {
                // 'l', 'L' qualifier for long integers
                // A long cannot have a decimal point or an exponent
                return foundDigit && !hasExp && !hasDecPoint;
            }
            // Any other character at the end is illegal (e.g., "123G")
            return false;
        }

        // If the loop finished and there are no characters left, or the last char was handled
        // `allowSigns` being true here implies the number ends with 'e' or 'E' or 'e+' or 'e-', without a trailing digit.
        // `foundDigit` ensures that at least one digit was found at some point.
        return !allowSigns && foundDigit;
    }

