                return false;
            }
            // Check for valid hexadecimal digits
            for (; i < len; i++) {
                if (!((chars[i] >= '0' && chars[i] <= '9') ||
                      (chars[i] >= 'a' && chars[i] <= 'f') ||
                      (chars[i] >= 'A' && chars[i] <= 'F'))) {
                    return false;
                }
            }
            return true; // Valid hexadecimal number
        }

        // Main loop for decimal/scientific numbers
