        for (; i < len; i++) {
            if (chars[i] >= '0' && chars[i] <= '9') {
                foundDigit = true;
                allowSignsInExponent = false; // A digit invalidates allowing a sign before it (unless it's an exponent sign)
            } else if (chars[i] == '.') {
