                    return false;
                }
                hasExp = true;
                foundDigit = false; // Reset foundDigit, as we need digits *after* the exponent sign
                allowSignsInExponent = true; // Allow a sign immediately after 'e'/'E'
            } else if (chars[i] == '+' || chars[i] == '-') {
                if (!allowSignsInExponent) {
                    // Sign in a disallowed position (e.g., "1-2", "++1", "1.+2")
                    return false;
                }
                allowSignsInExponent = false; // Only one sign allowed after 'e'/'E'
