        if (decPos > -1) { // Has a decimal point
            if (ePos > -1) { // Has decimal and exponent
                dec = s.substring(decPos + 1, ePos);
                mant = s.substring(0, decPos);
                exp = s.substring(ePos + 1);
            } else { // Has only decimal
                dec = s.substring(decPos + 1);
                mant = s.substring(0, decPos);
            }
        } else { // No decimal point
            if (ePos > -1) { // Has exponent but no decimal
                mant = s.substring(0, ePos);
                exp = s.substring(ePos + 1);
            } else { // Neither decimal nor exponent
                mant = s;
            }
        }

        // Check for type suffix
        char lastChar = s.charAt(s.length() - 1);
        boolean hasTypeSuffix = !Character.isDigit(lastChar) &&
                                Character.isLetter(lastChar) &&
                                "lLfFdD".indexOf(lastChar) != -1;

        String numericPart = s; // The actual numeric string without type suffix

        if (hasTypeSuffix) {
            numericPart = s.substring(0, s.length() - 1);
            // Re-parse components for the numericPart if a suffix was present
            decPos = numericPart.indexOf('.');
            ePos = -1;
            eIndexLower = numericPart.indexOf('e');
            eIndexUpper = numericPart.indexOf('E');
            if (eIndexLower > -1) ePos = eIndexLower;
            if (eIndexUpper > -1 && (ePos == -1 || eIndexUpper < ePos)) ePos = eIndexUpper;

            // Recalculate mant, dec, exp based on numericPart
            if (decPos > -1) {
                if (ePos > -1) {
                    dec = numericPart.substring(decPos + 1, ePos);
                    mant = numericPart.substring(0, decPos);
                    exp = numericPart.substring(ePos + 1);
                } else {
                    dec = numericPart.substring(decPos + 1);
                    mant = numericPart.substring(0, decPos);
                    exp = null; // No exponent in numeric part
                }
            } else {
                if (ePos > -1) {
                    mant = numericPart.substring(0, ePos);
                    exp = numericPart.substring(ePos + 1);
                    dec = null; // No decimal in numeric part
                } else {
                    mant = numericPart;
                    dec = null;
                    exp = null; // No decimal or exponent in numeric part
                }
            }
        }

        // After all parsing, if mantissa or dec/exp are empty, it's invalid
        if (mant != null && mant.isEmpty() && (dec == null || dec.isEmpty()) && (exp == null || exp.isEmpty())) {
             // Cases like "." ".e1" "e1" (empty mantissa)
            throw new NumberFormatException(s + " is not a valid number. Mantissa cannot be empty without a valid decimal or exponent part.");
        }

        // Ensure that mant, dec, exp are never null for isAllZeros, pass empty string instead
        String checkMant = mant == null ? "" : mant;
        String checkDec = dec == null ? "" : dec;
        String checkExp = exp == null ? "" : exp;

        // Handle type-hinted numbers
        if (hasTypeSuffix) {
            switch (Character.toLowerCase(lastChar)) {
                case 'l':
                    // Longs cannot have decimal points or exponents
                    if (decPos > -1 || ePos > -1) {
                        throw new NumberFormatException(s + " is not a valid long number. Longs cannot contain decimal points or exponents.");
                    }
                    try {
                        return NumberUtils.createLong(numericPart);
                    } catch (NumberFormatException nfe) {
                        // Too big for a long, try BigInteger
                        try {
                            return NumberUtils.createBigInteger(numericPart);
                        } catch (NumberFormatException bigNfe) {
                            throw new NumberFormatException(s + " is not a valid long or big integer: " + bigNfe.getMessage());
                        }
                    }
                case 'f':
                    boolean allZerosF = isAllZeros(checkMant) && isAllZeros(checkDec) && isAllZeros(checkExp);
                    try {
                        Float f = NumberUtils.createFloat(numericPart);
                        // Check for precision issues or overflow/underflow
                        if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZerosF && (numericPart.contains("1") || numericPart.contains("2") || numericPart.contains("3") || numericPart.contains("4") || numericPart.contains("5") || numericPart.contains("6") || numericPart.contains("7") || numericPart.contains("8") || numericPart.contains("9")))) {
                            return f;
                        }
                    } catch (NumberFormatException ignore) {
                        // Fall through to BigDecimal if float parse fails
                    }
                    // Fall through to 'd' and then BigDecimal
                case 'd':
                    boolean allZerosD = isAllZeros(checkMant) && isAllZeros(checkDec) && isAllZeros(checkExp);
                    try {
                        Double d = NumberUtils.createDouble(numericPart);
                        // Check for precision issues or overflow/underflow
                        if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZerosD && (numericPart.contains("1") || numericPart.contains("2") || numericPart.contains("3") || numericPart.contains("4") || numericPart.contains("5") || numericPart.contains("6") || numericPart.contains("7") || numericPart.contains("8") || numericPart.contains("9")))) {
                            return d;
                        }
                    } catch (NumberFormatException ignore) {
                        // Fall through to BigDecimal if double parse fails
                    }
                    try {
                        return NumberUtils.createBigDecimal(numericPart);
                    } catch (NumberFormatException bigNfe) {
                        throw new NumberFormatException(s + " is not a valid decimal number: " + bigNfe.getMessage());
                    }
                default:
                    // Should not be reached due to hasTypeSuffix check, but for safety
                    throw new NumberFormatException(s + " is not a valid number with recognized type suffix.");
            }
        } else {
            // No type suffix, determine type based on content
            if (decPos == -1 && ePos == -1) { // Integer types
                try {
                    return NumberUtils.createInteger(s);
                } catch (NumberFormatException nfe) {
                    try {
                        return NumberUtils.createLong(s);
                    } catch (NumberFormatException nfe2) {
                        return NumberUtils.createBigInteger(s);
                    }
                }
            } else { // Floating point types
                boolean allZerosFloat = isAllZeros(checkMant) && isAllZeros(checkDec) && isAllZeros(checkExp);
                try {
                    Float f = NumberUtils.createFloat(s);
                    if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZerosFloat && (s.contains("1") || s.contains("2") || s.contains("3") || s.contains("4") || s.contains("5") || s.contains("6") || s.contains("7") || s.contains("8") || s.contains("9")))) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // empty catch
                }
                try {
                    Double d = NumberUtils.createDouble(s);
                    if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZerosFloat && (s.contains("1") || s.contains("2") || s.contains("3") || s.contains("4") || s.contains("5") || s.contains("6") || s.contains("7") || s.contains("8") || s.contains("9")))) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // empty catch
                }
                return NumberUtils.createBigDecimal(s);
            }
        }
    }

public static String getShortClassName(String className) {
    if (className == null || className.length() == 0) {
        return StringUtils.EMPTY;
    }

    StringBuilder shortNameBuilder = new StringBuilder();
    int arrayDepth = 0;
    while (className.startsWith("[")) {
        arrayDepth++;
        className = className.substring(1);
    }

    if (arrayDepth > 0) {
        if (className.length() == 0) { // e.g., only "[[["
             // This case is unlikely from Class.getName(), but defensive
            return StringUtils.EMPTY;
        }

        // Handle primitive types for arrays
        if (className.length() == 1) {
            char primitiveChar = className.charAt(0);
            String primitiveName = null;
            switch (primitiveChar) {
                case 'Z': primitiveName = "boolean"; break;
                case 'B': primitiveName = "byte"; break;
                case 'C': primitiveName = "char"; break;
                case 'D': primitiveName = "double"; break;
                case 'F': primitiveName = "float"; break;
                case 'I': primitiveName = "int"; break;
                case 'J': primitiveName = "long"; break;
                case 'S': primitiveName = "short"; break;
            }
            if (primitiveName != null) {
                shortNameBuilder.append(primitiveName);
            } else { // Unknown primitive char or malformed
                shortNameBuilder.append(className); // Fallback to raw char
            }
        } else if (className.startsWith("L") && className.endsWith(";")) {
            // Strip Object type encoding: Lfully.qualified.ClassName;
            className = className.substring(1, className.length() - 1);
            // Now className is "fully.qualified.ClassName"
            int lastDotIdx = className.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
            String baseName = className.substring(lastDotIdx + 1);
            String processedBaseName = baseName.replace(INNER_CLASS_SEPARATOR_CHAR, PACKAGE_SEPARATOR_CHAR);
            shortNameBuilder.append(processedBaseName);
        } else {
            // This could be a non-standard array encoding for objects without 'L;'
            // or just a malformed string. We'll try to process it as a regular class name.
            int lastDotIdx = className.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
            String baseName = className.substring(lastDotIdx + 1);
            String processedBaseName = baseName.replace(INNER_CLASS_SEPARATOR_CHAR, PACKAGE_SEPARATOR_CHAR);
            shortNameBuilder.append(processedBaseName);
        }

        for (int i = 0; i < arrayDepth; i++) {
            shortNameBuilder.append("[]");
        }
    } else {
        // Not an array type, process as a regular class name
        int lastDotIdx = className.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
        String out = className.substring(lastDotIdx + 1);
        int innerIdx = out.indexOf(INNER_CLASS_SEPARATOR_CHAR); // Check in 'out' only
        if (innerIdx != -1) {
            out = out.replace(INNER_CLASS_SEPARATOR_CHAR, PACKAGE_SEPARATOR_CHAR);
        }
        shortNameBuilder.append(out);
    }

    return shortNameBuilder.toString();
}

public static Number createNumber(String val) throws NumberFormatException {
        if (val == null) {
            return null;
        }
        if (val.isEmpty()) { // Use isEmpty() for clarity and robustness
            throw new NumberFormatException("\"\" is not a valid number.");
        }
        if (val.startsWith("--")) {
            // Consistent error handling: an invalid format should throw an exception.
            // BigDecimal can handle it, but standard Number classes cannot, and it's ambiguous.
            throw new NumberFormatException("String starts with double dash: " + val);
        }

        // Handle hexadecimal prefixes early
        if (val.startsWith("0x") || val.startsWith("-0x")) {
            // Assuming createInteger correctly handles hex (Integer.decode does)
            try {
                return createInteger(val);
            } catch (NumberFormatException nfe) {
                // If createInteger fails for a valid hex (e.g., too big for Integer), try BigInteger
                try {
                    // BigInteger constructor does not support "0x" prefix directly, so remove it.
                    // If createInteger supports hex, it's better to stick with it or provide a specific createHexBigInteger.
                    // For now, let's assume createInteger is the primary hex parser.
                    // If it fails, BigInteger needs the radix for hex, which is not handled by the simple createBigInteger(val).
                    // This implies a need for a createHexBigInteger or more robust createBigInteger that infers radix.
                    // For this correction, let's simplify and assume createInteger covers hex sufficiently for common cases.
                    // If it's too big for Integer, it's very likely to be an invalid hex string if createLong also fails.
                    // Realistically, we'd need a specific hex parser for BigInteger.
                    // Let's re-evaluate: Integer.decode and Long.decode handle hex. BigInteger(String) does not.
                    // If the number is too big for Long but is hex, BigInteger needs BigInteger(String, radix).
                    // This requires more dedicated hex parsing. For now, we'll try createLong and then BigInteger directly
                    // which implicitly assumes decimal for BigInteger(val). This is a gap in the original design if hex can be huge.
                    // A better approach would be:
                    String hexValue = val.startsWith("-0x") ? "-" + val.substring(3) : val.substring(2);
                    return new BigInteger(hexValue, 16); // Explicitly parse as hex
                } catch (NumberFormatException e) {
                    throw new NumberFormatException("Invalid hexadecimal number: " + val);
                }
            }
        }

        char lastChar = val.charAt(val.length() - 1);
        String mant; // Mantissa part
        String dec;  // Decimal part (after dot, before exponent)
        String exp;  // Exponent part (after 'e'/'E')

        int decPos = val.indexOf('.');
        // Correctly find exponent position: first 'e' or 'E'
        int ePos = val.indexOf('e');
        int EPos = val.indexOf('E');
        int expCharPos = -1; // Position of 'e' or 'E'
        if (ePos > -1 && EPos > -1) {
            expCharPos = Math.min(ePos, EPos);
        } else if (ePos > -1) {
            expCharPos = ePos;
        } else if (EPos > -1) {
            expCharPos = EPos;
        }

        if (decPos > -1) {
            if (expCharPos > -1) {
                if (expCharPos < decPos) {
                    throw new NumberFormatException(val + " is not a valid number (exponent before decimal).");
                }
                dec = val.substring(decPos + 1, expCharPos);
            } else {
                dec = val.substring(decPos + 1);
            }
            mant = val.substring(0, decPos);
        } else { // No decimal point
            if (expCharPos > -1) {
                mant = val.substring(0, expCharPos);
            } else {
                mant = val;
            }
            dec = null; // No decimal part
        }

        // Parse exponent string
        if (expCharPos > -1) {
             // If lastChar is a type suffix, exponent should not include it.
            if (!Character.isDigit(lastChar) && expCharPos < val.length() - 1) {
                exp = val.substring(expCharPos + 1, val.length() - 1);
            } else if (Character.isDigit(lastChar) && expCharPos < val.length() - 1) {
                exp = val.substring(expCharPos + 1);
            } else { // Exponent char is the last char, or no chars after it
                 exp = null; // This case might be invalid, e.g., "1e", "1.2e"
                 if (expCharPos == val.length() - 1) {
                     throw new NumberFormatException("Invalid number format, exponent indicator without digits: " + val);
                 }
            }
        } else {
            exp = null;
        }


        if (!Character.isDigit(lastChar)) {
            // Requesting a specific type..
            String numeric = val.substring(0, val.length() - 1); // Value without type suffix
            boolean allZerosString = isAllZeros(mant) && isAllZeros(dec) && isAllZeros(exp); // More robust check

            switch (Character.toLowerCase(lastChar)) { // Use toLowerCase for case-insensitivity in switch
                case 'l':
                    if (dec == null && exp == null) {
                        // Check if numeric string represents a valid integer
                        if (!isDigits(numeric) && !(numeric.startsWith("-") && isDigits(numeric.substring(1)))) {
                            throw new NumberFormatException(val + " is not a valid integer for type Long.");
                        }
                        try {
                            return createLong(numeric);
                        } catch (NumberFormatException nfe) {
                            // Too big for a long, try BigInteger
                            try {
                                return createBigInteger(numeric);
                            } catch (NumberFormatException bigNfe) {
                                throw new NumberFormatException("Invalid number for BigInteger: " + numeric, bigNfe);
                            }
                        }
                    }
                    throw new NumberFormatException(val + " is not a valid Long format (decimal or exponent present).");

                case 'f':
                    // If user explicitly asks for float, try float first.
                    // If float is infinite or precision is lost (non-zero string becomes zero), fallback.
                    try {
                        Float f = createFloat(numeric);
                        // Check for infinity or significant underflow (non-zero source becoming zero)
                        if (Float.isInfinite(f) || (f.floatValue() == 0.0F && !allZerosString)) {
                            // Precision loss or overflow, try Double or BigDecimal.
                            // Fall through to 'd' case to try Double first.
                            break; // break from switch, continue to try 'd'
                        }
                        return f;
                    } catch (NumberFormatException e) {
                        // Not a valid float, try Double or BigDecimal.
                        break; // break from switch, continue to try 'd'
                    }

                case 'd':
                    // Try Double
                    try {
                        Double d = createDouble(numeric);
                        // Check for infinity or significant underflow (non-zero source becoming zero)
                        if (Double.isInfinite(d) || (d.doubleValue() == 0.0D && !allZerosString)) {
                             // Precision loss or overflow, try BigDecimal.
                             break; // break from switch, continue to try BigDecimal after switch
                        }
                        return d;
                    } catch (NumberFormatException nfe) {
                        // Not a valid double, fall through to BigDecimal.
                        break; // break from switch, continue to try BigDecimal after switch
                    }

                default:
                    throw new NumberFormatException(val + " has an unsupported type suffix: " + lastChar);
            }
            // If float or double conversion failed or indicated precision loss,
            // or if we broke out of 'f' or 'd' cases, attempt BigDecimal.
            try {
                return createBigDecimal(numeric);
            } catch (NumberFormatException e) {
                throw new NumberFormatException("Failed to parse as BigDecimal after type suffix attempt: " + val, e);
            }

        } else { // No type suffix, lastChar is a digit
            // User doesn't have a preference on the return type, so let's start
            // small and go from there...

            // Recalculate exp with full string if no suffix
            if (expCharPos > -1 && expCharPos < val.length() - 1) { // Ensure there are digits after 'e'/'E'
                exp = val.substring(expCharPos + 1);
            } else {
                exp = null;
            }

            if (dec == null && exp == null) {
                // Must be an int,long,bigint
                try {
                    return createInteger(val);
                } catch (NumberFormatException nfe) {
                    try {
                        return createLong(val);
                    } catch (NumberFormatException nfe2) {
                        try {
                            return createBigInteger(val);
                        } catch (NumberFormatException bigNfe) {
                            throw new NumberFormatException("Invalid integral number: " + val, bigNfe);
                        }
                    }
                }
            } else {
                // Must be a float,double,BigDec
                boolean allZerosString = isAllZeros(mant) && isAllZeros(dec) && isAllZeros(exp);
                try {
                    Float f = createFloat(val);
                    if (Float.isInfinite(f) || (f.floatValue() == 0.0F && !allZerosString)) {
                         // Precision loss or overflow, try Double.
                         // Do not return f, fall through.
                    } else {
                        return f; // Return float if it's good enough
                    }
                } catch (NumberFormatException nfe) {
                    // Cannot parse as Float, fall through.
                }

                try {
                    Double d = createDouble(val);
                    if (Double.isInfinite(d) || (d.doubleValue() == 0.0D && !allZerosString)) {
                        // Precision loss or overflow, try BigDecimal.
                        // Do not return d, fall through.
                    } else {
                        return d; // Return double if it's good enough
                    }
                } catch (NumberFormatException nfe) {
                    // Cannot parse as Double, fall through.
                }

                try {
                    return createBigDecimal(val);
                } catch (NumberFormatException e) {
                    throw new NumberFormatException("Invalid decimal/exponent number: " + val, e);
                }
            }
        }
    }

public static <T> T[] add(T[] array, T element) {
        Class<?> componentType;
        int newLength;

        if (array != null) {
            componentType = array.getClass().getComponentType();
            newLength = array.length + 1;
        } else if (element != null) {
            componentType = element.getClass();
            newLength = 1;
        } else {
            // Both array and element are null. Default to Object.class to create an array
            // that can hold a null element. The return type will technically be Object[]
            // but is cast to T[] due to type erasure.
            componentType = Object.class;
            newLength = 1;
        }

        // Create a new array of the correct component type and size
        @SuppressWarnings("unchecked")
        T[] newArray = (T[]) Array.newInstance(componentType, newLength);

        // Copy existing elements if the original array was not null
        if (array != null) {
            System.arraycopy(array, 0, newArray, 0, array.length);
        }

        // Add the new element at the last position
        newArray[newLength - 1] = element;
        return newArray;
    }

