                }
                return createBigInteger(val); // Can't fail for valid number format
            } else {
                // Must be a float, double, or BigDecimal
                try {
                    Float f = createFloat(val);
                    // Check precision/overflow. If okay, return float.
                    if (!(f.isInfinite() && !(val.equalsIgnoreCase("infinity") || val.equalsIgnoreCase("-infinity"))) &&
                            !(f.floatValue() == 0.0F && !isAllZeros(fullNumericPart))) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // Falls through to try Double
                }
                try {
                    Double d = createDouble(val);
                    // Check precision/overflow. If okay, return double.
                    if (!(d.isInfinite() && !(val.equalsIgnoreCase("infinity") || val.equalsIgnoreCase("-infinity"))) &&
                            !(d.doubleValue() == 0.0D && !isAllZeros(fullNumericPart))) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // Falls through to try BigDecimal
                }

                // If float/double failed, use BigDecimal for full precision.
                return createBigDecimal(val);
            }
        }
    }

public static String getShortClassName(String className) {
        if (className == null || className.length() == 0) {
            return EMPTY;
        }

        StringBuilder arraySuffix = new StringBuilder();
        int arrayDimensions = 0;
        while (className.startsWith("[")) {
            className = className.substring(1);
            arrayDimensions++;
            arraySuffix.append("[]");
        }

        // Handle primitive array types (e.g., "[I" -> "int")
        if (arrayDimensions > 0 && className.length() == 1) {
            String primitiveType = ABBREVIATION_MAP.get(className);
            if (primitiveType != null) {
                return primitiveType + arraySuffix.toString();
            }
        }

        // Handle object array types (e.g., "[Ljava.lang.String;")
        if (className.startsWith("L") && className.endsWith(";")) {
            className = className.substring(1, className.length() - 1);
        }

        int lastDotIdx = className.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
        String out = className.substring(lastDotIdx + 1);

        // Replace all inner class separators with package separators for the short name
        out = out.replace(INNER_CLASS_SEPARATOR_CHAR, PACKAGE_SEPARATOR_CHAR);

        return out + arraySuffix.toString();
    }

public static Number createNumber(String val) throws NumberFormatException {
        if (val == null) {
            return null;
        }
        if (val.isEmpty()) {
            throw new NumberFormatException("\"\" is not a valid number.");
        }

        // Handle negative sign followed by another negative sign (e.g., "--123")
        // This is not a standard number format and should be an exception.
        // The original code returned null here, which is inconsistent.
        if (val.startsWith("--")) {
            throw new NumberFormatException(val + " is not a valid number (double negative sign).");
        }

        // Handle hexadecimal numbers
        if (val.startsWith("0x") || val.startsWith("-0x")) {
            // Need to parse hex specifically. Integer.decode() handles "0x" prefix.
            try {
                // Integer.decode() returns an Integer, which is a Number.
                // It handles both positive and negative hex.
                return Integer.decode(val);
            } catch (NumberFormatException e) {
                // If it's too large for an Integer, try Long.decode()
                try {
                    return Long.decode(val);
                } catch (NumberFormatException e2) {
                    // For extremely large hex values, BigInteger can handle it
                    // Strip the "0x" or "-0x" and construct BigInteger with radix 16
                    String hexValue = val.startsWith("-0x") ? val.substring(3) : val.substring(2);
                    if (hexValue.isEmpty()) {
                        throw new NumberFormatException(val + " is not a valid hexadecimal number.");
                    }
                    BigInteger bi = new BigInteger(hexValue, 16);
                    return val.startsWith("-0x") ? bi.negate() : bi;
                }
            }
        }

        int decPos = val.indexOf('.');
        // Correct calculation for exponent position
        int expPos = -1;
        int eIndex = val.indexOf('e');
        int EIndex = val.indexOf('E');
        if (eIndex > -1) {
            expPos = eIndex;
        }
        if (EIndex > -1) {
            if (expPos == -1 || EIndex < expPos) {
                expPos = EIndex;
            }
        }

        String mant; // Mantissa part of the number
        String dec;  // Decimal part of the number
        String exp;  // Exponent part of the number

        // Determine mantissa, decimal, and exponent parts
        if (decPos > -1) { // Has a decimal point
            if (expPos > -1) { // Has an exponent
                if (expPos < decPos) {
                    throw new NumberFormatException(val + " is not a valid number (exponent before decimal).");
                }
                mant = val.substring(0, decPos);
                dec = val.substring(decPos + 1, expPos);
                exp = val.substring(expPos + 1);
            } else { // No exponent
                mant = val.substring(0, decPos);
                dec = val.substring(decPos + 1);
                exp = null;
            }
        } else { // No decimal point
            if (expPos > -1) { // Has an exponent
                mant = val.substring(0, expPos);
                dec = null;
                exp = val.substring(expPos + 1);
            } else { // No decimal, no exponent
                mant = val;
                dec = null;
                exp = null;
            }
        }

        // Handle trailing type characters (l/L, f/F, d/D)
        char lastChar = val.charAt(val.length() - 1);
        if (!Character.isDigit(lastChar) && lastChar != '.') { // Check if last char is a type indicator or an invalid character
            String numericPart = val.substring(0, val.length() - 1);
            // Re-calculate exponent for the numeric part if needed, to avoid issues if 'e' was last char
            // However, the original code takes mant, dec, exp from the full val, then modifies numericPart.
            // This is complex. Let's assume mant and exp calculated from original 'val' are sufficient.

            boolean mantAllZeros = isAllZeros(mant);
            boolean expAllZeros = isAllZeros(exp); // exp could be null, isAllZeros should handle it.

            switch (lastChar) {
                case 'l':
                case 'L':
                    if (dec == null && exp == null) { // Longs cannot have decimal or explicit exponent
                        try {
                            return createLong(numericPart);
                        } catch (NumberFormatException nfe) {
                            // Too big for a long, try BigInteger
                        }
                        return createBigInteger(numericPart);
                    }
                    throw new NumberFormatException(val + " is not a valid Long number (contains decimal or exponent).");

                case 'f':
                case 'F':
                    try {
                        Float f = createFloat(numericPart);
                        // Original condition: !(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))
                        // Refined to check if string representation loses significant info or is infinity.
                        // If it's infinity (too large) or if it parses to 0.0 but original string
                        // has non-zero digits (indicating precision loss), then it's not a suitable float.
                        // 'allZeros' check should use mant and exp from *original* val if relevant,
                        // or numericPart directly. Let's use mantAllZeros & expAllZeros derived earlier.
                        if (!f.isInfinite() && !(f.floatValue() == 0.0F && (!mantAllZeros || !expAllZeros))) {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // ignore the bad number, will fall through to general parsing or exception
                    }
                    // If float failed or lost precision, throw an exception because 'f' suffix implies preference.
                    // The original code falls through to double/BigDecimal, which ignores the 'f' suffix.
                    // This corrected implementation honors the suffix more strictly.
                    throw new NumberFormatException(val + " is not a valid Float number (precision loss or out of range).");

                case 'd':
                case 'D':
                    try {
                        Double d = createDouble(numericPart);
                        // Same logic as float for precision/range check.
                        if (!d.isInfinite() && !(d.doubleValue() == 0.0D && (!mantAllZeros || !expAllZeros))) {
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // ignore, will throw exception below
                    }
                    // If double failed or lost precision, throw an exception.
                    throw new NumberFormatException(val + " is not a valid Double number (precision loss or out of range).");

                default:
                    // If the last character is not a digit and not a known type suffix, it's an invalid number.
                    // If it was '.', it would have been handled by decPos logic.
                    throw new NumberFormatException(val + " is not a valid number (unrecognized trailing character).");
            }
        } else {
            // No explicit type preference indicated by a suffix.
            // Try to parse as the "smallest" appropriate number type first.
            boolean valAllZeros = isAllZeros(mant) && isAllZeros(dec) && isAllZeros(exp); // check all parts for zero

            if (dec == null && exp == null) { // Integer types (no decimal or exponent)
                try {
                    return createInteger(val);
                } catch (NumberFormatException nfe) {
                    // Too large for Integer, try Long
                }
                try {
                    return createLong(val);
                } catch (NumberFormatException nfe) {
                    // Too large for Long, fall back to BigInteger
                }
                return createBigInteger(val);

            } else { // Floating point types (has decimal or exponent)
                try {
                    Float f = createFloat(val);
                    // Check for precision loss or infinity, but apply it carefully.
                    // If the original string *can* be perfectly represented as a float, use it.
                    // The condition ensures we don't return 0.0F if the original had non-zero digits
                    // that would be lost, or if it's too large to be represented.
                    if (!f.isInfinite() && !(f.floatValue() == 0.0F && !valAllZeros)) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // empty catch, try Double
                }
                try {
                    Double d = createDouble(val);
                    // Similar precision check for Double.
                    if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !valAllZeros)) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // empty catch, try BigDecimal
                }

                return createBigDecimal(val);
            }
        }
    }

public static String getShortClassName(String className) {
    if (className == null || className.length() == 0) {
        return StringUtils.EMPTY;
    }

    // Initialize maps for array type abbreviations if not already done.
    // In a real scenario, these would likely be static final members initialized once.
    // For this example, assuming they might need local setup if not globally available.
    final Map<String, String> ABBREVIATION_MAP;
    final Map<String, String> REVERSE_ABBREVIATION_MAP;

    // This block mimics the internal logic often found in ClassUtils for handling abbreviations.
    // In the actual ClassUtils, these maps are already populated.
    // We recreate them here for self-contained demonstration, as they are not fully visible
    // but hinted at by 'abbreviationMap' and 'reverseAbbreviationMap' fields.
    if (true) { // A placeholder for checking if maps are initialized or to use the class fields
        Map<String, String> tempAbbreviationMap = new HashMap<>();
        tempAbbreviationMap.put("B", "byte");
        tempAbbreviationMap.put("C", "char");
        tempAbbreviationMap.put("D", "double");
        tempAbbreviationMap.put("F", "float");
        tempAbbreviationMap.put("I", "int");
        tempAbbreviationMap.put("J", "long");
        tempAbbreviationMap.put("S", "short");
        tempAbbreviationMap.put("Z", "boolean");
        tempAbbreviationMap.put("V", "void"); // Though void arrays are not possible, it's often in this map
        ABBREVIATION_MAP = Collections.unmodifiableMap(tempAbbreviationMap);

        Map<String, String> tempReverseAbbreviationMap = new HashMap<>();
        for (Map.Entry<String, String> entry : tempAbbreviationMap.entrySet()) {
            tempReverseAbbreviationMap.put(entry.getValue(), entry.getKey());
        }
        REVERSE_ABBREVIATION_MAP = Collections.unmodifiableMap(tempReverseAbbreviationMap);
    } else {
        // In a real ClassUtils, these would be the class's static fields.
        // ABBREVIATION_MAP = ClassUtils.abbreviationMap;
        // REVERSE_ABBREVIATION_MAP = ClassUtils.reverseAbbreviationMap;
        throw new IllegalStateException("Abbreviation maps not correctly initialized or accessible.");
    }


    // Handle array encoding, e.g., "[Ljava.lang.String;", "[I"
    int arrayDepth = 0;
    while (className.charAt(arrayDepth) == '[') {
        arrayDepth++;
        if (arrayDepth >= className.length()) { // Malformed array string
            return StringUtils.EMPTY; // Or throw an IllegalArgumentException
        }
    }

    String baseClassName = className.substring(arrayDepth);
    String componentTypeName;

    if (baseClassName.length() > 1 && baseClassName.charAt(0) == 'L' && baseClassName.endsWith(";")) {
        // Strip Object type encoding: "Ljava.lang.String;" -> "java.lang.String"
        componentTypeName = baseClassName.substring(1, baseClassName.length() - 1);
    } else if (ABBREVIATION_MAP.containsKey(baseClassName)) {
        // Primitive array type: "I" -> "int"
        componentTypeName = ABBREVIATION_MAP.get(baseClassName);
    } else {
        // Not an encoded array or a malformed one, treat as regular class name
        componentTypeName = baseClassName;
    }

    // Now process the componentTypeName to get its short name (without package)
    int lastDotIdx = componentTypeName.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
    String out = (lastDotIdx == -1) ? componentTypeName : componentTypeName.substring(lastDotIdx + 1);

    // Handle inner class separator if present in the 'short' part of the name
    // Example: "Outer$Inner" -> "Outer.Inner"
    // "Outer.Inner" is considered the short name as per typical ClassUtils interpretation
    int innerIdx = out.lastIndexOf(INNER_CLASS_SEPARATOR_CHAR); // Look for $ in the extracted 'out'
    if (innerIdx != -1) {
        // Replace all occurrences, as nested inner classes exist (e.g., Outer$Middle$Inner -> Outer.Middle.Inner)
        out = out.replace(INNER_CLASS_SEPARATOR_CHAR, PACKAGE_SEPARATOR_CHAR);
    }

    // Append array suffix, e.g., "String" + "[]" -> "String[]"
    for (int i = 0; i < arrayDepth; i++) {
        out += "[]";
    }

    return out;
}

public static String abbreviate(String str, int lower, int upper, String appendToEnd) {
        // Initial parameter checks for str
        if (str == null) {
            return null;
        }
        if (str.length() == 0) {
            return StringUtils.EMPTY;
        }

        // Normalize lower and upper bounds
        lower = Math.max(0, lower); // Ensure lower is not negative
        upper = Math.max(0, upper); // Ensure upper is not negative

        // Adjust upper to be at most the string length
        // This makes 'upper' the maximum *actual* length of the string content *before* appendToEnd.
        int effectiveUpper = Math.min(str.length(), upper);

        // If lower is greater than effectiveUpper, it implies 'lower' is the stricter limit.
        // In such a case, the abbreviation should not go past 'lower'.
        // This means the effective maximum truncation point is 'lower'.
        effectiveUpper = Math.max(effectiveUpper, lower);


        // If the string is already shorter than or equal to the desired effectiveUpper,
        // or if effectiveUpper is 0 (meaning no content requested),
        // return the original string (or empty) without appending.
        if (str.length() <= effectiveUpper) {
            return str; // No actual abbreviation needed
        }

        // Find the last space before or at the effectiveUpper limit, but starting search from 'lower'.
        // We want a word boundary. The original logic's `indexOf(str, " ", lower)` implies finding
        // the *first* space from `lower`. This is slightly different from finding the *last* space
        // *before* effectiveUpper which is often preferred for abbreviation, but we'll try to
        // adhere to the original's implicit intent of finding the first space from 'lower' that
        // *also* falls within 'effectiveUpper'.

        int spaceIndex = StringUtils.indexOf(str, " ", lower);

        // Case 1: No space found from 'lower' up to the end of the string.
        // OR the first space found is beyond our 'effectiveUpper' limit.
        if (spaceIndex == -1 || spaceIndex > effectiveUpper) {
            // Abbreviate by cutting strictly at effectiveUpper.
            return str.substring(0, effectiveUpper) + StringUtils.defaultString(appendToEnd);
        } else {
            // Case 2: A space was found between 'lower' and 'effectiveUpper' (inclusive of effectiveUpper if space is exactly there).
            // Truncate at this space.
            return str.substring(0, spaceIndex) + StringUtils.defaultString(appendToEnd);
        }
    }

public static String getShortClassName(String className) {
        if (StringUtils.isEmpty(className)) { // Use StringUtils.isEmpty for null and empty check
            return StringUtils.EMPTY;
        }

        StringBuilder arraySuffix = new StringBuilder();
        int arrayDepth = 0;
        String componentClassName = className;

        // Handle array encoding (JVM internal format like [Ljava.lang.String; or [[I)
        while (componentClassName.startsWith("[")) {
            arrayDepth++;
            componentClassName = componentClassName.substring(1);
        }

        // If it's a primitive array, map the single char to its primitive name
        if (arrayDepth > 0) {
            if (componentClassName.length() > 0) {
                switch (componentClassName.charAt(0)) {
                    case 'L': // Object type array, e.g., [Ljava.lang.String;
                        componentClassName = componentClassName.substring(1, componentClassName.length() - 1); // Strip 'L' and ';'
                        break;
                    case 'Z': componentClassName = "boolean"; break;
                    case 'B': componentClassName = "byte"; break;
                    case 'C': componentClassName = "char"; break;
                    case 'D': componentClassName = "double"; break;
                    case 'F': componentClassName = "float"; break;
                    case 'I': componentClassName = "int"; break;
                    case 'J': componentClassName = "long"; break;
                    case 'S': componentClassName = "short"; break;
                    case 'V': componentClassName = "void"; break; // void[] is technically not valid, but for completeness
                    default:
                        // Unknown primitive type, treat as part of class name
                        break;
                }
            }

            for (int i = 0; i < arrayDepth; i++) {
                arraySuffix.append("[]");
            }
        }


        int lastDotIdx = componentClassName.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
        String out = componentClassName.substring(lastDotIdx + 1);

        // Handle inner classes, replace $ with . for common display
        int innerIdx = out.indexOf(INNER_CLASS_SEPARATOR_CHAR);
        if (innerIdx != -1) {
            out = out.replace(INNER_CLASS_SEPARATOR_CHAR, PACKAGE_SEPARATOR_CHAR);
        }

        return out + arraySuffix.toString();
    }

public static String abbreviate(String str, int lower, int upper, String appendToEnd) {
        // initial parameter checks
        if (str == null) {
            return null;
        }
        if (str.length() == 0) {
            return StringUtils.EMPTY;
        }

        // Clamp lower and upper bounds
        final int strLen = str.length();

        // Ensure lower is not negative and not greater than string length
        lower = Math.max(0, lower);
        lower = Math.min(strLen, lower);

        // Ensure upper is handled correctly: -1 means no limit, otherwise clamped between 0 and strLen
        if (upper == -1) {
            upper = strLen; // No upper limit, so effectively the full string length
        } else {
            upper = Math.max(0, upper); // Ensure upper is not negative (if not -1)
            upper = Math.min(strLen, upper); // Clamp upper to string length
        }

        // Ensure upper is not less than lower after clamping
        // If upper is still less than lower, it means the effective max length is lower itself.
        upper = Math.max(lower, upper);

        // If the string is already shorter than or equal to the desired upper limit,
        // no abbreviation is needed.
        if (strLen <= upper && strLen <= lower) { // Special case: if str is very short and fits within both lower/upper
            return str;
        }
        if (strLen <= upper) { // If str fits within upper, no abbreviation needed
            return str;
        }


        // Use StringBuilder for better performance
        StringBuilder result = new StringBuilder();

        // Find the first space character starting from 'lower' up to 'upper'
        // This indexOf will look for a space from 'lower' up to the end of the string.
        // We then need to check if this space is within our 'upper' boundary.
        int firstSpaceAfterLower = StringUtils.indexOf(str, " ", lower);

        int truncationPoint;
        boolean abbreviationOccurred;

        // Case 1: No space found after 'lower', or the first space is beyond 'upper' limit.
        // In this case, we truncate strictly at 'upper'.
        if (firstSpaceAfterLower == -1 || firstSpaceAfterLower > upper) {
            truncationPoint = upper;
            abbreviationOccurred = (truncationPoint < strLen);
        }
        // Case 2: A space is found after 'lower' AND it is within or at the 'upper' limit.
        // We truncate at this space to ensure word boundaries.
        else { // firstSpaceAfterLower <= upper
            truncationPoint = firstSpaceAfterLower;
            abbreviationOccurred = (truncationPoint < strLen);
        }

        // Append the abbreviated string content
        result.append(str.substring(0, truncationPoint));

        // Append the suffix ONLY if abbreviation actually occurred
        if (abbreviationOccurred) {
            result.append(StringUtils.defaultString(appendToEnd));
        }

        return result.toString();
    }

public static void escapeJava(Writer out, String str) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("The Writer must not be null");
    }
    // If str is null, we can choose to do nothing, write "null", or throw an exception.
    // Given the sister method StringEscapeUtils.escapeJava(String str) returns null for null input,
    // and for a Writer, writing nothing for null input is a reasonable approach
    // if the goal is to prevent a NullPointerException downstream and not introduce "null" literally.
    // If the intent was to write the literal string "null", that would be different.
    // Assuming the common StringEscapeUtils behavior where null input often means no output or null result,
    // doing nothing for null str when writing is consistent and safe.
    if (str == null) {
        return; // Do nothing for null input string.
    }
    escapeJavaStyleString(out, str, false);
}

public static String abbreviate(String str, int lower, int upper, String appendToEnd) {
        if (str == null) {
            return null;
        }
        if (str.isEmpty()) {
            return StringUtils.EMPTY;
        }

        // Normalize appendToEnd to an empty string if null, for consistent length calculations
        final String effectiveAppendToEnd = StringUtils.defaultString(appendToEnd);
        final int appendToEndLength = effectiveAppendToEnd.length();

        // 1. Validate and adjust lower and upper bounds
        // 'lower' must be non-negative.
        if (lower < 0) {
            lower = 0;
        }
        // 'upper' must be non-negative (unless -1 indicating no limit).
        // If upper is 0, the result should be empty or just the suffix if it fits.
        // If upper is -1, it means no hard character limit, effectively 'str.length()'.
        if (upper == -1) {
            upper = str.length();
        } else if (upper < 0) { // If upper is negative but not -1, treat as 0 or a more robust error handling
            upper = 0; // Or throw IllegalArgumentException("Upper bound must be non-negative or -1");
        }

        // Ensure 'lower' is not greater than 'upper', and both are not greater than string length
        if (lower > str.length()) {
            lower = str.length();
        }
        if (upper > str.length()) {
            upper = str.length();
        }
        if (lower > upper) { // If lower limit is greater than the overall upper limit, adjust lower
            lower = upper;
        }


        // 2. Check if abbreviation is even necessary
        // If the string length is already within the upper bound, and 'lower' isn't forcing truncation
        // (i.e., we are not trying to trim *after* lower even if it fits in upper)
        // This condition implies we return the original string if it's short enough.
        if (str.length() <= upper && str.length() <= lower && effectiveAppendToEnd.isEmpty()) {
            return str; // No truncation needed and no suffix to add
        }
        if (str.length() <= upper && effectiveAppendToEnd.isEmpty()) { // If it fits and no suffix
            return str;
        }
        // If the string is already short enough to fit without appending the suffix, return it directly.
        // This prevents adding "..." to "Hello" if upper is 10.
        if (str.length() <= upper - appendToEndLength) {
             return str;
        }


        // 3. Determine the effective maximum length for the string content (excluding suffix)
        // This is `upper` minus the length of the suffix.
        // If `upper` is smaller than the suffix length, we can't even fit the suffix,
        // so the content length would be 0, and we may or may not return the suffix itself.
        int maxContentLength = upper - appendToEndLength;
        if (maxContentLength < 0) {
            maxContentLength = 0; // Cannot fit any content if suffix is longer than upper
        }

        // If maxContentLength is 0, and upper is sufficient for the suffix, just return the suffix.
        if (maxContentLength == 0) {
            return (upper >= appendToEndLength) ? effectiveAppendToEnd : StringUtils.EMPTY;
        }

        // If 'lower' itself is greater than or equal to maxContentLength, then 'lower' becomes the effective content limit.
        // This ensures we always try to preserve at least 'lower' characters, but not exceeding the overall 'maxContentLength'.
        int actualContentLimit = Math.min(maxContentLength, str.length());


        // 4. Find a word boundary (space) for abbreviation
        // We look for a space *after or at* the 'lower' boundary, but *not exceeding* the 'actualContentLimit'.
        int spaceIndex = -1;
        if (lower < actualContentLimit) { // Only try to find a space if there's room between lower and the content limit
            spaceIndex = StringUtils.indexOf(str, " ", lower);
        }

        // If no space is found, or if the space found is beyond our actual content limit,
        // then we truncate strictly at the character limit.
        if (spaceIndex == -1 || spaceIndex > actualContentLimit) {
            // Truncate at actualContentLimit characters
            if (actualContentLimit == str.length()) {
                // If actualContentLimit is the full length, no truncation occurs.
                // This means the full string fits (possibly along with the suffix if it was shorter than upper),
                // so no suffix should be added.
                return str; // No actual truncation needed based on upper-suffix limit.
            } else {
                return str.substring(0, actualContentLimit) + effectiveAppendToEnd;
            }
        } else {
            // Space found within limits, truncate at the space
            return str.substring(0, spaceIndex) + effectiveAppendToEnd;
        }
    }

public static int indexOfAnyBut(final CharSequence cs, final char[] searchChars) {
        if (isEmpty(cs)) {
            return INDEX_NOT_FOUND;
        }

        // Logical correction for empty searchChars:
        // If searchChars is empty, any char in cs is "not in" searchChars.
        // So, the first char of cs (at index 0) is the answer, provided cs is not empty.
        if (ArrayUtils.isEmpty(searchChars)) {
            return 0; // All characters in cs are 'not in' an empty set.
        }

        final int csLen = cs.length();
        final int searchLen = searchChars.length;

        // Iterate through each character in the main CharSequence
        for (int i = 0; i < csLen; i++) {
            final char ch = cs.charAt(i);
            boolean foundInSearchChars = false; // Flag to track if 'ch' is found in 'searchChars'

            // Iterate through each character in the searchChars array
            for (int j = 0; j < searchLen; j++) {
                if (searchChars[j] == ch) {
                    foundInSearchChars = true; // 'ch' is present in 'searchChars'
