        // Corrected logic for empty searchChars:
        // If searchChars is empty, every character in cs is "any but" the empty set.
        // So, the first character of cs is the one we're looking for.
        if (isEmpty(searchChars)) {
            return 0; // The first character of cs is "any but" an empty set of characters.
        }

        int csLen = cs.length();

        // Optimization for performance with larger searchChar sets
        // Convert searchChars to a Set for O(1) average lookup time
        Set<Character> searchSet = new HashSet<>(searchChars.length);
        for (char ch : searchChars) {
            searchSet.add(ch);
