            if (!searchSet.contains(ch)) {
                return i;
            }
        }
        return INDEX_NOT_FOUND;
    }

public static String abbreviate(String str, int minLength, int maxLength, String appendToEnd) {
        // 1. Initial parameter checks
        if (str == null) {
            return null;
        }
        if (str.isEmpty()) {
            return StringUtils.EMPTY;
        }

        // 2. Validate boundary parameters
        if (minLength < 0) {
            minLength = 0; // Treat negative minLength as 0
        }
        if (maxLength < -1) {
            maxLength = -1; // Treat invalid negative maxLength as -1 (no limit)
        }

        // 3. Normalize maxLength (if not -1)
        int effectiveMaxLength = maxLength;
        if (effectiveMaxLength == -1 || effectiveMaxLength > str.length()) {
            effectiveMaxLength = str.length();
        }

        // Ensure minLength doesn't exceed effectiveMaxLength
        if (minLength > effectiveMaxLength) {
            minLength = effectiveMaxLength;
        }

        // If the string is already shorter than or equal to the desired max length
        // and doesn't need a word break, return it as is.
        // This handles cases where no abbreviation is needed.
        if (str.length() <= effectiveMaxLength) {
             // Check if truncation occurred due to minLength for word break
            int firstSpaceIndex = StringUtils.indexOf(str, " ", minLength);
            if (firstSpaceIndex == -1 || firstSpaceIndex >= str.length()) { // No space found after minLength, or space is beyond string length
                return str; // No truncation needed
            }
        }


        // Find the first space after minLength, but not beyond effectiveMaxLength
        int abbreviationPoint = StringUtils.indexOf(str, " ", minLength);

        // Scenario A: No space found from minLength onwards, or space is beyond maxLength
        if (abbreviationPoint == -1 || abbreviationPoint > effectiveMaxLength) {
            // Truncate hard at effectiveMaxLength.
            String result = str.substring(0, effectiveMaxLength);
            // Append suffix ONLY if actual truncation occurred
            if (effectiveMaxLength < str.length()) {
                result += StringUtils.defaultString(appendToEnd);
            }
            return result;
        }
        // Scenario B: Space found within effectiveMaxLength
        else {
            // Truncate at the found space.
            String result = str.substring(0, abbreviationPoint);
            // Append suffix ONLY if actual truncation occurred
            if (abbreviationPoint < str.length()) {
                result += StringUtils.defaultString(appendToEnd);
            }
            return result;
        }
    }

