public static String abbreviate(String str, int lower, int upper, String appendToEnd) {
        // 1. Initial parameter checks and edge cases
        if (str == null) {
            return null;
        }
        if (str.length() == 0) {
            return StringUtils.EMPTY;
        }

        // Ensure appendToEnd is not null
        final String effectiveAppendToEnd = StringUtils.defaultString(appendToEnd);
        final int appendToEndLength = effectiveAppendToEnd.length();

        // 2. Validate and adjust lower and upper bounds
        // lower must be non-negative
        if (lower < 0) {
            lower = 0;
        }
        // upper must be non-negative or -1
        if (upper < -1) {
            upper = 0; // Treat negative upper (other than -1) as 0
        }

        // If upper is -1, it means no explicit upper limit from this parameter.
        // It should be treated as the string's full length for comparison.
        // Also, upper cannot be greater than string length initially.
        int effectiveUpper = (upper == -1 || upper > str.length()) ? str.length() : upper;

        // The effective upper limit should not be less than lower.
        // This ensures we at least meet the minimum length requirement if possible.
        if (effectiveUpper < lower) {
            effectiveUpper = lower;
        }

        // If the string is already short enough (or shorter than lower), no abbreviation is needed.
        // Or if effectiveUpper is the full string length and it's also >= lower.
        if (str.length() <= effectiveUpper && str.length() >= lower) {
            return str;
        }

        // If after all adjustments, the string's length is already within the desired range, no action needed.
        if (str.length() <= effectiveUpper) {
            return str;
        }

        // 3. Determine the abbreviation point

        // Calculate the maximum actual length for the string content, accounting for appendToEnd.
        // We need to reserve space for effectiveAppendToEnd if we are going to truncate.
        int targetLengthWithoutSuffix = effectiveUpper - appendToEndLength;

        // Ensure we don't try to truncate to a negative length
        if (targetLengthWithoutSuffix < 0) {
            targetLengthWithoutSuffix = 0;
        }

        // We must ensure the truncated part (without suffix) is at least 'lower'
        if (targetLengthWithoutSuffix < lower) {
            targetLengthWithoutSuffix = lower;
        }

        // If targetLengthWithoutSuffix is 0 and lower is 0,
        // and appendToEndLength is 0, it means we want an empty string.
        // But if appendToEndLength > 0 and effectiveUpper is small,
        // targetLengthWithoutSuffix could be 0, implying "..." or similar.

        // If after all calculations, targetLengthWithoutSuffix is 0 but effectiveUpper is > 0
        // (meaning effectiveAppendToEnd will take up all space, e.g., upper=3, appendToEnd="..."),
        // then we might just return the effectiveAppendToEnd directly if lower allows.
        if (targetLengthWithoutSuffix == 0 && effectiveUpper > 0 && effectiveUpper <= appendToEndLength && lower == 0) {
             return effectiveAppendToEnd.substring(0, Math.min(effectiveUpper, effectiveAppendToEnd.length()));
        }


        // Find the last space before or at targetLengthWithoutSuffix
        int lastSpaceIndex = StringUtils.lastIndexOf(str, " ", targetLengthWithoutSuffix);

        StringBuffer result = new StringBuffer();

        if (lastSpaceIndex == -1 || lastSpaceIndex < lower) {
            // No space found before targetLengthWithoutSuffix (or before 'lower'),
            // or the space found is before the minimum 'lower' boundary.
            // Truncate hard at targetLengthWithoutSuffix.
            result.append(str.substring(0, Math.min(str.length(), targetLengthWithoutSuffix)));
        } else {
            // Space found within the range, truncate at the space.
            result.append(str.substring(0, lastSpaceIndex));
        }

        // Append the suffix only if actual truncation has occurred
        // (i.e., the resulting string length + suffix length is less than original string length)
        // Or if the string was longer than effectiveUpper
        if (result.length() < str.length()) { // This ensures original string was longer
            if (effectiveUpper < str.length()) { // This ensures actual truncation happened due to effectiveUpper
                 result.append(effectiveAppendToEnd);
            }
        }

        // Final adjustment for the very strict upper bound.
        // If, after appending the suffix, the result is still too long,
        // it means appendToEnd itself made it too long, or previous
        // calculations were slightly off due to edge cases.
        // This is a safety net.
        if (result.length() > effectiveUpper) {
            // Trim the result to exactly effectiveUpper.
            // This might cut off part of the appendToEnd string if effectiveUpper is very small.
            return result.substring(0, effectiveUpper).toString();
        }

        return result.toString();
    }

