public static String getPackageName(String className) {
        if (className == null || className.isEmpty()) {
            return StringUtils.EMPTY;
        }

        // Handle array and primitive type encodings (e.g., "[Ljava.lang.String;", "I")
        // The JVM uses a specific format for array types:
        // [Z - boolean[]
        // [B - byte[]
        // [C - char[]
        // [S - short[]
        // [I - int[]
        // [J - long[]
        // [F - float[]
        // [D - double[]
        // [L<ClassName>; - Object[]
        // We need to strip these prefixes to get to the actual class name.
        int dimension = 0;
        while (className.charAt(dimension) == '[') {
            dimension++;
            if (dimension >= className.length()) { // Malformed array name, e.g., only "[[["
                return StringUtils.EMPTY;
            }
        }

        if (dimension > 0) { // It was an array
            if (className.charAt(dimension) == 'L' && className.endsWith(";")) {
                // Object array type: [Ljava.lang.String; -> java.lang.String
                className = className.substring(dimension + 1, className.length() - 1);
            } else if (dimension == 1 && (className.charAt(dimension) == 'Z' || className.charAt(dimension) == 'B' ||
                                           className.charAt(dimension) == 'C' || className.charAt(dimension) == 'S' ||
                                           className.charAt(dimension) == 'I' || className.charAt(dimension) == 'J' ||
                                           className.charAt(dimension) == 'F' || className.charAt(dimension) == 'D')) {
                // Primitive array type: [I -> int (no package name for primitives)
                return StringUtils.EMPTY;
            } else {
                // Malformed array, or primitive type without 'L' (e.g., "I" directly),
                // which has no package name.
                // For "int" or "double" (not encoded), this part won't be reached.
                // If input is "I" or "J", it correctly falls through to return empty later.
                // However, if it's "[I", it implies the class name for int.
                // Primitives don't have package names.
                return StringUtils.EMPTY;
            }
        }
        // After stripping, if it was a primitive type directly (e.g., "int", "boolean"),
        // or a malformed array encoding that resolved to a primitive, it won't have a '.'
        // and will correctly return empty later.

        int i = className.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
        if (i == -1) {
            // No package separator found, likely a class in the default package or a primitive type
            return StringUtils.EMPTY;
        }
        return className.substring(0, i);
    }

