public static int indexOfAnyBut(CharSequence cs, char[] searchChars) {
        // Handle null or empty CharSequence: No characters to search, return not found.
        if (StringUtils.isEmpty(cs)) {
            return INDEX_NOT_FOUND;
        }

        // Handle null searchChars array: No characters to "but" against.
        // As per the original method's logic and the "indexOfAnyBut" semantic,
        // if searchChars is null, it cannot contain any character, so any char in cs
        // would be "not in" null. This case is implicitly handled correctly by returning INDEX_NOT_FOUND
        // because the loop for 'j' would not run, and no character would be found.
        // However, an explicit check for searchChars == null is clearer and handles it
        // before considering the empty searchChars case.
        if (searchChars == null) {
            return INDEX_NOT_FOUND;
        }

        // Handle empty searchChars array: If there are no characters to "but" against,
        // then *any* character in cs will be "not in" the empty set.
        // Therefore, if cs is not empty, the first character's index (0) is the answer.
        // This is a correction to the original logic which returned INDEX_NOT_FOUND.
        if (searchChars.length == 0) {
            return StringUtils.isEmpty(cs) ? INDEX_NOT_FOUND : 0;
        }

        int csLen = cs.length();
        int searchLen = searchChars.length;

        outer:
        for (int i = 0; i < csLen; i++) {
            char ch = cs.charAt(i);
            for (int j = 0; j < searchLen; j++) {
                if (searchChars[j] == ch) {
                    // Character 'ch' is found in 'searchChars', so it does NOT satisfy the "AnyBut" condition.
                    // Continue to the next character in 'cs'.
                    continue outer;
                }
            }
            // If the inner loop completes, it means 'ch' was NOT found in 'searchChars'.
            // This character satisfies the "AnyBut" condition, so return its index.
            return i;
        }

        // If the outer loop completes, it means all characters in 'cs' were found in 'searchChars'.
        return INDEX_NOT_FOUND;
    }

