public Fraction reduce() {
    // Defensively check for zero denominator, although getFraction factory methods
    // should ideally prevent this state. A fraction with a zero denominator is
    // mathematically undefined and attempting to reduce it would lead to division by zero.
    if (denominator == 0) {
        throw new ArithmeticException("Cannot reduce a fraction with a zero denominator.");
    }

    // Calculate the greatest common divisor of the absolute value of the numerator
    // and the denominator. We use Math.abs(numerator) for GCD calculation
    // to ensure GCD is positive, simplifying subsequent division.
    int gcd = greatestCommonDivisor(Math.abs(numerator), denominator);

    // If the greatest common divisor is 1, the fraction is already in its
    // simplest form, so we can return the current instance directly
    // to avoid creating a new identical object (immutability).
    if (gcd == 1) {
        return this;
    }

    // Divide both the numerator and the denominator by their greatest common divisor
    // to reduce the fraction to its simplest form.
    // The sign of the numerator is preserved correctly here because we used the
    // original 'numerator' for the division, not its absolute value.
    // The 'getFraction' factory method is used to construct the new Fraction
    // instance, which is expected to handle any necessary sign normalization
    // (e.g., ensuring a positive denominator if the initial division resulted
    // in a negative denominator and numerator, e.g., -2/-4 becoming 1/2).
    return Fraction.getFraction(numerator / gcd, denominator / gcd);
}

