public Fraction reduce() {
    // A fraction with a numerator of 0 always reduces to 0/1.
    // This is a minor optimization to avoid GCD calculation for this common case.
    if (numerator == 0) {
        return Fraction.ZERO; // Assuming Fraction.ZERO is defined as new Fraction(0, 1)
    }

    // Calculate the greatest common divisor of the absolute value of the numerator
    // and the denominator. We use Math.abs for the numerator to ensure GCD calculation
    // works correctly with magnitudes, as GCD is typically for non-negative integers.
    // The denominator is already guaranteed to be non-zero and typically positive
    // by the Fraction class's construction rules.
    int commonDivisor = greatestCommonDivisor(Math.abs(numerator), denominator);

    // If the greatest common divisor is 1, the fraction is already in its simplest form.
    // In this case, return the current instance to avoid creating a new identical object,
    // adhering to immutability and potential object pooling/optimization.
    if (commonDivisor == 1) {
        return this;
    }

    // Otherwise, reduce the fraction by dividing both the numerator and denominator
    // by their greatest common divisor.
    // The getFraction factory method is used to ensure proper canonicalization
    // (e.g., handling negative signs correctly and ensuring a positive denominator).
    return Fraction.getFraction(numerator / commonDivisor, denominator / commonDivisor);
}

