    // The part after '_' (index 3) is either a country code or variant code.
    // If it's a country code, it must be two uppercase letters.
    if (len < 5) {
        throw new IllegalArgumentException("Invalid locale format: " + str + ". Expected 2-letter country code or variant after '_'.");
    }

    final char ch3 = str.charAt(3);
    final char ch4 = str.charAt(4);

    // Assume it's a country code if the next two chars are uppercase
    if (Character.isUpperCase(ch3) && Character.isUpperCase(ch4)) {
        final String country = str.substring(3, 5);

        // Handle Language and Country only (e.g., "en_US")
        if (len == 5) {
            return new Locale(language, country);
        }

        // Handle Language, Country, and Variant (e.g., "en_US_VAR")
        if (len < 7) { // "en_US_" or "en_US_V" (length 6) is not a full variant
            throw new IllegalArgumentException("Invalid locale format: " + str + ". Expected '_' separator or variant after country code.");
        }
        if (str.charAt(5) != '_') {
            throw new IllegalArgumentException("Invalid locale format: " + str + ". Expected '_' separator at index 5 for variant.");
        }
        final String variant = str.substring(6);
        return new Locale(language, country, variant);
    } else {
        // If the 3rd and 4th chars are not uppercase, assume it's a variant directly after 'll_'
        // This handles cases like "en_v" (length 4) or "en_var" (length 6)
        // The original code would throw an exception for "en_v" or "en_var" if they didn't fit country rules.
        // We can create a locale with language and variant directly.
        if (len < 4) { // "ll_..." min 4 if variant is 1 char
             throw new IllegalArgumentException("Invalid locale format: " + str + ". Missing variant after '_'.");
