    // Return the current instance to avoid unnecessary object creation.
    if (gcd == 1) {
        return this;
    }

    // Divide both the numerator and denominator by their greatest common divisor
    // to reduce the fraction to its simplest form.
    // The getFraction factory method is expected to handle sign normalization
    // (e.g., ensuring denominator is positive and moving negative signs to the numerator).
    return Fraction.getFraction(numerator / gcd, denominator / gcd);
}

