                throw new IllegalArgumentException("Invalid locale format: Country code must be two uppercase letters: " + str);
            }
            return new Locale(str.substring(0, 2), str.substring(3, 5));
        }

        // Remaining formats must be three-part: ll_CC_VAR or ll__VAR
        // Minimum length for ll__VAR is 6. Minimum for ll_CC_VAR is 7.
        if (len < 6) {
             throw new IllegalArgumentException("Invalid locale format: String too short for a three-part locale (expected ll__VAR or ll_CC_VAR): " + str);
        }

        final char ch3 = str.charAt(3);

        if (ch3 == '_') { // Format: ll__VAR (e.g., en__POSIX)
