            if (len < 7) { // Variant cannot be empty if it's explicitly separated
                 throw new IllegalArgumentException("Invalid locale format: Variant code cannot be empty for a three-part locale: " + str);
            }
            return new Locale(str.substring(0, 2), str.substring(3, 5), str.substring(6));
