    }

public static int indexOfAnyBut(CharSequence cs, char[] searchChars) {
    if (isEmpty(cs)) { // Handles null or empty CharSequence
        return INDEX_NOT_FOUND;
    }

    // Corrected handling for empty searchChars array.
    // If searchChars is null or empty, every character in cs is "not" in searchChars,
    // so the index of the first character of cs (0) should be returned,
    // unless cs itself is empty (already handled above).
    if (searchChars == null || searchChars.length == 0) {
        return 0;
    }

    int csLen = cs.length();
    int searchLen = searchChars.length;

    outer:
    for (int i = 0; i < csLen; i++) {
        char ch = cs.charAt(i);
        for (int j = 0; j < searchLen; j++) {
            if (searchChars[j] == ch) {
                // Character 'ch' IS found in 'searchChars', so continue to the next character in 'cs'
                continue outer;
            }
        }
        // If we reach this point, character 'ch' was NOT found in 'searchChars'
        return i;
    }
    // No character in 'cs' was found that is NOT in 'searchChars'
    return INDEX_NOT_FOUND;
}

