        // It could be:
        // 1. xx_YY (country)
        // 2. xx_YY_ZZZ (country + variant)
        // 3. xx_VAR (variant) - when VAR is not 2 uppercase chars
        // 4. xx__VAR (empty country + variant)

        // Try to parse country code first if available.
        // A country code is always 2 uppercase letters.
        if (len >= 5 && str.charAt(3) != '_' && Character.isUpperCase(str.charAt(3)) && Character.isUpperCase(str.charAt(4))) {
            country = str.substring(3, 5);

            // If we have "xx_YY"
            if (len == 5) {
                return new Locale(language, country);
            }

            // If we have "xx_YY_" (length 6), then the next char must start a variant.
            if (str.charAt(5) != '_') {
                throw new IllegalArgumentException("Invalid locale format: " + str);
            }

            // If we have "xx_YY_ZZZ..." (length >= 7)
            variant = str.substring(6);
            return new Locale(language, country, variant);

        } else if (len > 3) { // This handles "xx_VAR" or "xx__VAR"
            // If the char at index 3 is '_', it means we have "xx__VAR" (empty country).
            if (str.charAt(3) == '_') {
