                variant = str.substring(3);
                return new Locale(language, "", variant); // Language, empty country, variant
            }
        }

        // If we reach here, it means we had "xx_" and nothing after it,
        // or a format that doesn't fit the above patterns.
        throw new IllegalArgumentException("Invalid locale format: " + str);
    }

