public static Locale toLocale(final String str) {
        if (str == null) {
            return null;
        }

        final int len = str.length();

        // Handle empty string
        if (len == 0) {
            throw new IllegalArgumentException("Invalid locale format: empty string");
        }

        // Language code (e.g., "en")
        if (len < 2) {
            throw new IllegalArgumentException("Invalid locale format: " + str + ". Language code must be at least 2 characters.");
        }

        final char ch0 = str.charAt(0);
        final char ch1 = str.charAt(1);

        if (!isTwoLowercaseAsciiLetters(ch0, ch1)) {
            throw new IllegalArgumentException("Invalid locale format: " + str + ". Language code '" + str.substring(0, 2) + "' must be two lowercase ASCII letters.");
        }

        if (len == 2) {
            return new Locale(str); // e.g., "en"
        }

        // Expect separator for country or variant
        if (str.charAt(2) != '_') {
            throw new IllegalArgumentException("Invalid locale format: " + str + ". Expected '_' separator at index 2.");
        }

        // Case: ll__VARIANT (e.g., "en__POSIX") or ll_CC (e.g., "en_US")
        if (len == 3) {
            // Cannot be just "ll_" - needs country or variant
            throw new IllegalArgumentException("Invalid locale format: " + str + ". String too short after language and separator.");
        }

        final char ch3 = str.charAt(3);

        if (ch3 == '_') { // Format: ll__VARIANT
            if (len == 4) { // e.g., "en__" - no variant provided
                 throw new IllegalArgumentException("Invalid locale format: " + str + ". Variant code missing after 'll__'.");
            }
            // Variant can be anything. No specific char validation needed here per typical Locale API.
            return new Locale(str.substring(0, 2), "", str.substring(4)); // e.g., "en__POSIX"
        } else { // Format: ll_CC or ll_CC_VARIANT
            if (len < 5) {
                // Must be at least 5 for "ll_CC"
                throw new IllegalArgumentException("Invalid locale format: " + str + ". Country code must be two uppercase ASCII letters.");
            }
            final char ch4 = str.charAt(4);

            if (!isTwoUppercaseAsciiLetters(ch3, ch4)) {
                throw new IllegalArgumentException("Invalid locale format: " + str + ". Country code '" + str.substring(3, 5) + "' must be two uppercase ASCII letters.");
            }

            if (len == 5) {
                return new Locale(str.substring(0, 2), str.substring(3, 5)); // e.g., "en_US"
            }

            // Expect separator for variant
            if (str.charAt(5) != '_') {
                throw new IllegalArgumentException("Invalid locale format: " + str + ". Expected '_' separator at index 5 for variant.");
            }

            if (len == 6) { // e.g., "en_US_" - empty variant is valid
                return new Locale(str.substring(0, 2), str.substring(3, 5), "");
            }

            // Format: ll_CC_VARIANT
            // Variant can be anything. No specific char validation needed here per typical Locale API.
            return new Locale(str.substring(0, 2), str.substring(3, 5), str.substring(6)); // e.g., "en_US_POSIX"
        }
    }

