public StrBuilder appendFixedWidthPadLeft(Object obj, int width, char padChar) {
    if (width <= 0) {
        // As per the existing design, a width of 0 or less means no characters are appended.
        // This is a reasonable design choice for fixed-width operations.
        return this;
    }

    // Ensure capacity for the new fixed width
    ensureCapacity(size + width);

    // Get the string representation, handling null obj and potential null from getNullText()
    String str;
    if (obj == null) {
        str = getNullText();
        // Defensive check: If getNullText() returns null, treat it as an empty string to avoid NPE.
        // This makes the method more robust against potentially misconfigured or buggy getNullText().
        if (str == null) {
            str = "";
        }
    } else {
        str = obj.toString();
        // Defensive check: If obj.toString() returns null, treat it as an empty string to avoid NPE.
        if (str == null) {
            str = "";
        }
    }

    int strLen = str.length();

    if (strLen >= width) {
        // If string is longer or equal to width, append the rightmost 'width' characters (left-truncation)
        str.getChars(strLen - width, strLen, buffer, size);
    } else {
        // If string is shorter than width, pad on the left
        int padLen = width - strLen;
        // Append padding characters
        for (int i = 0; i < padLen; i++) {
            buffer[size + i] = padChar;
        }
        // Append the actual string after padding
        str.getChars(0, strLen, buffer, size + padLen);
    }

    // Update the size of the StrBuilder
    size += width;

    return this;
}

