public static int indexOfAnyBut(CharSequence cs, char[] searchChars) {
        if (isEmpty(cs)) {
            return INDEX_NOT_FOUND;
        }

        // Corrected logic: If searchChars is null or empty, then any character
        // in a non-empty cs is "not in" searchChars. Thus, the first character
        // of cs will satisfy the condition.
        if (ArrayUtils.isEmpty(searchChars)) {
            return 0; // The first character of cs is not in the empty searchChars set.
        }

        int csLen = cs.length();
        int searchLen = searchChars.length;

        outer:
        for (int i = 0; i < csLen; i++) {
            char ch = cs.charAt(i);
            for (int j = 0; j < searchLen; j++) {
                if (searchChars[j] == ch) {
                    // Character 'ch' IS in searchChars, so continue to the next character in cs
                    continue outer;
                }
            }
            // If the inner loop completes, it means 'ch' was NOT found in searchChars
            return i;
        }

        // If the outer loop completes, it means all characters in cs were found in searchChars
        return INDEX_NOT_FOUND;
    }

