public static int indexOfAnyBut(final CharSequence str, final CharSequence searchChars) {
        if (isEmpty(str) || isEmpty(searchChars)) {
            return INDEX_NOT_FOUND;
        }

        // Optimize searchChars lookup by converting it to a Set
        // This makes character lookups O(1) on average.
        final Set<Character> searchSet = new HashSet<>(searchChars.length());
        for (int i = 0; i < searchChars.length(); i++) {
            searchSet.add(searchChars.charAt(i));
        }

        final int strLen = str.length();
        for (int i = 0; i < strLen; i++) {
            final char ch = str.charAt(i);
            if (!searchSet.contains(ch)) { // O(1) average time complexity for lookup
                return i;
            }
        }
        return INDEX_NOT_FOUND;
    }

