    if (this.runningState == STATE_STOPPED) {
        // Idempotent: allow calling stop() on an already stopped stopwatch without error.
        return;
    }

    // Must be STATE_RUNNING or STATE_SUSPENDED at this point.
    stopTime = System.currentTimeMillis();
    this.runningState = STATE_STOPPED;
