public static int indexOfAnyBut(String str, String searchChars) {
    if (isEmpty(str)) {
        return INDEX_NOT_FOUND;
    }
    // Handle null searchChars gracefully as in original, returning INDEX_NOT_FOUND if no characters to compare against.
    // If searchChars is null, no character in str can be "but" (not in) null, so INDEX_NOT_FOUND is correct.
    if (searchChars == null) {
        return INDEX_NOT_FOUND;
    }

    // Logical Correction: If searchChars is empty, then every character in str is "any but" the empty set.
    // Therefore, the first character of str is the answer, if str is not empty.
    if (searchChars.isEmpty()) {
        return str.isEmpty() ? INDEX_NOT_FOUND : 0;
    }

    int strLen = str.length();
    for (int i = 0; i < strLen; i++) {
        char ch = str.charAt(i);
        if (searchChars.indexOf(ch) < 0) { // If character 'ch' is NOT found in 'searchChars'
            return i;
        }
    }
    return INDEX_NOT_FOUND;
}

public static Number createNumber(String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (StringUtils.isBlank(str)) { // Assuming StringUtils.isBlank is available and works as expected
            throw new NumberFormatException("A blank string is not a valid number");
        }

        // Improved check for non-standard formats often caught by BigDecimal's leniency
        // and platform-specific issues mentioned in the original comment.
        // It's better to throw an exception for clearly malformed input.
        if (str.startsWith("--")) {
            throw new NumberFormatException(str + " is not a valid number (double dash prefix).");
        }

        if (str.startsWith("0x") || str.startsWith("-0x")) {
            return createInteger(str); // Delegate to Integer/BigInteger for hex
        }

        char lastChar = str.charAt(str.length() - 1);
        String mant; // Mantissa (integer part before decimal)
        String dec;  // Decimal part
        String exp;  // Exponent part

        // Robustly find the first occurrence of 'e' or 'E'
        int eIndex = str.indexOf('e');
        int EIndex = str.indexOf('E');
        int expPos = -1;
        if (eIndex != -1) {
            expPos = eIndex;
        }
        if (EIndex != -1) {
            if (expPos == -1 || EIndex < expPos) {
                expPos = EIndex;
            }
        }

        int decPos = str.indexOf('.');

        // Validate structure: exponent cannot appear before decimal point
        if (decPos > -1 && expPos > -1 && expPos < decPos) {
            throw new NumberFormatException(str + " is not a valid number (exponent before decimal).");
        }

        // Extract mantissa, decimal, and exponent parts
        if (decPos > -1) { // Has a decimal point
            if (expPos > -1) { // Has both decimal and exponent
                dec = str.substring(decPos + 1, expPos);
                mant = str.substring(0, decPos);
            } else { // Has decimal, no exponent
                dec = str.substring(decPos + 1);
                mant = str.substring(0, decPos);
            }
        } else { // No decimal point
            if (expPos > -1) { // Has exponent, no decimal
                mant = str.substring(0, expPos);
            } else { // No decimal, no exponent
                mant = str;
            }
            dec = null; // Mark decimal part as non-existent
        }

        // Check for multiple decimal points
        if (decPos != -1 && str.indexOf('.', decPos + 1) != -1) {
            throw new NumberFormatException(str + " is not a valid number (multiple decimal points).");
        }

        // Check for multiple exponent characters (e.g., 1e2E3) - this covers an earlier flaw
        if ((eIndex != -1 && str.indexOf('e', eIndex + 1) != -1) ||
            (EIndex != -1 && str.indexOf('E', EIndex + 1) != -1)) {
            throw new NumberFormatException(str + " is not a valid number (multiple exponent characters).");
        }


        // Handle numbers with type suffixes (l, L, f, F, d, D)
        if (!Character.isDigit(lastChar)) {
            // Extract exponent for `isAllZeros` check if applicable, excluding suffix
            if (expPos > -1 && expPos < str.length() - 1) { // Ensure exp is not just the suffix
                exp = str.substring(expPos + 1, str.length() - 1);
            } else {
                exp = null;
            }

            String numeric = str.substring(0, str.length() - 1); // String without the type suffix
            boolean allZeros = isAllZeros(mant) && isAllZeros(dec) && isAllZeros(exp); // Check all parts

            switch (lastChar) {
                case 'l':
                case 'L':
                    // A long cannot have a decimal or exponent
                    if (dec != null || exp != null) {
                        throw new NumberFormatException(str + " is not a valid Long number (contains decimal or exponent).");
                    }
                    // Use createLong which should handle sign and digits correctly.
                    try {
                        return createLong(numeric);
                    } catch (NumberFormatException nfe) {
                        // If too big for a long, try BigInteger.
                        // If it fails BigInteger, then it's truly not an integer.
                        try {
                            return createBigInteger(numeric);
                        } catch (NumberFormatException innerNFE) {
                            throw new NumberFormatException(str + " is not a valid Long or BigInteger number: " + innerNFE.getMessage());
                        }
                    }
                case 'f':
                case 'F':
                    try {
                        Float f = createFloat(numeric);
                        // If it's too big for a float or the float value = 0.0 and the string
                        // has non-zeros in it (indicating precision loss), try larger types.
                        if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // ignore the bad number for float, fall through to double/BigDecimal
                    }
                    // Fall through to try Double and then BigDecimal

                case 'd':
                case 'D':
                    try {
                        Double d = createDouble(numeric);
                        // Same precision check for double
                        if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // ignore the bad number for double, fall through to BigDecimal
                    }
                    try {
                        return createBigDecimal(numeric);
                    } catch (NumberFormatException e) {
                        // If BigDecimal also fails, then it's truly not a number.
                        throw new NumberFormatException(str + " is not a valid floating-point number: " + e.getMessage());
                    }

                default:
                    throw new NumberFormatException(str + " is not a valid number (unrecognized type suffix '" + lastChar + "').");
            }
        } else { // User doesn't have a preference on the return type (last char is a digit)
            // Extract exponent for `isAllZeros` check
            if (expPos > -1) { // expPos cannot be at the end if the last char is a digit
                exp = str.substring(expPos + 1); // Exp part goes to the end of string
            } else {
                exp = null;
            }

            if (dec == null && exp == null) {
                // Must be an int, long, or BigInteger
                try {
                    return createInteger(str);
                } catch (NumberFormatException nfe) {
                    // Try a bigger integer type
                }
                try {
                    return createLong(str);
                } catch (NumberFormatException nfe) {
                    // Try the biggest integer type
                }
                try {
                    return createBigInteger(str);
                } catch (NumberFormatException nfe) {
                    throw new NumberFormatException(str + " is not a valid integer number: " + nfe.getMessage());
                }
            } else {
                // Must be a float, double, or BigDecimal
                boolean allZeros = isAllZeros(mant) && isAllZeros(dec) && isAllZeros(exp);
                try {
                    Float f = createFloat(str);
                    if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // Try a bigger floating-point type
                }
                try {
                    Double d = createDouble(str);
                    if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // Try the biggest floating-point type
                }
                try {
                    return createBigDecimal(str);
                } catch (NumberFormatException nfe) {
                    throw new NumberFormatException(str + " is not a valid floating-point number: " + nfe.getMessage());
                }
            }
        }
