public void stop() {
    // This condition correctly ensures that stop() can only be called
    // when the stopwatch is actively timing (running or suspended).
    // If it's unstarted, already stopped, or split, attempting to stop it
    // is an invalid operation sequence.
    if (this.runningState != STATE_RUNNING && this.runningState != STATE_SUSPENDED) {
        throw new IllegalStateException("Stopwatch is not running or suspended. Cannot stop.");
    }
    stopTime = System.currentTimeMillis();
    this.runningState = STATE_STOPPED;
}

