                    if (!f.isInfinite() && !(f.floatValue() == 0.0F && !originalIsAllZeros(numericPart))) {
                        return f;
                    }
                    // If float isn't precise enough, fall through to double/BigDecimal.
                    // This is the original behavior, explicitly maintained for the fall-through.
                } catch (NumberFormatException nfe) {
                    // Ignore, attempt double/BigDecimal
                }
                // Fall-through to 'd'/'D' case to try double, then BigDecimal
            case 'd':
            case 'D':
                explicitTypeHint = true;
                numericPart = str.substring(0, str.length() - 1);
                try {
                    Double d = createDouble(numericPart);
                    // Check for precision loss or infinity
                    boolean originalIsAllZeros = isAllZeros(numericPart);
                    if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !originalIsAllZeros(numericPart))) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // Ignore, attempt BigDecimal
                }
                // If double isn't precise enough, or it was 'f'/'F' and float/double failed, try BigDecimal
                try {
                    return createBigDecimal(numericPart);
                } catch (NumberFormatException e) {
                    throw new NumberFormatException("String '" + str + "' is not a valid Float, Double, or BigDecimal.");
                }

            default:
                // No explicit type suffix, attempt to infer type
                // Pattern for detecting decimal point or exponent in the main part of the string
                Pattern floatingPointPattern = Pattern.compile(".*[Ee.].*");
                Matcher matcher = floatingPointPattern.matcher(str);

                if (matcher.matches()) {
                    // Looks like a floating-point number (contains '.', 'e', or 'E')
                    boolean originalIsAllZeros = isAllZeros(str); // Check for the whole string

                    try {
                        Float f = createFloat(str);
                        if (!f.isInfinite() && !(f.floatValue() == 0.0F && !originalIsAllZeros)) {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // Ignore, try double
                    }

                    try {
                        Double d = createDouble(str);
                        if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !originalIsAllZeros)) {
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // Ignore, try BigDecimal
                    }

                    // If float/double failed or was imprecise, fall back to BigDecimal
                    try {
                        return createBigDecimal(str);
                    } catch (NumberFormatException e) {
                        throw new NumberFormatException("String '" + str + "' is not a valid Float, Double, or BigDecimal.");
                    }
                } else {
                    // Looks like an integer (no '.', 'e', or 'E')
                    try {
                        return createInteger(str);
                    } catch (NumberFormatException nfe) {
                        // Ignore, try long
                    }

                    try {
                        return createLong(str);
                    } catch (NumberFormatException nfe) {
                        // Ignore, try BigInteger
                    }

                    try {
                        return createBigInteger(str);
                    } catch (NumberFormatException e) {
                        throw new NumberFormatException("String '" + str + "' is not a valid Integer, Long, or BigInteger.");
                    }
                }
        }
    }

public static Number createNumber(String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        // Corrected: Use isBlank for initial check and subsequent checks on numeric parts
        if (isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number.");
        }

        // Corrected: Return null for "--" for backward compatibility if intended,
        // but often an exception is preferred for invalid input.
        // Keeping original behavior for consistency with original intent.
        if (str.startsWith("--")) {
            return null;
        }

        // Handle hexadecimal numbers
        if (str.startsWith("0x") || str.startsWith("-0x") || str.startsWith("0X") || str.startsWith("-0X")) {
            // Validate hex digits: createInteger/Long will throw if invalid.
            String hexPart = str.startsWith("-") ? str.substring(3) : str.substring(2);
            if (!isHexDigits(hexPart)) { // New validation for hex content
                throw new NumberFormatException("Invalid hexadecimal digits in string: " + str);
            }

            int hexDigits = str.length();
            if (str.startsWith("0x") || str.startsWith("0X")) {
                hexDigits -= 2;
            } else { // "-0x" or "-0X"
                hexDigits -= 3;
            }

            if (hexDigits > 8) { // A 32-bit int can hold 8 hex digits (0-F)
                try {
                    return createLong(str);
                } catch (NumberFormatException nfe) {
                    // Fall through to BigInteger if Long fails
                }
                return createBigInteger(str);
            }
            try {
                return createInteger(str);
            } catch (NumberFormatException nfe) {
                // Fall through to Long if Integer fails (e.g., too large for int but not too many digits)
            }
            return createLong(str); // Try as long if int fails
        }

        char lastChar = str.charAt(str.length() - 1);
        String mant;
        String dec;
        String exp;

        int decPos = str.indexOf('.');
        // Corrected: Properly find the exponent position
        int expPos = Math.max(str.indexOf('e'), str.indexOf('E'));

        // Check for multiple decimal points or exponent symbols early
        if (decPos != -1 && str.indexOf('.', decPos + 1) != -1) {
            throw new NumberFormatException("Invalid number format (multiple decimal points): " + str);
        }
        if (expPos != -1 && (str.indexOf('e', expPos + 1) != -1 || str.indexOf('E', expPos + 1) != -1)) {
            throw new NumberFormatException("Invalid number format (multiple exponent symbols): " + str);
        }


        if (decPos > -1) { // Contains a decimal point
            if (expPos > -1) { // Contains both decimal and exponent
                if (expPos < decPos) {
                    throw new NumberFormatException(str + " is not a valid number. Exponent before decimal.");
                }
                dec = str.substring(decPos + 1, expPos);
                // Corrected: mantissa goes up to decPos
                mant = str.substring(0, decPos);
            } else { // Contains only decimal
                dec = str.substring(decPos + 1);
                mant = str.substring(0, decPos);
            }
        } else { // No decimal point
            if (expPos > -1) { // Contains only exponent
                mant = str.substring(0, expPos);
                dec = null; // No decimal part
            } else { // Neither decimal nor exponent
                mant = str;
                dec = null;
            }
        }

        // Validate mantissa and decimal parts for non-numeric content
        // This is a simplification; full validation might be more complex
        if (!isDigits(mant) && !mant.startsWith("-")) { // Allow leading minus
            throw new NumberFormatException("Invalid mantissa in number: " + str);
        }
        if (dec != null && !isDigits(dec)) {
            throw new NumberFormatException("Invalid decimal part in number: " + str);
        }


        // Handle type-suffixed numbers
        if (!Character.isDigit(lastChar) && lastChar != '.') {
            String numeric = str.substring(0, str.length() - 1);
            // Corrected: Apply blank check to numeric part as well
            if (isBlank(numeric)) {
                 throw new NumberFormatException("A blank string is not a valid number when stripped of type suffix.");
            }
            // Corrected: Apply double-dash check to numeric part
            if (numeric.startsWith("--")) {
                return null; // Consistent with original behavior for "--"
            }

            // Corrected: exp is part of the numeric string up to the suffix, if present
            if (expPos > -1 && expPos < str.length() - 1) { // Check if exp exists before suffix
                exp = str.substring(expPos + 1, str.length() - 1); // Exponent after 'e'/'E' before suffix
            } else {
                exp = null;
            }

            // Check if mantissa and exponent are all zeros (for float/double precision check)
            boolean allZeros = isAllZeros(mant) && isAllZeros(exp); // Only relevant for float/double

            switch (lastChar) {
                case 'l':
                case 'L':
                    // Numeric string should not have decimal or exponent for a Long
                    if (dec != null || exp != null || !isValidSignedDigits(numeric)) {
                        throw new NumberFormatException(str + " is not a valid Long number format.");
                    }
                    try {
                        return createLong(numeric);
                    } catch (NumberFormatException nfe) {
                        // Too big for a long, try BigInteger
                    }
                    return createBigInteger(numeric);

                case 'f':
                case 'F':
                    try {
                        Float f = createFloat(numeric);
                        // Corrected: Check against 0.0F for Float type
                        if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                            return f;
                        }
                    } catch (NumberFormatException nfe) {
                        // ignore and try next type
                    }
                    // $FALL-THROUGH$
                case 'd':
                case 'D':
                    try {
                        Double d = createDouble(numeric);
                        // Corrected: Check against 0.0D for Double type
                        if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                            return d;
                        }
                    } catch (NumberFormatException nfe) {
                        // ignore and try next type
                    }
                    try {
                        return createBigDecimal(numeric);
                    } catch (NumberFormatException e) {
                        // ignore and throw default exception if no type matches
                    }
                    // $FALL-THROUGH$
                default:
                    throw new NumberFormatException(str + " is not a valid number with recognized suffix.");
            }
        } else { // No type suffix, infer type based on content
            // Corrected: exp is the part after 'e'/'E' up to the end of the string
            if (expPos > -1) {
                exp = str.substring(expPos + 1);
            } else {
                exp = null;
            }

            if (dec == null && exp == null) {
                // Must be an int, long, or BigInteger
                if (!isValidSignedDigits(str)) { // Ensure it's purely digits or signed digits
                    throw new NumberFormatException(str + " is not a valid integer format.");
                }
                try {
                    return createInteger(str);
                } catch (NumberFormatException nfe) {
                    // Try Long if Integer fails
                }
                try {
                    return createLong(str);
                } catch (NumberFormatException nfe) {
                    // Try BigInteger if Long fails
                }
                return createBigInteger(str);

            } else {
                // Must be a float, double, or BigDecimal
                boolean allZeros = isAllZeros(mant) && isAllZeros(exp);
                try {
                    Float f = createFloat(str);
                    if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                        return f;
                    }
                } catch (NumberFormatException nfe) {
                    // Try Double if Float fails
                }
                try {
                    Double d = createDouble(str);
                    if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                        return d;
                    }
                } catch (NumberFormatException nfe) {
                    // Try BigDecimal if Double fails
                }
                return createBigDecimal(str);
            }
        }
    }

public static int indexOfAnyBut(String str, String searchChars) {
    if (StringUtils.isEmpty(str) || StringUtils.isEmpty(searchChars)) { // Use fully qualified name for clarity and consistency
        return StringUtils.INDEX_NOT_FOUND;
    }
    int strLen = str.length();
    for (int i = 0; i < strLen; i++) {
        char ch = str.charAt(i);
        // If the character 'ch' is NOT found in 'searchChars'
        if (searchChars.indexOf(ch) < 0) {
            return i;
        }
    }
    // No character in 'str' was found that is NOT in 'searchChars'
    return StringUtils.INDEX_NOT_FOUND;
}

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }

        final String trimmedStr = str.trim(); // Always trim input to handle whitespace

        if (StringUtils.isBlank(trimmedStr)) {
            throw new NumberFormatException("A blank or whitespace-only string is not a valid number");
        }

        // Specific handling for "--"
        if (trimmedStr.startsWith("--")) {
            // This is an unusual case. Assuming it's an intended special return.
            // If it's meant to be an error, throw new NumberFormatException.
            return null;
        }

        // Hexadecimal parsing
        if (trimmedStr.startsWith("0x") || trimmedStr.startsWith("-0x") || trimmedStr.startsWith("0X") || trimmedStr.startsWith("-0X")) {
            final String hexPrefix = trimmedStr.substring(0, trimmedStr.indexOf('x') + 1);
            final String hexValue = trimmedStr.substring(hexPrefix.length());

            if (StringUtils.isBlank(hexValue)) {
                throw new NumberFormatException(trimmedStr + " is not a valid hexadecimal number (no digits after prefix).");
            }

            int hexDigits = hexValue.length();
            if (trimmedStr.startsWith("-")) {
                // If it's negative, the '-' is part of the overall number, not counted in hexDigits.
                // The 'hexDigits' should just be the count of actual hex characters.
            }

            // Determine if it's too large for Integer, then Long.
            // Integer.decode and Long.decode handle the 0x / -0x prefix internally.
            try {
                return createInteger(trimmedStr);
            } catch (final NumberFormatException e) {
                // Ignore, likely too large for Integer.
            }

            try {
                return createLong(trimmedStr);
            } catch (final NumberFormatException e) {
                // Ignore, likely too large for Long.
            }

            // If it's too large for Long, try BigInteger.
            return createBigInteger(trimmedStr);
        }

        // Find decimal point and exponent
        final int decPos = trimmedStr.indexOf('.');
        // Correctly find the exponent character (case-insensitive)
        int expPos = Math.max(trimmedStr.indexOf('e'), trimmedStr.indexOf('E'));

        String mantissa; // Part before decimal or exponent
        String decimalPart; // Part after decimal, before exponent
        String exponentPart; // Part after exponent

        if (expPos > -1) { // Found an exponent
            if (expPos == 0) { // Exponent cannot be at the very beginning
                throw new NumberFormatException(trimmedStr + " is not a valid number (exponent at start).");
            }
            if (expPos == trimmedStr.length() - 1) { // Exponent cannot be at the very end
                 throw new NumberFormatException(trimmedStr + " is not a valid number (exponent at end).");
            }
            exponentPart = trimmedStr.substring(expPos + 1);
            if (decPos > -1 && decPos < expPos) { // Decimal exists before exponent
                mantissa = trimmedStr.substring(0, decPos);
                decimalPart = trimmedStr.substring(decPos + 1, expPos);
            } else if (decPos > expPos) { // Decimal appears after exponent, invalid
                throw new NumberFormatException(trimmedStr + " is not a valid number (decimal after exponent).");
            } else { // No decimal before exponent
                mantissa = trimmedStr.substring(0, expPos);
                decimalPart = null;
            }
        } else { // No exponent
            exponentPart = null;
            if (decPos > -1) { // Found a decimal
                mantissa = trimmedStr.substring(0, decPos);
                decimalPart = trimmedStr.substring(decPos + 1);
            } else { // No decimal
                mantissa = trimmedStr;
                decimalPart = null;
            }
        }

        // Check for specific type suffixes (l, L, f, F, d, D)
        final char lastChar = trimmedStr.charAt(trimmedStr.length() - 1);
        final String numericValueWithoutSuffix;
        boolean hasSuffix = false;

        if (!Character.isDigit(lastChar) && lastChar != '.') {
            numericValueWithoutSuffix = trimmedStr.substring(0, trimmedStr.length() - 1);
            hasSuffix = true;

            // Re-evaluate mantissa, decimalPart, exponentPart for the numericValueWithoutSuffix
            // This is important because the suffix changes the structure.
            final int decPosNoSuffix = numericValueWithoutSuffix.indexOf('.');
            final int expPosNoSuffix = Math.max(numericValueWithoutSuffix.indexOf('e'), numericValueWithoutSuffix.indexOf('E'));

            String mantissaNoSuffix;
            String decimalPartNoSuffix;
            String exponentPartNoSuffix;

            if (expPosNoSuffix > -1) {
                exponentPartNoSuffix = numericValueWithoutSuffix.substring(expPosNoSuffix + 1);
                if (decPosNoSuffix > -1 && decPosNoSuffix < expPosNoSuffix) {
                    mantissaNoSuffix = numericValueWithoutSuffix.substring(0, decPosNoSuffix);
                    decimalPartNoSuffix = numericValueWithoutSuffix.substring(decPosNoSuffix + 1, expPosNoSuffix);
                } else {
                    mantissaNoSuffix = numericValueWithoutSuffix.substring(0, expPosNoSuffix);
                    decimalPartNoSuffix = null;
                }
            } else {
                exponentPartNoSuffix = null;
                if (decPosNoSuffix > -1) {
                    mantissaNoSuffix = numericValueWithoutSuffix.substring(0, decPosNoSuffix);
                    decimalPartNoSuffix = numericValueWithoutSuffix.substring(decPosNoSuffix + 1);
                } else {
                    mantissaNoSuffix = numericValueWithoutSuffix;
                    decimalPartNoSuffix = null;
                }
            }

            // Determine if the *parsed numeric part* (without suffix) consists of all zeros.
            // This is used for precision checks later.
            final boolean allZerosNumericPart = isAllZeros(mantissaNoSuffix) && isAllZeros(exponentPartNoSuffix) && isAllZeros(decimalPartNoSuffix);

            switch (lastChar) {
                case 'l':
                case 'L':
                    // Longs cannot have decimal points or exponents.
                    if (decimalPartNoSuffix != null || exponentPartNoSuffix != null || !isDigits(numericValueWithoutSuffix.replace("-", ""))) {
                        throw new NumberFormatException(trimmedStr + " is not a valid Long number.");
                    }
                    try {
                        return createLong(numericValueWithoutSuffix);
                    } catch (final NumberFormatException nfe) {
                        // Too big for a long, try BigInteger
                        return createBigInteger(numericValueWithoutSuffix);
                    }
                case 'f':
                case 'F':
                    try {
                        final Float f = createFloat(numericValueWithoutSuffix);
                        // Check for precision loss: if it became infinite or 0.0 from a non-zero string
                        if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZerosNumericPart)) {
                            return f;
                        }
                    } catch (final NumberFormatException nfe) {
                        // Ignore, try next larger type
                    }
                    // Fall through to Double if Float fails or loses precision
                case 'd':
                case 'D':
                    try {
                        final Double d = createDouble(numericValueWithoutSuffix);
                        // Check for precision loss: if it became infinite or 0.0 from a non-zero string
                        if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZerosNumericPart)) {
                            return d;
                        }
                    } catch (final NumberFormatException nfe) {
                        // Ignore, try next larger type
                    }
                    // If Double fails or loses precision, fall through to BigDecimal
                    try {
                        return createBigDecimal(numericValueWithoutSuffix);
                    } catch (final NumberFormatException e) {
                        // If BigDecimal also fails, then it's truly not a valid number.
                        throw new NumberFormatException(trimmedStr + " is not a valid floating point number.");
                    }
                default:
                    throw new NumberFormatException(trimmedStr + " is not a valid number (unrecognized suffix '" + lastChar + "').");
            }
        } else { // No type suffix, or suffix is a digit/period (which means no suffix)
            // Determine if the *original* string (trimmed) consists of all zeros.
            final boolean allZerosOriginal = isAllZeros(mantissa) && isAllZeros(exponentPart) && isAllZeros(decimalPart);

            if (decimalPart == null && exponentPart == null) {
                // Must be an int, long, BigInteger
                try {
                    return createInteger(trimmedStr);
                } catch (final NumberFormatException nfe) {
                    // Ignore, likely too large for Integer.
                }
                try {
                    return createLong(trimmedStr);
                } catch (final NumberFormatException nfe) {
                    // Ignore, likely too large for Long.
                }
                return createBigInteger(trimmedStr); // If Long fails, it must be BigInteger or malformed.
            } else {
                // Must be a float, double, BigDecimal
                try {
                    final Float f = createFloat(trimmedStr);
                    // Check for precision loss: if it became infinite or 0.0 from a non-zero string
                    if (!f.isInfinite() && !(f.floatValue() == 0.0F && !allZerosOriginal)) {
                        return f;
                    }
                } catch (final NumberFormatException nfe) {
                    // Ignore, try next larger type
                }
                try {
                    final Double d = createDouble(trimmedStr);
                    // Check for precision loss: if it became infinite or 0.0 from a non-zero string
                    if (!d.isInfinite() && !(d.doubleValue() == 0.0D && !allZerosOriginal)) {
                        return d;
                    }
                } catch (final NumberFormatException nfe) {
                    // Ignore, try next larger type
                }
                return createBigDecimal(trimmedStr); // If Double fails, it must be BigDecimal or malformed.
            }
        }
    }

public static String random(int count, int start, int end, boolean letters, boolean numbers,
                                char[] chars, Random random) {
        // --- Robustness Omissions & Input Validation ---
        if (count < 0) {
            throw new IllegalArgumentException("Requested random string length " + count + " is less than 0.");
        }
        if (count == 0) {
            return "";
        }
        if (random == null) {
            throw new IllegalArgumentException("Random instance cannot be null.");
        }

        // Determine the effective character source and range
        int effectiveStart = start;
        int effectiveEnd = end;
        char[] charSource = chars;

        if (charSource != null) {
            if (charSource.length == 0) {
                throw new IllegalArgumentException("The 'chars' array cannot be empty if provided.");
            }
            // When chars array is provided, 'start' and 'end' define the range within this array.
            // If start/end are 0, use the full array.
            if (effectiveStart == 0 && effectiveEnd == 0) {
                effectiveEnd = charSource.length;
            }
            if (effectiveStart < 0 || effectiveStart >= effectiveEnd || effectiveEnd > charSource.length) {
                throw new IllegalArgumentException("Invalid 'start' (" + effectiveStart + ") or 'end' (" + effectiveEnd + ") for the provided 'chars' array (length " + charSource.length + ").");
            }
        } else {
            // No custom chars array, use ASCII range.
            if (effectiveStart == 0 && effectiveEnd == 0) {
                if (!letters && !numbers) {
                    // Default to full Unicode Basic Multilingual Plane if no restrictions and no char array
                    // This is a more reasonable default than Integer.MAX_VALUE for char types.
                    effectiveStart = Character.MIN_VALUE;
                    effectiveEnd = Character.MAX_VALUE + 1; // exclusive
                } else {
                    // Default to common alphanumeric range
                    effectiveStart = ' ';
                    effectiveEnd = 'z' + 1; // exclusive
                }
            }
            if (effectiveStart < 0 || effectiveStart >= effectiveEnd) {
                throw new IllegalArgumentException("Invalid 'start' (" + effectiveStart + ") or 'end' (" + effectiveEnd + ") for character range generation (no 'chars' array provided).");
            }
        }

        char[] buffer = new char[count];
        int bufferIndex = 0; // Use an incrementing index for cleaner logic

        while (bufferIndex < count) {
            char ch;
            if (charSource == null) {
                // Generate character from ASCII range
                ch = (char) (random.nextInt(effectiveEnd - effectiveStart) + effectiveStart);
            } else {
                // Generate character from provided charSource array
                ch = charSource[random.nextInt(effectiveEnd - effectiveStart) + effectiveStart];
            }

            // --- Logical Mistakes: Filter and Surrogate Pair Handling ---
            // 1. Filter characters first
            boolean isValidChar = true;
            if (letters && !Character.isLetter(ch)) {
                isValidChar = false;
            }
            if (numbers && !Character.isDigit(ch)) {
                isValidChar = false;
            }
            // If both letters and numbers are false, any character is valid (unless chars array restricts it)
            if (!letters && !numbers) {
                // No additional filtering needed for 'letters'/'numbers'
            }

            if (isValidChar) {
                // 2. Handle surrogate pairs correctly
                // High surrogate range: 0xD800 to 0xDBFF (55296 to 56319)
                // Low surrogate range:  0xDC00 to 0xDFFF (56320 to 57343)

                if (Character.isHighSurrogate(ch)) { // 0xD800 to 0xDBFF
                    // If a high surrogate is generated, we need to ensure there's space for a low surrogate
                    if (bufferIndex + 1 < count) { // Check if there's space for two characters
                        buffer[bufferIndex++] = ch;
                        // Generate a random low surrogate (0xDC00 to 0xDFFF)
                        buffer[bufferIndex++] = (char) (Character.MIN_LOW_SURROGATE + random.nextInt(Character.MAX_LOW_SURROGATE - Character.MIN_LOW_SURROGATE + 1));
                    }
                    // If no space, effectively skip this high surrogate and try again for a valid char.
                    // This means bufferIndex won't increment, and the loop will retry the same slot.
                } else if (Character.isLowSurrogate(ch)) { // 0xDC00 to 0xDFFF
                    // If a low surrogate is generated, we need to ensure there's space for a high surrogate
                    if (bufferIndex + 1 < count) { // Check if there's space for two characters
                        // Generate a random high surrogate (0xD800 to 0xDBFF)
                        buffer[bufferIndex++] = (char) (Character.MIN_HIGH_SURROGATE + random.nextInt(Character.MAX_HIGH_SURROGATE - Character.MIN_HIGH_SURROGATE + 1));
                        buffer[bufferIndex++] = ch;
                    }
                    // If no space, effectively skip this low surrogate and try again for a valid char.
                } else if (ch >= 0xFDD0 && ch <= 0xFDEF || (ch & 0xFFFE) == 0xFFFE) {
                    // Non-characters: U+FDD0-U+FDEF and any U+xxFE, U+xxFF
                    // These should generally not be generated in random strings. Skip and retry.
                } else {
                    // Regular character or valid surrogate pair part already handled.
                    buffer[bufferIndex++] = ch;
                }
            }
            // If isValidChar is false, or if a surrogate was generated without space, bufferIndex
            // does not increment, and the loop re-tries for the current bufferIndex.
        }
        return new String(buffer);
    }

public static String random(int count, int start, int end, boolean letters, boolean numbers,
                                char[] chars, Random random) {
        if (count < 0) {
            throw new IllegalArgumentException("Requested random string length " + count + " is less than 0.");
        }
        if (count == 0) {
            return "";
        }

        if (random == null) {
            random = RANDOM; // Use default random instance
        }

        int actualStart = start;
        int actualEnd = end;

        // Determine the character range if chars array is not provided
        if (chars == null) {
            if (start == 0 && end == 0) {
                if (!letters && !numbers) {
                    actualEnd = Character.MAX_VALUE + 1; // All BMP characters
                    actualStart = 0;
                } else {
                    actualEnd = 'z' + 1; // ASCII printable chars from space to z
                    actualStart = ' ';
                }
            } else if (start > end) {
                throw new IllegalArgumentException("Start (" + start + ") must not be greater than End (" + end + ").");
            }
